/* 平成15年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h15.committeeSessions.push(...[{"id":"h15-20031006-4","meetingId":"h15-c-settlement","date":"2003年10月6日","dateIso":"2003-10-06","committee":"決算特別委員会","time":"午前１０時０６分～午後８時２０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林副委員長","kind":"質問・要望","question":"第１項理事および理事会の設置についてです。１人当たりの質問時間は答弁時間も含めて１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお無所属委員の質問時間は答弁も含めて１０分といたします。経過時間のお知らせにつきましては、残り時間３分前に振鈴を１回、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"以上で決算統計上の数値についての説明が終わりました。 それでは、平成１４年度品川区一般会計歳入歳出決算","agenda":"以上で決算統計上の数値についての説明が終わりました。 それでは、平成１４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"石田委員","kind":"質問","question":"お伺いをしたいのは、この中で、特別区税が増、特別交付金が減、繰入金が増ということで、最終的には単年度収支が４億３,１２６万円増ということになっているわけでありますが、ここら辺のところを決算をどういうふうにと質問をすると、答えが大体、健全財政のためと返ってくるので、そこら辺のところも踏まえて、収支均衡を、標準財政規模の中で３％から５％が健全だと。","respondent":"市岡企画財政課長","answer":"先ほどご説明をしたとおり、今回の決算は３点特徴があると考えています。先ほど区民サービスのことを委員ご指摘されましたが、積極的な施策展開をしたということが第１です。","voiceIndex":17,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"事業部編制枠方式をとって初めての決算ですということがあって、執行計画などにも、各事業部からいろいろ出てくるので、企画としてはあまり赤ペンを入れませんというような以前の発言があったと思うんですが、この編制方式をとって１年間経って、今の財調の部分も含めて、事業部の方に伺うと、財調で手当とか、そういうのは企画は分かっているんだろうけれども、各事業部で本当にここまで浸透して。","respondent":"市岡企画財政課長","answer":"しかし、私どもは事業部編制枠方式をとって、財調と税、その他、一般財源が予算を編成するときの一番基本ですよということを各事業部にもご説明申し上げておりまして、予算というのは、特定財源はそのとき左右されますけれども、一般財源を中心にこれをいかに節減し。","voiceIndex":19,"id":"exchange-003"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう点で、もう１段進めていただきたいところがあります。ですから、そこら辺の点をどういうふうに踏み込んでいこうとされているのか、もう１点その点だけは伺っておきたいなと思いますし、特別区税と財調が逆転をしていったとき、基金繰入金の限度もあるわけですから、そこのレベルはどのぐらいとお考えになって基金を繰り入れていくのか、そういうところも併せてお聞きしたいと思います。","respondent":"市岡企画財政課長","answer":"そういう意味では、起債残高を今減少させておりますので、まだ基金は積極的に活用できるというふうに考えてあります。","voiceIndex":21,"id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"その点ひとつよろしくお願いします。もう１点質問をしようと考えています。確認をしたいのは、区長も、施策的にはもう箱ものはというところの部分、ほかの区営、区民も含めて、もちろん建て替えというのはあるにしても、再開発絡みで何かそこが絡んでくる、それ以外のものの箱は公営住宅としてはつくっていかないというようなお話で理解をしていいかどうかの確認が一つ。","respondent":"田村住宅課長","answer":"それと、区営住宅につきましては、現在西大井六丁目に建て替え時移管の２３区初の事業を開始しておりまして、１１月に募集し、来年の４月に入居ということで、都営住宅の移管推進を含めまして、今のところそれで計画は終了というふうに考えております。","voiceIndex":23,"id":"exchange-005"},{"speaker":"石田委員","kind":"質問","question":"これをさまざま考えていきますと、管理について、特に収納部分について新たな方法を考えていく、また、それは今後のことでもいいわけですが、例えば二社なら二社、状況の１年や２年の成果を捉えて、それでも滞納率が上がらない、また改善されたんだということであればいいわけですが、それが今度増えてきたりとか、そこら辺のところが、課長のマンパワーが及ばないところになってきたときに。","respondent":"田村住宅課長","answer":"管理戸数がこれだけ増えるということで、私を含めまして、住宅課の職員だけで対応というのはやはり限界があるだろうというふうに考えております。したがいまして、区としては平成７年に滞納整理の要綱というのを設置しています。","voiceIndex":25,"id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"その点で、全体の政策的なことを考えると、滞納の場合は欠損の部分で落とせないというのがありますね。そこの部分もどう思っていらっしゃるかというのも聞きたいけれども、その部分と、それから、入居時の一定の基準で入れちゃうんだけれども、その後の２カ月、３カ月ですぐ滞納という人もいますよね。","respondent":"田村住宅課長","answer":"不納欠損等につきましては、まだ考えておりませんけれども、退去者の未済額が３,０００万円ほどありますので、それも今後検討をする形をとらざるを得ないと、そのように考えております。","voiceIndex":27,"id":"exchange-007"},{"speaker":"嶋委員","kind":"質問","question":"私からは３点についてお伺いいたします。初めに１７０ページの職員費に関連して、退職手当金についてお伺いいたします。二つ目には、７４ページの東品川文化センターの使用についてお伺いいたします。今の品川区の職員構成をお聞きをいたしましたところ、２０歳代が１０４名、３０歳代が６５８名、４０歳代が９９０名、５０歳代は１,２３３名の職員構成とお伺いをしております。","respondent":"桑村人事課長","answer":"その意味では全体の職員、退職金を含めて、経費をどうするかというのが一つの問題になるだろうというふうに思ってあります。その意味で、そういった面も含めて、今後の計画のあり方というのをつくってまいりたいと考えています。","voiceIndex":30,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味では、基準というのは、命を賭して職務を遂行したり、功績に報いるポイント制とか、区政に対する多年の功績に報いるなどが挙げられておりますので、この制度が悪いということではないですが、そういう意味で、今回１２２名いらっしゃいますが、内訳が分かりましたら教えていただきたいと思います。それと、増額分と、平均と、最高を教えていただきたいと思います。","respondent":"桑村人事課長","answer":"そのうち今回おっしゃられました、いわゆる昇給制度に該当する基準を持っている職員が８５名おりました。そのうち付与した人数は７７名です。平均しますと、一人当たり約３３万円ぐらいです。総額ですと２,５３０万円です。最高の者が１３０万円、最低が２３万円という数字です。","voiceIndex":32,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問・要望","question":"２３区においても、豊島区、中野区なども平成１５年度の退職者から実施をしていくというお話も出ておりますので、そういう意味で、名誉昇給の制度運用と、今後のあり方に対するお考えをお聞かせいただきたいと思います。","respondent":"桑村人事課長","answer":"その意味では、すべて平等に扱うことが果たして職員のやる気をもたらすのかどうかについてはちょっと疑問を持ってありますので、その点も含めて検討をしていきたいと思ってあります。","voiceIndex":34,"id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味で、リノリュームを２枚引かなければならないんですが、大変重いもので、センターの所長にお聞きしたら、台車がありますから、それでも重いんですかという答えだったものですから、どのぐらい重いのか、私自身も運んでまいりましたら、台車といっても、ただ滑車がついているだけで、押すところもないし、２枚を巻いて台車に乗せるだけでも大変重とうあります。お伺いいたします。","respondent":"上川内生涯学習課長","answer":"東品川文化センターは、スポーツ室、軽スポーツ室もかなり広くありまして、ダンスに人気があります。今、リノリュームが重いということなので、早急に私のほうで実態を調べて検討をさせていただきたいと思いますので、よろしくお願いいたします。","voiceIndex":36,"id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ至急にやっていただきたいと思います。３人がかりでやっと１枚のリノリュームを台車に乗せるというのが、私の今回の感想でございましたので、高齢者の方はもっと大変な思いだと思いますので、大至急にやっていただきたいと思います。東京都にお伺いいたしましたら、人事委員会が今週出るですが、区のほうではそういう情報を聞いていらっしゃるか、東京都の動きを聞かせていただきたいと思います。","respondent":"桑村人事課長","answer":"その結果、私どものほうでも検討が進んでございまして、若干の偏りはありますけれども、来年４月に実施する方向で検討をしています。","voiceIndex":38,"id":"exchange-012"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひいち早く実施をしていただきたいと思います。都内でも小金井市、調布市、国分寺市の３市が今年の４月から実施をしているということもありますので、ぜひ参考にしていただいて、実施をいち早くしていただきたいと考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"区民が実際に区民料金でお借りをすると１日に１０万４００円かかるんですね。しかも、夜間の料金になりますと、どの部屋も午前中の料金の倍ということですから、区有施設の使用料としてあまりにも料金設定が高過ぎるのではないかというふうに思いまして、区民利用では午前中の利用料金と同一にするということが必要なんじゃないかというふうに思います。","respondent":"諸岡区民生活事業部副参事、太川区民生活事業部長","answer":"したがいまして、これ以上の料金設定を減額するということは、きゅりあんの運営上大変困難だと考えてございまして、現状のまま区民料金の設定をしていきたいというふうに考えております。ただ、これにつきましては、１０月２０日から３０日にかけまして、東京など世界５カ国での再編を説明していきたいということで、話が出されております。","voiceIndex":42,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"実際にアルゼンチン国債の損失は品川文化振興事業団が会計処理で何とかできるというぐらいの保留金を持っているわけですから、その辺はきちんとした趣旨に沿った考え方というのをぜひしていただきたいなというふうに思います。収入役は公益法人の会計基準の中身について知らなかったというふうに理解をしてもよろしいのかどうか、ちょっとお聞かせください。","respondent":"諸岡区民生活事業部副参事、相川収入役","answer":"この収入の目標といたしまして、運営費の３割以上を目標としておりますので、こういう数字を達成するためには現行の使用料は徴収せざるを得ないというふうに考えております。ただし、細かな会計基準のつくり方ですね、要は、国債と書いてあるものを、もっと個別な銘柄を書かなければいけない、この指摘は初めて受けたわけですから、私もその時点ではそこの部分は認識をしていなかった、こういうものです。","voiceIndex":45,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"東京都が言う、会計基準に沿って言えば、きちんとした銘柄、きちんとした金額について記載をしなければならないという、これは実際に理事として監査をする上で、極めて基本的な部分ではないかというふうに思うんですけれども、このとき指摘をされて初めてそのことに気がついたということですけれども、平成１５年度も収入役は監査をやられておりますけれども。","respondent":"相川収入役","answer":"その指摘がございましたので、現在品川文化振興事業団の財産目録の中には明確に資産の中身を個々に書いてございまして、例えば定期預金が幾ら、品川区の区債が幾ら、アルゼンチン国債が幾らと、これは指摘を受けた部分で直したもので書いてありますので。","voiceIndex":48,"id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"当時出されました区の調査報告書の中に、事業監査に主眼が置かれていて、財務監査が形式に流されやすいというふうに言っておりますけれども、そういう意味では実際には形式さえ認識をせずに監査をしていたというふうに受け止めざるを得ないところですけれども、実際に今の状況も含めまして、これから１２月に損害確定が一定程度出てきますけれども。","respondent":"濱野助役","answer":"先ほどのご答弁の中にもありましたけれども、きゅりあんの値段の設定とこの問題は全く関係ありませんし、きゅりあんの値段は使用料の設定という考えの中から出てきているものでありまして、高い利用率をいただいているということは。","voiceIndex":50,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"今の助役のお話、私は理解できなかったんです。私がお聞きしたのは、損壊確定後に区民に対して改めてこの問題について説明をしてくかどうかということをお聞きをしたんですけれども、この点をもう一度お願いいたします。","respondent":"濱野助役","answer":"品川文化振興事業団には理事会、評議委員会というものがあります。この機関を通じて物事を説明していくのが段取りだというふうに考えてあります。","voiceIndex":52,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"議事進行。と申しますのは、決算特別委員会は款別審査をやっておりまして、今日やるべきことは当初に示されておるわけでございまして、質問者の内容は品川文化振興事業団の財産運営に関することですので、直接ここに答弁者もいませんし、今日やる款別審査の対象になっていないと私は認識しておりますので、この進行について、委員長の見解を示していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"},{"speaker":"高星委員","kind":"質問","question":"議事進行。裁きがおかしいですよ。時間は残っているわけですから、図らずも彼はいいですよというような言い方、何がいいんだかわからないけれども、発言をしていたけれども、暫時でもいいから、休憩なら休憩して、残り時間もどうするのかも含めて、きちんとやってくださいよ。そうしないと話にならないよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-020"},{"speaker":"金高委員","kind":"質問","question":"初めに、歳入不納欠損額について質問をします。そして、財産収入、それから、基金運用状況等につきまして、３点ばかりお伺いしたいと思います。初めに、歳入不納欠損額の内訳という書類が出ております。併せて、３ページに国民健康保険事業会計、あるいは介護保険特別会計等がありますけれども、これらのことについてまずお示し願いたいと思います。","respondent":"松崎税務課長、太田保険年金課長","answer":"この中には差押えをして、看過処分をする、残りのものについて即時に消滅をさせるという、こういう段階でやっております。これは中立性、効率性、公平性の観点から勘案をしながら実施をするものです。執行停止、即消滅分については、国民健康保険料も、地方自治法の適用にありますので、地方税法の準用をするということで、先ほど税務課長がご説明したとおりの処理になるということで私どもはやってあります。","voiceIndex":62,"id":"exchange-021"},{"speaker":"金高委員","kind":"質問","question":"もう一つは、これについて、実際に国民健康保険ですから、区民の方々でありますので、例えば家族で払えない場合には、受けられない人数はもっと大勢いるんじゃないかと思うんですけれども、その辺はどうなんでしょうか。","respondent":"太田保険年金課長","answer":"滞納されている方につきましては、不納欠損とは別に、私ども日頃から督促、催告、あるいは短期証、資格証等を使いながら、接点を持ちながら、生活状況をお聞きして、徴収に努めているところです。","voiceIndex":65,"id":"exchange-022"},{"speaker":"金高委員","kind":"質問","question":"確かに保険料の納付、あるいは実際に保険証を使うということは別だということでありますけれども、たしか保険料を払っていなければ、今度は現金で払って、後で清算するというのが出てきたと思うんですけれども、実際にこれだけの件数、延べ件数で出ておりますけれども、２年間ということで、その部分と、こういう処分を受けて国民健康保険証そのものが使えなくなってしまったと、要するに。","respondent":"太田保険年金課長","answer":"ただし、先ほども申し上げましたように、その期間がその方の状況に応じて６カ月の短期証もあれば、一旦窓口で全額お支払いいただいて、後ほど区のほうで償還払いをすると、そういう適用になっている方もいらっしゃるです。","voiceIndex":67,"id":"exchange-023"},{"speaker":"金高委員","kind":"質問","question":"続きまして、財産収入のほうについてお伺いします。それから、売り払いということで５０.３％、これは監査報告書の１９ページにありますけれども、収入未収額が財産売払の中で計上されておりますけれども、これは財産を売り払った収入の未収額というふうになっておりますけれども、これはどうしてまだ入ってこないのか、あるいは繰り延べされているのか、その辺をお聞きしたいと思います。","respondent":"西島経理課長","answer":"財産未収の分ですけれども、これは平成４年に廃道敷地を１,４００万円余でお売りをいたしましたけれども、当初の予定では４回に分けて延納していただくという約束でございましたけれども、３回まではほぼ順調に納付されておりましたが、４回目以降になりまして。","voiceIndex":69,"id":"exchange-024"},{"speaker":"金高委員","kind":"意見","question":"そうしますと、収入としては未収額というふうになっておりますけれども、例えばこういうお金が入ってこない部分について、例えば税金を滞納した場合には延滞金とか取られますけれども、こういう場合の入ってくるお金に対して、売った代金ですので、期限までに入ってくるのは当然でしょうけれども、それが遅れた場合に何かペナルティ的な、延滞金とか何かというのはかかるのかどうか。","respondent":"西島経理課長","answer":"ご指摘のとおり、遅れますと延滞金が発生をしてまいります。","voiceIndex":71,"id":"exchange-025"},{"speaker":"金高委員","kind":"質問","question":"そうしますと、確かに税金ということで、税金の対価としての物品を売ったわけですから当然税金扱いになりますけれども、その場合の利率といいますか、細かいことですけれども、その辺の利率でもって年に何％ぐらいの滞納金がかかるのか、お示しいただければと思います。","respondent":"西島経理課長","answer":"延滞金ですけれども、税と同じですので、１３.６％というふうに記憶しています。２点目は、財産売払収入のご質問ですよね。","voiceIndex":73,"id":"exchange-026"},{"speaker":"金高委員","kind":"意見","question":"不用品売払代金１４５万円の増加によるものということで、これが減少ということになっておりますけれども、ここの表現の仕方の意味といいますか、収入の減少ということになっておりまして、代金１４５万円の増加によるものであるという、不用品の売払代金１４５万円の不用品はどういう不用品で１４５万円という数字が出たのか分かりましたら。","respondent":"小野副収入役","answer":"それが前年度に比べ、本年度は増加しているです。","voiceIndex":75,"id":"exchange-027"},{"speaker":"金高委員","kind":"質問","question":"国債というのは分かりますけれども、政府保証債は、政府が保証するということですけれども、国債と政府保証債の違いの説明と、基金ですから、それに対する利率があるし、利率については、それぞれ違うのではないかと思いますが、なぜ分けてあるのか、また、分けるに従ってどういうメリットがあるのか、その辺も含めてご説明願いたいと思います。","respondent":"小野副収入役","answer":"そのほか国債ということで、これはその時々で区のほうの基金で、例えば余裕資金がございましたときに、一番利率のいいところで運用するということがございまして、国債ですと、できるだけ短期間で２年物というようなところで。","voiceIndex":77,"id":"exchange-028"},{"speaker":"金高委員","kind":"質問・要望","question":"国債というのは、今のご答弁ですと、２年物を中心とするというような形、確かに国債はそのときの利回りによって若干の差があるわけでありますので、より高い運用方法をしていただきたいと思います。政府保証債というのは、具体的にどのぐらいの期限を中心としているのか。それから、国債に比べて利率的なものとしてどのくらいの差があるのか、あるいは同じなのか、その辺も含めてご答弁願いたいと思います。","respondent":"小野副収入役","answer":"政府保証債ですけれども、今、国民生活債券は５年債、預金保険機構債は２年債、４年債となっていますけれども、これもその時々でございまして、平成１３年に購入いたしました国民生活債券につきましては５年債で、年利０.４％。","voiceIndex":79,"id":"exchange-029"},{"speaker":"金高委員","kind":"質問","question":"品川区は基金の運用が非常に上手であるということでありますし、特に５２０億円という数字が出ております。基金というのは、私も何度か質問をさせていただきましたけれども、各家庭で言う定期預金であると。この定期預金を十二分に活用して、それぞれの施策に回っていることと思います。これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"私は６９ページの庁舎管理費負担金および７０ページの総務使用料の中の庁舎使用料等につきまして、庁舎管理全般についてお伺いをします。本年の決算と昨年の決算をそれぞれ比較をしますと、昨年と比べまして、庁舎管理費負担金が約２７％削減をされております。ほぼ同比率で庁舎使用料が約２７％削減をされております。","respondent":"西島経理課長","answer":"２点のご質問ですけれども、庁舎管理費負担金ですが、この庁舎は全国的にも数少ない総合庁舎でございまして、区、東京都、国の三者で共有しています。庁舎管理費負担金の中身ですが、大きく分けて三つございまして、この庁舎の改修修繕費に係わる部分が一つあります。","voiceIndex":83,"id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"それぞれがまた負担を軽減されているのかなというふうに思っておるわけですが、その辺も絡めてのご答弁をお願いしたいと思います。","respondent":"西島経理課長","answer":"平成１２年度で言いますと９,２７０万円余、平成１３年度では８,６４０万円、平成１４年度では８,１６０万円ということで、この間ＩＳＯの環境に対する取り組みということで、省エネルギー。","voiceIndex":85,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"庁舎管理負担金の中にそれぞれ国、都、あるいは区関連の施設等が負担をされておりますが、その中の法務局のことについてお聞かせをいただきたいと思います。このことにつきましては、特に我が党の鈴木総務委員長のもとで、この問題を常任委員会の中で積極的に取り上げられているかと思いますが、改めまして、それ以降の経過、あるいは今後の状況につきましてのご説明をお願いしたいと思います。","respondent":"西島経理課長","answer":"ただし、計画そのものは閣議決定を受けているので、簡単に白紙撤回はできない。関係団体については、２４日の午後と、２５日に説明を予定している。以上のような回答がございました。","voiceIndex":87,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"今後もこれはあまり立ち入った部分に触れてはいけないんですが、先日の総務委員会の中でも議会としてまた改めて強い意思を内閣総理大臣および法務大臣あてに伝えていこうという動きがあります。そういった観点で、今後意見書等の議論もある中で、どこまでという部分もあるかもしれませんが、今後のこの問題に対する取り組み方の決意、熱意をお聞かせをいただきたいと思います。","respondent":"本間総務部長","answer":"今後の対応ですが、今経理課長からご説明しましたとおり、当分の間延期するというだけで、これは計画を白紙撤回をしたわけではございません。","voiceIndex":89,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ歩調を合わせてお願いをしたいと思います。この問題に派生して、１点だけお伺いしたいんですが、これからＩＴ化がますます進む中で、国としましては、電子政府を構築していくという中で、先ほどご答弁にもありました、ｅジャパン計画というものの中で、登記のやりとりも電子化して、財産登記法の改正等々があって、そういう流れの中で法務局の移転が当分の間延期という形になったという背景があります。","respondent":"西島経理課長","answer":"将来的に言えば、電子申請、電子調達が進んだ形になってくれば、庁舎のあり方も当然変わってくることは考えられますけれども、その辺の推移を見ながら、庁舎のあり方について今後十分検討をしていきたいというふうに考えてあります。","voiceIndex":91,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"私は１０１ページの特別区債についてお伺いします。平成１４年度の決算と平成１３年度の決算を比較しますと、目立った違いが２点あると思うんです。公園施設の起債はミニ市場公募債の、はばたけしながわ未来債のことだと思うんですけれども、ミニ市場公募債の評判はいかがだったでしょうか。","respondent":"市岡企画財政課長","answer":"もちろん販売のほうも順調に完売をいたしまして、一人当たりの上限額を３００万円に設定したんですが、平均２１７万円ということで、購入された区民の層も、感じからすると、比較的高齢の方の資産活用ということで。","voiceIndex":94,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"今のご答弁をお伺いしますと、いいとこづくめと言いますか、区民の方の評判は物凄く良かったということは分かるんですけれども、初めてやったことに関しての反省点、それと、安心して買われたということも含めて、何か反省点がありましたら、お知らせしていただきたいと思います。","respondent":"市岡企画財政課長","answer":"あまり反省はしていないんですが、もう少しこうすれば良かったかなと思っているのは、初めてのことですので、並んだけれども買えなかったとか、あるいは買うことについて非常にご心配されている方に、非常に丁寧に説明したために、若干購入の手続が固過ぎて、金融商品ですから。","voiceIndex":96,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"それを次の質問にしようと思ったんですけれども、本当にそのように評判がよければ、今後も続けていかれると思うんですけれども、今少し課長のほうからご説明がありましたけれども、２回目をするということですけれども、２回目と１回目の差というのは何かあるのか。金額についてとか、内容についてとか、もう少し金額を増やすとか、そういうことは何かあるんでしょうか。","respondent":"市岡企画財政課長","answer":"２回目もしながわ中央公園の第２期の工事の分を予定しております。","voiceIndex":98,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"東急目黒線立体事業のほうは、たしか平成１４年度の当初予算では予定があったと思うんですけれども、このように連続立体のような大きな金額がかかる事業を起債を起こさなくても進めていけるものなんでしょうか。","respondent":"市岡企画財政課長","answer":"要は、タイミングが若干タイムラグがあるために、その間のつなぎで起債をしようかということですので、財源的にもしっかり見通しが立てられましたので、あるいはまた、先ほど来出ておりますとおり、平成１４年度決算の見通しを年度の終わり頃立てておりますけれども。","voiceIndex":100,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"東急目黒線の事業の現在の状況、それと、今後の進め方、事業自体が順調にいけるのかどうか。３番目に、この大きな事業のこれからの課題は何でしょうか。","respondent":"中島街路事業担当課長","answer":"そういった意味では、この部分が買収できないと２面４線で開業できないという事態にもなりかねませんので、このエリアの部分の買収を速やかに行いまして、来年の秋までに買収を済ましていきたいというように考えてあります。","voiceIndex":102,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"最後に、未来債についてですが、電話等がかかってきたときに、区民の方が安心ということを言っていらっしゃったというご説明がありましたけれども、これからも区債発行をするときは安心という気持ちを忘れないで、施策を実行していってください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-041"},{"speaker":"武内委員","kind":"質問","question":"私のほうからは歳入の雑入の１０１ページの放置自転車等保管料と、その下の水族館運営費収入についてお伺いします。厳しい状況もあるのかなと思いますが、今の改善されている点と、なかなか改善されない点、特に苦情等が多くて問題になっている駅がどれくらいあるかということをお聞かせください。","respondent":"奈良交通安全担当課長","answer":"したがって、午後１０時以降に帰ってきた方もスムーズに出していけるという状態になっておりますので、これからはもっと頑丈なものをやっていただいて、午後１０時以降にそこに止めている通勤。","voiceIndex":106,"id":"exchange-042"},{"speaker":"武内委員","kind":"意見","question":"放置自転車についてはいろいろご苦労があるかと思いますが、これからもしっかり、よろしくお願いしたいと思います。それから、自転車と同じで今非常に問題になっているのが、放置バイクの問題かと思いますが、今、品川区の駐輪場が幾つあって、また、その中でバイクを利用できる駐輪場が何か所あって、もし分かれば、平均で結構ですが、バイクを置ける駐輪場のバイクの利用率等をお願いいたします。","respondent":"奈良交通安全担当課長","answer":"今ご指摘のバイクの駐輪場関係ですけれども、今、区の運営している駐輪場の中でバイク置場が設置してあるのが、ターミナル駅の大井町、大崎、五反田をはじめ６駅にバイクの置場を設置しております。現在では４５０台強のスペースを設けてあります。","voiceIndex":108,"id":"exchange-043"},{"speaker":"武内委員","kind":"質問","question":"７２％の利用率ということで、バイクのスペースがあれば、利用される方が多いのかなというふうに感じまして、そういった中で今後バイクは、今６駅ということですが、駐輪場は各駅に大体あるかと思うんですが、その中で今後バイクのスペースをつくっていくような可能性のある駅が何カ所かあれば教えていただければと思います。","respondent":"奈良交通安全担当課長","answer":"そういったところについてはバイク置場が設置できるように、現在検討をしています。","voiceIndex":110,"id":"exchange-044"},{"speaker":"武内委員","kind":"提案","question":"不動前駅のほうも１０月１日から保管所のほうがオープンしたということですが、以前に八潮北の保管所のほうに自転車を持っていかれまして、取りに行って、帰ろうとしたときに、いろいろ事情はあったんでしょうけれども、パンクしておりまして、家まで引いて帰ったというような苦情があったというのを踏まえて、我が党のほうから提案ということで。","respondent":"奈良交通安全担当課長","answer":"以前にもパンクのまま持っていけないということで、その場で修理をして、感謝された事例もありますので、私どものほうも引き取りに来た方に不便を与えてはいけないということで、委託業者のほうも、努めてそういった便宜を図るように対応をしています。","voiceIndex":112,"id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"不動前駅のほうもそういった措置をよろしくお願いしたいと思います。次に、水族館の運営費収入についてですけれども、平成１３年に１０周年のリニューアルオープンをされたということで伺っておりますが、その前後の来館者数と、収入の推移についてお伺いしたいと思います。","respondent":"松代道路公園課長","answer":"平成１３年度は１億２,１００万円ということですので、２０％ほどの増です。平成１２年度で見ますと、収入が３,８００万円ということでしたので、リニューアルオープン等での収入の増があったというふうに捉えているところです。","voiceIndex":114,"id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"平成１３年に比べて平成１４年が少し利用者数が減った割に収入のほうが上がっているということ、これはおそらくリニューアルオープンのときに少し利用料を値上げされたということが功を奏しているのかなというふうに思いますけれども、いかがでしょうか。","respondent":"松代道路公園課長","answer":"今までサンシャイン水族館と利益が上がったときの取り分を、従前は区が６割、サンシャイン水族館が４割のところを、区が７割、サンシャイン水族館が３割というようなことにしましたし、一般需要費等、経費等も少し落としていただきまして。","voiceIndex":116,"id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"簡単に見直しができるというわけではないと思うんですけれども、見直しをされたということで、非常にありがたいなというふうに思っておりますが、水族館という問題、各地いろいろあると思いますが、安定して収益を上げていくというのは大変なことだと思うんですが、そのために常に新しい取り組みと、イベントとか、特別展等のそういったものが必要になってくるかと思うんですが、今後のイベント。","respondent":"松代道路公園課長","answer":"特別展ですけれども、常設展としましては、イルカショー、アシカショー、こういったものを都内唯一のショーとして継続してやっております。特別展は春、夏、冬３回程度いろいろな展示をしています。水族館は魅力ある形をどんどん打ち出していかないと来ていただけません。","voiceIndex":118,"id":"exchange-048"},{"speaker":"武内委員","kind":"意見","question":"イルカショーのほうも、前説というか、事前の注意事項で、女性の方が近づいてはいけないよとか、いろいろなことを言っているんですけれども、それに対してすべて外国語でどうのこうのというのはできないと思うんですが、例えば近づいてはいけないとかという注意事項等は英語の表示も今後必要になってくるのではないかなというふうに思いますけれども、いかがでございましょうか。","respondent":"松代道路公園課長","answer":"基本的にサービススタッフが対応するようにしておりますけれども、それに加えまして、入場の際に、利用の案内というものを配ってあります。そういう中に若干ではありますけれども、英語で明記して、それをご覧いただいてご利用いただくというようなことをとってあります。","voiceIndex":120,"id":"exchange-049"},{"speaker":"三村委員","kind":"意見","question":"たとえとして挙げられていたのが、５日間程度の休暇を取得しやすい環境を整備する。そういうようなものをぜひ盛り込んでいってほしいというようなことが挙げられていたんですけれども、また実際に民間企業の中には、５日間の限定ではありますけれども、男性の育児休業取得を義務化している企業もあります。品川区において今後男性の育児休暇取得の促進についてどのようなお考えをお持ちか、お聞かせ願います。","respondent":"桑村人事課長","answer":"ご指摘にございましたように、次世代育成支援対策推進法の中でも、品川区としての事業主の行動計画をつくっていくことになってありますので、その中で十分検討をしていきたいと思ってあります。","voiceIndex":125,"id":"exchange-050"},{"speaker":"三村委員","kind":"質問・要望","question":"職員費についてですけれども、今年品川区ではすまいるスクールが新たに１５校設置されて、全部で１９校の学校ですまいるスクールが実施されておりますけれども、すまいるスクールの専任指導員に求められている責務は、学校との関係調整、また非常勤スタッフの教育、ボランティアの募集、指導、そして子どもたちへの支援と、多岐にわたっておりますけれども。","respondent":"富田教育改革担当課長","answer":"この中では、例えばすまいるスクールの毎月の教室などを含めましたプログラムの企画ですとか、たよりの発行、また、ボランティアとの打ち合わせ、勤怠管理などのほか、先ほど出ませんでした中では、学習指導や生活指導につきまして。","voiceIndex":127,"id":"exchange-051"},{"speaker":"三村委員","kind":"質問","question":"今お伺いしたところ、専任指導員に仕事が大変集中しているかと思われます。","respondent":"富田教育改革担当課長","answer":"その学校を中心に四つのブロックに分けまして応援相談体制というものをとってきております。これらの中で事務的な作業ですとか、プログラム等々についての相談、打ち合わせ等々十分行うようにして進めているところであります。","voiceIndex":129,"id":"exchange-052"},{"speaker":"三村委員","kind":"質問","question":"今四つのブロックに分けて応援体制を組むという話だったんですけれども、その辺と少し係わってくるかと思うんですけれども、すまいるスクールが週６日開設されている一方では、専任指導員の勤務は週５日となっておりますけれども、専任指導員不在時のすまいるスクールの責任者はだれになるのか、教えていただけますでしょうか。","respondent":"富田教育改革担当課長","answer":"専任指導員が週休等で不在の折の現場の責任者は非常勤の指導員になってまいります。その非常勤の指導員が現場の責任者となりますが、さまざまな緊急時対応等々につきましては、それぞれの学校の校長、教頭等と連絡をとりながら行ってまいるということになっております。","voiceIndex":131,"id":"exchange-053"},{"speaker":"三村委員","kind":"質問","question":"今、専任指導員がいらっしゃらないときには非常勤の方が現場の責任者となるということだったんですけれども、非常勤の職員に対してどのような研修を行っているのか、もし採用段階で非常勤職員に対しての研修が行われているようでしたら、どういった研修が行われているのか、教えていただけますでしょうか。","respondent":"富田教育改革担当課長","answer":"非常勤指導員への研修ですが、非常勤指導員は任用時の発令の折にすまいるスクールの説明ですとか、非常勤職員の心構え等々について、時間を設けて講義を行っております。","voiceIndex":133,"id":"exchange-054"},{"speaker":"三村委員","kind":"提案","question":"現在のすまいるスクールの専任職員体制、専任指導員１人でこのまま続けていくお考えかと思いますけれども、現在の体制のままですと、子どもたちに関する情報ですとか、すまいるスクールで培われた技術というのが、専任職員１人という体制では失われていくかと思います。正規職員の増員も含めたケアスタッフの配置や、事務作業専任スタッフの配置を提案いたしますが、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"事務の専任スタッフ等々専門の配置をする考えはございません。ただし、それぞれ現在におきましても非常勤の指導員も勉強会ですとか、教室ですとか、それぞれ事務等の役割を分担しながら行ってきているところです。","voiceIndex":135,"id":"exchange-055"},{"speaker":"三村委員","kind":"質問","question":"保護者のニーズとしては、子どもたちの心のケア、特に低学年の児童に対する心のケアというものをぜひ充実させていってほしいということがあるかと思いますけれども、その点についてもお答え願えますでしょうか。","respondent":"富田教育改革担当課長","answer":"そういう意味では、現在も十分そういった小学校の低学年も含めました児童のケアに当たっておりますが、今後とも努めてまいりたいと考えています。","voiceIndex":137,"id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"私は１７０ページ、職員費についてお伺いしたいと思います。一般質問で南議員がサービス残業の問題で質問をいたしました。こうした中で、改めて伺いたいんですけれども、厚生労働省がこうした通達とか要綱、一連の通達の関係はご存じでしょうか。もう一つ、サービス残業そのものは労働基準法違反というふうに言われておりますけれども、そこのサービス残業についてのご認識について伺いたいと思います。","respondent":"桑村人事課長","answer":"基本的な意味では、サービス残業はないだろうというふうに思ってあります。お話の中で、一般的なお話という意味でのお話は承ってありますけれども、区においてはないというふうに認識しています。","voiceIndex":140,"id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"一般質問のときも取り上げたんですけれども、９月１６日の「さけび」を紹介したんですけれども、ここでは保育をしながらではできないので、持ち帰ってやっているとか、そういう実態が告発されているわけです。これについては調査しないということだったんですけれども、私は改めて現状把握をお願いしたいと思うんですけれども、この認識をお願いしたいと思います。そこら辺のところはどうでしょうか。","respondent":"金子保育課長","answer":"超過勤務に関しての何点かのお尋ねですが、本会議でも福祉事業部長がご答弁申し上げたとおり、私どもとしましては、サービス残業があるというふうな認識はしておりませんし、超過勤務、これは先ほど人事課長がお答え申し上げたとおり、命令権者が命令して。","voiceIndex":142,"id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"フロッピーディスクでなくて、メールでと、実際にそういうことを指導しているという話ですけれども、それはどういう内容での指導なのか、改めてお伺いしたいと思います。事前命令が原則だと。そこのところの見解を伺いたいと思います。２,０００時間というのは、通常、常勤職員何人分に当たる労働時間になるか、お伺いしたいと思います。","respondent":"田中情報システム課長、桑村人事課長","answer":"そういうことで非常に危険な行為ですので、家からパソコンを持ってきてＬＡＮにつないだり、もしくは媒体等を持ち込むことを禁止したということが、８月の段階での指示の内容です。その意味で、認識が違うということだと思います。先ほどおっしゃられました、いわゆる２,０００時間というのは、時間数にすれば、大体１人分というようなことになろうかと思います。","voiceIndex":144,"id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"１人分なんですよね。それと、先ほど自宅で情報収集をやることがあると、そういうことというのは、それをまた役所に持ち込むということは、自宅でそういう仕事をやっているということをちゃんと区のほうも認識しているということではないですか。そもそも１人分の仕事だったら、１人分の専任職員を配置すべきではないかと私は思うんですけれども、そこのところはいかがでしょうか。","respondent":"金子保育課長","answer":"各園によって違うという再三のお尋ねがありますけれども、これについては、各園なりの取り組みでそれぞれ工夫してやるようにというふうに指示しておりますので。","voiceIndex":147,"id":"exchange-060"},{"speaker":"宮崎委員","kind":"意見","question":"時間がないので、最後意見を言いたいと思うんですけれども、急な残業とか、一時的に集中するとか、そういうのはあり得ると思うんですけれども、年中ずっとＩＳＯマニュアルづくりに係わるんですよ。それは残業でやるものではないんですよね。本会議でも、例えば午睡時間にやりますと言うけれども、その時間に子どもの打ち合わせができない、支障が出ているということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":149,"id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私は成果報告書の７０ページ、１０款使用料及び手数料から、総務使用料、区民保養所使用料、９９ページの１７款諸収入、６項雑入の中から国民年金印紙、雑入、もう１点、１０１ページ、１８款特別区債について、３点か４点にまとめてお聞きしたいと思います。１点目に、先ほどもちょっと質問に出ておりましたが、特別区債についてお聞きをしたいと思います。その辺についてお聞きしたい。","respondent":"市岡企画財政課長","answer":"この辺はよく説明できるように心がけてまいります。","voiceIndex":151,"id":"exchange-062"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"国民年金については今朝ほどご説明をいただいたので、その分の残った印紙ということになると思うんですけれども、今期の３億６,７００万円ぐらいの印紙売払代金が出ておりますが、昨年は５,２００万円ぐらい売り捌き手数料が入っていると思うんですが、この分が今期には１カ月分の中で手数料が何で出てこないのか、その辺を教えてください。","respondent":"市岡企画財政課長、太田保険年金課長","answer":"ミニ市場公募債については、今後も長く活用していき、区民の方に信頼される債券にしなければいけませんので、続けて十分な説明をするように心がけてまいります。その結果、従来区が保険料の印紙検認事務を実施をしてございましたが、平成１４年４月からこれが国へ移管をされたです。","voiceIndex":153,"id":"exchange-063"},{"speaker":"鈴木（真）委員","kind":"質問","question":"よく理解できなかったので、最後の一カ月分の手数料は入ってくるべきではないかなということでお聞きしたんですが。","respondent":"太田保険年金課長","answer":"その段階で手数料が平成１３年度で収入済みです。それから、私が申し上げたのは、平成１４年度で残りました１億４,２００万円ほどの中に、事前に平成１３年度で手数料をもらっていましたので、その分を引かれた残りの１億４,０００万円を国で買い戻したと、こういう意味です。","voiceIndex":156,"id":"exchange-064"},{"speaker":"鈴木（真）委員","kind":"質問","question":"分かりました。５,２００万円ぐらい毎年売り捌き手数料が入っていた分が、ある程度資金が寝ていましたけれども、逆に言うと、５,２００万円の収入がなくなってくるという面も、区にとっては発生してくると思うんです。国民年金の担当者の方の人件費的なものは、今まで区が負担していたということでよろしいんですか。５,０００万円ぐらいの収益が減ってしまう部分をどう考えたらいいのかということで。","respondent":"太田保険年金課長","answer":"したがいまして、その中に国のほうの考え方としては、人件費を込みの事務費交付金で交付をしているです。","voiceIndex":158,"id":"exchange-065"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区としては５,０００万円ぐらいが利益が上がらなくなってくる部分が発生してくるのではないか。それは今まで印紙を抱えていた分がうまく運用することによって、その５,０００万円ぐらいがカバーできるのかなという点で、歳入全体という意味で考えたときどうなるかなということでお答えをいただきたいと思います。","respondent":"太田保険年金課長","answer":"売り捌き手数料につきましては、国のほうから印紙を買って、それを売り捌くという関係での事務手数料という意味合いですので、平成１４年４月以降区ではそういう事務を取り扱ってございませんので、そういう面では当然と言いますか、そういう結果になるです。","voiceIndex":160,"id":"exchange-066"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっと意味が違うんですけれども、区の資金、持っていたお金が、それを運用して、逆に言うと、運用したことによって５,０００万円ぐらい収益が入っていたはずですね。それが印紙を抱えていたお金が今度は別に普通預金なり、基金なりどこかに残しておける部分で運用がきいていくのかなという、そういう聞き方なんです。","respondent":"市岡企画財政課長","answer":"国民年金の事務費については、人件費に充当されていた分については、事務が変わった時点で職員数も大きく削減しておりますので、厳密に考えるといろいろプラスマイナスあろうかと思いますが、基本的には充足しているというふうに考えてあります。","voiceIndex":162,"id":"exchange-067"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"分かったような、まだ理解し切れていないような部分もあるんですけれども、この点は後でまたちょっと確認はさせていただきたいと考えています。区民保養所の件でもう１点聞かせていただきたいと思います。三つの保養所から約６,５００万円ぐらい収入が入っていますが、その中で、利用者数とか、空室率、その辺がどんなバランスになっているかをまずお答えをいただきたいと思います。","respondent":"長田区民課長","answer":"それぞれ部屋の稼働率にしてみれば、品川荘で８０％程度、暖景苑が６０％、箱根荘につきましては６２％、こういう状況になってあります。","voiceIndex":164,"id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ちょっと歳出も絡んでしまうかもしれないんですが、暖景苑ですと、区から委託している部分もあると思うんですが、暖景苑自体の会社としての採算性というものは、区として把握しているんでしょうか。","respondent":"長田区民課長","answer":"年間の委託料、平成１４年度決算で言いますと１億１,３００万円余ですけれども、この中で十分運営はやっていけるものというふうに私どものほうは理解をしています。","voiceIndex":166,"id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"質問","question":"逆の意味で聞いたんですけれども、やっていけるかではなくて、委託料で本当に合っているんですかという聞き方の意味だったんですが、費用対効果が本当に合っているのかどうか、そこら辺をどう判断するかという点でお聞きしたいんです。","respondent":"長田区民課長","answer":"私ども保養所につきましては、区が保養所を持つ意義も含めまして、根本的なところで今後どうしていくのかという部分についての検討を始めたところです。いずれ追って経過等につきましてもお知らせをしたい、このように考えてあります。","voiceIndex":168,"id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"時間がなくなったので、明日総務費でもう一度聞かせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-071"},{"speaker":"土井委員","kind":"質問・要望","question":"私は歳入歳出に係わる特別区債関連、公債費関連で１点と、議会費関係で１点お聞かせをいただきたいと考えています。最初に議会費のほうを聞かせてください。これからも、その意味ではどのように対処をしていくのか、どのようなものを、どんな形でというのは、前にも伺っておりますけれども、この際もう一度お聞かせをいただきたいというふうに思います。","respondent":"福田区議会事務局長、市岡企画財政課長","answer":"その頻度でありますが、原則としては月１回程度でありますが、ただし緊急を要するもの等につきましては随時行っているという状況です。以上の年間委託経費は５０万４,０００円です。これからなんですが、先ほど来申し上げているとおり、どういう起債、どういう適債事業が未来債にふさわしいかということをいろいろ研究していきまして、委員もおっしゃられたとおり、次の世代に広く区民サービスが提供できるような施設。","voiceIndex":172,"id":"exchange-072"},{"speaker":"土井委員","kind":"質問・要望","question":"その中で私どもも要望をいろいろしておりますけれども、私どもの要望は自分に要望しているような変な話ですけれども、例えば検索システムをどうしたらいいんだろうかなと、いろいろなことを考えながら発言等をしているわけですけれども、そういう今後の予定も含めまして、仕組みなり、システムの変更を図っていくようなこと等も、５０万円なり何なりということでできるのかどうかわかりませんけれども。","respondent":"福田区議会事務局長、市岡企画財政課長","answer":"その点を踏まえて申し上げますと、５０万４,０００円の中だけでこれを対応することは難しゅうありますが、しかし、かと言って、また５０万円とか４０万円とか。１点だけ、義務教育施設については、現在国庫負担との関係で、ややハードルがありますので、これは今後規制緩和でいろいろ変わっていくかと思いますので、その辺も視野に入れて検討をしていきたいと考えています。","voiceIndex":175,"id":"exchange-073"},{"speaker":"土井委員","kind":"質問・要望","question":"インターネット関連の議会の関係ですが、いろいろ要望の中に、検索システムが、議長がしゃべった、何がしゃべったというのが、ばらばらに出てくるのを何とか一体としてとれないものかなというふうなこと等が出ておりますので、そこら辺も含めまして、ご検討をいただくということになっているんだろうなというふうに思っておりますので、そのことを付言をして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"その経過ですね、当初の計画設定に対して、どういう事業であったのかということをもう少し見やすいようにしていただきたい。その方法としては、先ほど口頭でお話をされていましたが、昨年度と比べて何％増減という形でおっしゃっていましたが、それをここの中にぜひ入れていただきたいということで、意見と同時に、ご質問をまずしたいと思います。","respondent":"小野副収入役","answer":"決算書については、予算に対してどれだけの執行なり、収入があったかという数値の諸表ですので、一応決算を数値として表しているというものです。","voiceIndex":180,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問・要望","question":"数値を入れてくださいということです。成果報告書の１７０ページの職員費について質問をいたします。ただ、平成１５年度の予算等を見ましても、民生職員費、職員費全体的に下がったということをおっしゃっていますが、これは詳細のほうが明確にされていないところもありますので、ぜひ教えていただきたいんですけれども、特に夜間、延長保育をするにあたりまして、どれだけの職員費がかかっているのか。","respondent":"小野副収入役、金子保育課長","answer":"ですから、今後説明の中でできるだけ分かりやすいような形で説明をさせていただきたいと思います。２２時までの夜間保育をしている園には２名を増配置する、こういうことを基本的な考え方として配置しております。各園におきましては、それぞれ夜間においての子どもの数は違っております。","voiceIndex":182,"id":"exchange-076"},{"speaker":"西本委員","kind":"意見","question":"細かいところはこの席では問いませんけれども、夜間、延長保育、これは保育全体が国、都、区のほうの補助がかなり出ているという、それで運営されていると思うんですが、夜間、延長保育について、区のほうの持ち出し金というのは年々増えていっているのかどうか、そこをお聞かせください。","respondent":"金子保育課長","answer":"延長、夜間保育についての区の持ち出しというお尋ねですけれども、先ほども申し上げたとおり、増配置分についてはそのような配置をしておりますが、配置された職員の中でどういうふうに、私ども全部で１０パターンのシフトがありますが。","voiceIndex":185,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"今まで事業を拡大されてきた中で、職員費というのは変わっていないという理解でよろしいのでしょうか。そうしますと、夜間までに時間を延ばしている、それで２０時半までの延長する場合には１人、それから２２時までは２人をシフトさせているということは、平日のところの職員の数というのは減っているというふうに理解するんですが、そういう形でよろしいのでしょうか。","respondent":"金子保育課長","answer":"全体の職員数との絡みがありますので、その辺からご説明申し上げたいと思います。私どもは過去保育士の定数については見直しをしてまいりました。現在の定数につきましては、平成１０年度から現在の定数になっております。","voiceIndex":187,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、必然的に１０年ぐらい経つと、当然退職者が増えるわけですから、その場合の職員の扱いをどうされていくのか、若干進んでいるんじゃないかなというところの情報では、アウトソーシング、これは民間給食代行でもアウトソーシングの一部ではないかなというふうに思っているんですけれども、今後の職員の体制をどういうふうに考えられているのかをお聞かせください。","respondent":"金子保育課長","answer":"私どもとしましては、ご指摘のとおり、何年か先についてはかなりの数の定年退職者が増えるというふうな見込みは持ってあります。現在のところは毎年職員が退職しておりますので、その分について若干の見通しを持ちつつ、ここ２年採用し始めたところです。","voiceIndex":189,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"今後経過を見ながら採っていくということというふうに理解をしたわけですけれども、一つ、その中で、給食代行についてですけれども、これも退職不補充ということで、給食の代行を民間のほうにお願いしているという状況だと思うんですが、これを代行にしたために人件費というところにおいてどういう変動になっているんでしょうか。","respondent":"金子保育課長","answer":"これまでの調理代行の契約額は総額で２億９,０００万円余というふうになっておりますが、この分、正規の職員を置いた場合の職員費につきましては、約６億６,０００万円の人件費になりますので、そういう意味では５０％をかなり切るということで。","voiceIndex":191,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"給食代行になって何年か過ぎていようかと思うんですが、契約をしているところ等々、人件費ということなのか、契約金という形では全体ではないと思うんですけれども、人件費等々が上がったのでというような形での契約金の変動というのはあるんでしょうか。それとも当初の契約どおりに推移しているというふうに理解してよろしいのでしょうか。","respondent":"金子保育課長","answer":"平成１２年度から調理代行を導入しておりますが、若干金額が変更しているところも何カ所かあります。それの主な理由といたしましては、先ほど委員のご指摘がありましたとおり、延長、夜間保育を拡大している。","voiceIndex":193,"id":"exchange-081"},{"speaker":"西本委員","kind":"意見","question":"最後に、区の負担率、保育関係、保育料、学童保育クラブもそうですけれども、保育料といいますと、大体人件費に連動していくという形ですが、今後保育料という形で全体的に見直し等々は考えられているのか、東京都、国との補助金の変動ですね、これからどうなるかわからないという現状も踏まえていきますと、そこはどのような考え方でこれから進められていこうとしているのか、お聞かせ願いたいと思います。","respondent":"金子保育課長","answer":"これが当然未来永劫この保育料でいくということはあり得ないと考えていますので、適切に見直しはどこかの時点でしていかなければならないというふうに考えております。","voiceIndex":195,"id":"exchange-082"},{"speaker":"西本委員","kind":"意見","question":"保育料については今後見直していくということで、最後に意見も入りますけれども、夜間、延長保育というのが、成果報告書の中を見ますと、夜間については２２時までは区立でも０.６％という現状もありますので、そこら辺が８園という、私立も含めますと９園ありますので、そこの設置状況も踏まえて、全体的にどういう人件費をしていくのか、アウトソーシングを含めながら、保育の内容を落とさずに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-083"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは１点お伺いをします。区有施設の運営、収支バランスとか、業務の課題についてお伺いをします。それから、歳入の部分ですので、文化センターの過去３年の歳入は六千四、五百万円のところを推移している。しかし、ある特定の方々が利用する以上は、そこに負担をしていただかなければならないだろうということで、その辺の考え方をお伺いをさせていただきたいと思います。","respondent":"上川内生涯学習課長","answer":"文化センターですが、文化センターの使用料の考え方としましては、概ね光熱水費の約３割程度を受益者負担と考えております。平成８年に使用料の見直しがございました。そのときに概ね光熱水費の３割ということで設定しています。","voiceIndex":199,"id":"exchange-084"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうでお話しさせていただいたのは、光熱水費の３割が使用料だという説明ではなくて、文化センター等々におけるところの使用料と、それから、そこにおける歳入歳出のバランスをどういうふうに考えたらいいかというのを説明いただきたい、こういう話です。","respondent":"上川内生涯学習課長","answer":"バランスですが、歳出の部分は、この表につきましては、光熱水費だけではなくて、人件費を除いたすべてを持っております。社会教育の目的であります、区民に対する支援の部分も含めまして、文化センターの部分はこのような割合になっているものです。","voiceIndex":201,"id":"exchange-085"},{"speaker":"原委員","kind":"質問","question":"それは光熱水費の３割が収入だということではなくて、考え方の中で、受益者負担ということであれば、区民の皆様にも負担をいただかなければならないわけですから、そういうところでどういうふうに考えて今後持っていくか、これはちょっと先の話をしますけれども、例えば文化センターを民間委託をしていくとか、いろいろな方向がありますよね。","respondent":"上川内生涯学習課長","answer":"失礼しました。文化センターですが、平成１３年度に見直しをしまして、正規の職員から受付を民間委託をしてまいりました。","voiceIndex":203,"id":"exchange-086"},{"speaker":"原委員","kind":"質問・要望","question":"先ほど私は文化センターだけを挙げましたけれども、中小企業センターの暗室の問題にしても、品川健康センターのゴルフエリアの利用率の問題にしても、区有施設そのものについてはいろいろな見方がありますけれども、考え方を今までどおりでいいのかどうかというところのお話ですので、その辺のところを踏まえてお考えをお聞かせいただきたい。","respondent":"市岡企画財政課長","answer":"こういう場合の大規模修繕のコストもコスト計算の中に入れて、ストックの分析をするべきではないか、このような多角的な視点を含めて、ぜひ前向きに改革をしていきたい、こう考えてあります。","voiceIndex":205,"id":"exchange-087"},{"speaker":"原委員","kind":"質問","question":"したがいまして、中で行われている業務自体も、今のようなお考えに合わせて変えていかなければ、これからはいけないのではないのかなというふうに思うんです。ただ、まちづくり全体計画に合わせて検討を始めるという文言が入っているんですが、文化センターの位置づけが、今のような考え方で今後運営をされていくとすると、まちづくりの状況に合わせて改革をしていくということはどういうことなんですか。","respondent":"古川教育次長","answer":"今回の事務事業評価の中で、文化センターの整備につきましては、全体といたしましては、まちづくりの全体計画に合わせて検討を進める。","voiceIndex":207,"id":"exchange-088"},{"speaker":"原委員","kind":"質問","question":"そうすると、文化センターにおける業務内容も、地域性が確立されてくるということでよろしいんでしょうか。運営自体も、これからおそらく、今の状況では運営できない部分も出てくる。そして、事業形態もその地域地域に合わせて変わってくるとなると、もう一つ考えていかなければならない部分があるのではないかなと思うんですが、その辺のお考えがあればお聞かせください。","respondent":"古川教育次長","answer":"そういった観点から、まちづくりという大きな視点の中にそれぞれのセンターを捉えていく、こういうことでの考え方を私どもは持ってありますし、さまざまな機会にそういうものとの関連付けをしながら、文化センター全体の運営をまた工夫していきたい。","voiceIndex":209,"id":"exchange-089"},{"speaker":"原委員","kind":"意見","question":"そこで、文化センター、運営もそうですけれども、収支バランスもそうですけれども、今後の中で民間委託を既に受付業務とか保守点検の業務も委託をされている部分があると思いますけれども、今後の中でこういうものをどこまで委託を考えていらっしゃるのか、そしてまた、それが区民サービスにどこまで結びつくかという話ですが、はっきり言いますと、区民サービスを落とさないような形で。","respondent":"上川内生涯学習課長","answer":"そういうところをＰＴをつくりながら、今後詰めていくことになっております。それから、民間委託、受付業務等やってありますが、これからはサービス、接遇等を充実させるような方向で、全体的に地域バランスをとりながら、文化センターを運営していくように努めてまいります。","voiceIndex":211,"id":"exchange-090"},{"speaker":"原委員","kind":"質問・要望","question":"どこまでやるかをちょっと聞きたかったんですけれども、それで、今お話をさせていただいた業務委託が、一つ確認ですけれども、区民サービスの低下にならないような形をぜひ考えていただきたい。これは当然の話ですけれども、それをさらに押し進めていただきたい。それから、今たまたま文化センターなり品川歴史館なり挙げさせていただきました。","respondent":"中尾根企画部長","answer":"そうすると、一言で言えば、企画みたいな部分はきちんと残しながら管理運営をやる、こういうような検討をしていく必要がある、このように認識しています。","voiceIndex":213,"id":"exchange-091"},{"speaker":"中島委員","kind":"質問","question":"初めに、教育費委託金の８４１万５,１３０円の中に、心の教室相談員活用調査費というのがありますが、心の教室相談員というのは、たしかスクールカウンセラーが配置されない学校に配置されていると思うんですが、調査費というのは、どういったことを調査されているのか、初めにお伺いいたします。","respondent":"中島指導課長","answer":"心の教室相談員の調査費についてですけれども、これは文部科学省のほうで心の教室相談員の活用調査研究委託を実施しておりまして、それの実施です。","voiceIndex":216,"id":"exchange-092"},{"speaker":"中島委員","kind":"質問・要望","question":"スクールカウンセラーというのは、品川区で今何人配置されているのかわからないので、これも後で教えていただきたいですが、スクールカウンセラーにしても、心の教室相談員にしても、１対１というのはなかなか難しくて、カウンセリングのお部屋に何人も生徒が入ってきたりとか、いろいろあるという話も聞いたことがあるんですが。","respondent":"中島指導課長","answer":"スクールカウンセラーですけれども、平成１４年度は９校の中学校においてスクールカウンセラーが派遣されておりました。中学校は１８校ありますので、それを埋める形で心の教室相談員が派遣されてございました。","voiceIndex":218,"id":"exchange-093"},{"speaker":"中島委員","kind":"質問","question":"研究がそれぞれの学校でということですが、それは学校の先生方と話し合うという、単にそれでとどまっているんでしょうか、それともカウンセラーの方とか、心の教室相談員の方が一緒になっていろいろな問題、課題に対して取り組んでいるということなんでしょうか。","respondent":"中島指導課長","answer":"先ほども申し上げましたけれども、平成１４年度は各中学校でスクールカウンセラーか、心の教室相談員か、どちらかの配置ということでございました。","voiceIndex":220,"id":"exchange-094"},{"speaker":"中島委員","kind":"質問","question":"この部分というのは非常に大事な部分ではないかな、特に最近、青少年の犯罪というのが非常に多くなっております。私は最近長崎の１２歳の少年の記事を見たときに、非常に考えさせられたということは、あの少年は脳に疾患があった。それは一概にはできないと思うんですが、今後の教育委員会としての課題として、どのようなご見解を持っていらっしゃるか、お伺いしたいと思うんです。","respondent":"中島指導課長","answer":"多くの目で子どもたちを見守っていくような体制づくりにつきまして、今後とも基本的な児童・生徒理解を重視した教育活動が展開できるよう指導をしてまいりたいと考えております。","voiceIndex":222,"id":"exchange-095"},{"speaker":"中島委員","kind":"質問・要望","question":"いろいろあれもやっている、これもやっているということは分かるんです。大事な部分は、もう一つ心を砕いていただきたいということを私は要望しておきたいと思うんです。この問題はまたほかのところで触れていきたいと思うんです。それともう一つ、学童保育クラブでの参加費というのはお幾らだったんでしょうか。","respondent":"富田教育改革担当課長、辻田児童課長","answer":"すまいるスクール参加登録にあたりまして、年額５５０円という登録費用は同じです。学童保育クラブは使用料という形で毎月３,０００円ということでいただいております。","voiceIndex":224,"id":"exchange-096"},{"speaker":"中島委員","kind":"質問・要望","question":"３,０００円と、５５０円では随分違う。こうしたところは片方のすまいるスクールができたとなると、その学校の生徒はすまいるスクールのほうに行ってください、このように言われているということですが、そうでしょうか。","respondent":"辻田児童課長","answer":"平成１６年４月からはすまいるスクールの実施校のお子様はすべてすまいるスクールのほうで放課後児童健全育成事業を受けていただくことになります。","voiceIndex":227,"id":"exchange-097"},{"speaker":"中島委員","kind":"質問","question":"そこで、今小学校でも、中学校でも学校自由選択制というのがあるこの品川区ですので、片や、まだすまいるスクールが行われない学校の生徒が、あそこの学童保育クラブに行っている、そこにはお友達もいる。もうちょっとの間、すまいるスクールに自分は移行してもいいけれども、もう少しここにいたいというお子さんがもしいた場合、これに対しての選ぶ選択制というのは考えられないんでしょうか。","respondent":"辻田児童課長","answer":"そういう中では所属する学校のすまいるスクールの中の放課後児童健全育成事業を受けていくというのが一番素直な、そして子どもたちの育ちにとっても一番良い方策ではないかという具合に考えております。","voiceIndex":229,"id":"exchange-098"},{"speaker":"中島委員","kind":"確認","question":"そうしたものをきちっと子どもに理解をさせていくというか、子どもというより、私は保護者に理解をさせるということが大事かなと思うんです。保護者が疑問を持っていれば、子どもにそれは伝わっていくという、そういうことから、この辺のところの、こちらはもう決まったものですから、というのではなくて、そこにもう少しきめ細かなご指導があったらいいなと私は思うんですが、いかがでしょうか。","respondent":"富田教育改革担当課長、辻田児童課長","answer":"すまいるスクール、新しいところは９月に開設したばかりですが、そういった新しいところも含めまして、来年４月には、現在学童保育クラブを利用しているお子さんも安心してすまいるスクールをご利用いただけるように、その方向に向けて。お子様が安心すれば、保護者の方もかなり安心されるのではないかということで、私どものほうは基本的にこの事業を進めていく上で。","voiceIndex":231,"id":"exchange-099"},{"speaker":"中島委員","kind":"意見","question":"非常に力強い、子どもを安心させていただけるというご答弁をいただいたんですが、念のため、私も勘違いしていた部分があると思うんですが、来年度から移行ですね。今年すまいるスクールに移行するところは即今年中にということではないんですね。","respondent":"辻田児童課長","answer":"一つの年度の区切りとして、子どもたちも新しい生活にいく時期だと思います。そういうような４月という時期に移行するという具合に実施してまいります。","voiceIndex":234,"id":"exchange-100"},{"speaker":"中島委員","kind":"質問・要望","question":"それを伺って安心いたしました。それと、雑入の中のリサイクル資源売払収入というのが５,４００万円余あるわけですが、リサイクルショップの販売とは違って、リサイクル資源というのは、例えば古紙、空き缶とか、どういったものが含まれているのか、教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"資源売払収入と申しますのは、ほとんどが集積所に出される資源物で、古紙、びん、缶の売上代金、そのほか拠点であるとか、区の施設関係から売るものも資源物で売れるものを売却した収入益です。","voiceIndex":236,"id":"exchange-101"},{"speaker":"中島委員","kind":"質問","question":"これまた勘違いしたのかと思うんですが、例えば放置自転車、取りに来た者に対しては３,０００円の手数料をいただいて、保管料を徴収するわけですが、どうしても取りに来ない者、そうしたものをまちの自転車屋が修理をして、また販売しているという、この収入はどこにあるんでしょうか。","respondent":"奈良交通安全担当課長","answer":"リサイクルで区内の自転車屋に卸しておりますけれども、そういった関係のお金につきましては、一旦区の歳入に入りまして、社会福祉協議会のほうに寄附という形で入っております。","voiceIndex":238,"id":"exchange-102"},{"speaker":"中島委員","kind":"質問","question":"ほかのところに入っているということですね。分かりました。そのときのご答弁を伺っていて、私は非常に愕然としてしまった、たしか二、三年前、私も一般質問で、またこの委員会の席上でも何度か大井町駅の放置自転車には触れているわけですが、阪急の駐輪場をつくるという約束をずっと待っている。これは一体何年ぐらいお待ちになるのか、お伺いしたいと思います。","respondent":"奈良交通安全担当課長","answer":"ただ、相手もなかなかなものですので、すんなりつくってくれない部分がありますので、引き続き強力に協議をしてまいりたいというふうに思っております。できるだけ早急にはつくってきたいなというふうには思っております。","voiceIndex":240,"id":"exchange-103"},{"speaker":"中島委員","kind":"質問・要望","question":"その分だけ歩道に自転車が突き出しておりますから、高齢者の方から、あそこは何とかしてほしい、危ないという声をたくさんいただいております。あそこのプランターを取ろうと、取るまいと、放置自転車はずっとあるわけですから、この辺のお考えをお聞かせいただきたいと思います。","respondent":"奈良交通安全担当課長","answer":"私としても、なるべく早くいい改善策が見つかれば、そういった方向でやっていきたいと考えていますので、約束はできませんけれども、向こう側とよく協議をして、何とか委員のご趣旨に沿うように頑張っていてきたいというふうに思っております。","voiceIndex":242,"id":"exchange-104"},{"speaker":"中島委員","kind":"質問・要望","question":"約束していただきたいところですけれども、期待していたいと思います。そして、プランターをもし外したとしたら、その分取り締まりを厳しくするなど、いろいろ考えてアイデアを尽くしていただきたいと要望して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この速報というのは、土曜、日曜を除くと、３日目にインターネットで、答弁も含めてすべて見られるという状況になっているんですが、正式なものは後で出されるそうですけれども、速記者の方が入っているので、速記者の方がまとめられるということでお聞きしたんですが、これは大変やりとりがよく分かっていいなというふうに思ったんですけれども、品川区議会の中でも、区民の関心が強いことは。","respondent":"福田区議会事務局長","answer":"本会議等をもう少し早くホームページにその概要を記載できないか、もう一つは速報版です。この問題につきましては、前期の議会運営委員会の中でもさまざまなご意見がございました。","voiceIndex":247,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本会議のアップについては２カ月までにということですので、これは６月ですから、３カ月経ってもまだというふうな状況なので、ぜひこれはそのとおりにアップしていただけるように頑張っていただきたいというふうに思います。私もちょっと調べてみたんですけれども、１６倍速というのがあるそうです。ぜひ高速ダビングのご検討もいただきたいというふうに思うんですが、いかがでしょうか。","respondent":"福田区議会事務局長","answer":"技術的な問題、１６倍倍速、確かにあろうかというふうに思いますが、私はそういう問題ではないというふうに思っております。","voiceIndex":249,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"テープそのものは、今でもダビングをしていただいているんですけれども、このダビングそのものがやるべきじゃないという考え方なんでしょうか。","respondent":"福田区議会事務局長","answer":"そういう意味を含めまして、ダビングそのものに意味があるというふうには思っております。しかしながら、それを一般的に行って、一般的にダビングしたものをお渡しするということについてはいかがか、このように申し上げたものです。","voiceIndex":251,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなときにいただきたいということでも、なかなか全部をいただくというふうな状況になっておりませんでしたので、そういうところでは、文明の利器をせひご活用いただいて、議員にも正確にそれを把握することができるようにということで、改めてご検討いただきますよう要望して、次の質問のほうに移ります。次に、東京都の支出金についてお伺いをしたいと思います。","respondent":"市岡企画財政課長","answer":"第一次のときの結果については、何分にも前のことですので、今手持ちがございませんので、これももし必要でしたら、そういう形で資料を作成したいと考えています。","voiceIndex":253,"id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"現在の資料をいただきましたけれども、この中での第一次プランの１９９９年というのもお聞きしたんですけれども、その前の現在の中で事業数と、それから補助金の総額をお聞きしたんです。","respondent":"市岡企画財政課長","answer":"先ほどは第一次のお話で、現在手元に資料がないということをご説明しました。それから第二次のプランの問題ですが、件数と額ですが、これは計算をすれば出ることですが、今そういう計算をしておりませんので、ご容赦を願いたいと思います。","voiceIndex":255,"id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これを見ると、負担金というのがあって、それから補助金と委託金というふうなことになっているんですけれども、ということは、補助金と委託金を合わせた約５３億１,３００万円ということで理解していいのかなというふうなところで思ったんですけれども、そこのところを確認させていただきたいと思います。","respondent":"市岡企画財政課長","answer":"今のところ１０月を目途に作成するという、第二次東京都財政再建プランはまだ姿も形もどこにも出ておりませんので、この段階では具体的な協議はないということで、ご報告をします。","voiceIndex":257,"id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、東京都のほうからある程度プランが出された段階で協議をするというふうなことになるんでしょうか。東京都と一緒に区が減らすようなことになったら大変だなというふうなのを改めて思ったところですけれども、これについても、ひとり親家庭の方がこれがどれほど切実なものかというふうなところを、実際区民の立場から考えて、協議の場には臨んでいただきたいと思うんですが、いかがでしょうか。","respondent":"市岡企画財政課長","answer":"ただ、東京都は確かに補助金にはさまざまな課題があって、例えばできた当時にはそれなりの合理性があったけれども、時代変化とともに見直さなければいけない補助事業がたくさんあると、こういう意味でいろいろな補助金を例を挙げてありますが。","voiceIndex":259,"id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほかの自治体でも、市長会が合意しないものは実施しないようにというふうなところも言われている自治体もあるようですけれども、区長会として合意しないものは、東京都に対しても実施しないようにということで強く求めていただきたいと思うんですが、いかがでしょうか。","respondent":"市岡企画財政課長","answer":"ただ、それが区への財政負担の転嫁とか、単なるしわ寄せになるようなものについては、これはきちんと区の立場として協議をしていく、このように明快に区長は述べられたというふうに私どもも理解しています。","voiceIndex":261,"id":"exchange-113"},{"speaker":"須貝委員","kind":"質問・要望","question":"歳入の税についてと、総務費負担金について、ご質問をします。特別区民税の内容についてお聞きしたいということと、現在この不景気の中で特別区民税が増えていると。その理由を教えてください。さらに、特別区民税の歳入の年代別の割合、２０歳代、３０歳代から７０歳代、そして産業別の割合、さらに、その中で中小零細企業の割合などが分かるようでしたら教えていただきたいと思います。","respondent":"松崎税務課長","answer":"それと、増の要因ですが、企画財政課長が説明申し上げましたように、まず納税義務者数が平成１３年度と比較して１,４６１名増えているということ、それと、もう一つは、高額の納税者が昨年度発生している。途中で修正申告をして大きな税が出ているという２点。","voiceIndex":264,"id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"引き続きご質問をします。今、特別区民税が漸次増えていっているということですけれども、将来にわたって、数年先、１０年先、そのようなスパンで品川区は特別区民税に対してこれからも増えていくのか、その辺どのように考えているか、将来の見通しを現在で分かればお答えください。","respondent":"松崎税務課長","answer":"それと、将来の見通しですが、品川区は住宅政策をずっと続けてまいりました。定住化するとすれば、私どもが中堅ファミリー層の定住化というのを非常に気にしているのは、３０歳代から５０歳代までを中堅ファミリー層というふうに考えております。","voiceIndex":266,"id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"品川区の歳入につきまして、軽自動車税は増えております。ですが、自動車取得税は現在減っております。こういうことを鑑みますと、今特別区民税が一時的に増えている、高額所得者、３０歳代から５０歳代の若いファミリー層が増えているということでなっていると思うんですけれども、現状を見まして、品川区の景況ですか、全般を見ますと、どのような判断をなされているのか、お聞きしたいと思います。","respondent":"松崎税務課長","answer":"昨年あたりは２０％を切っているという状況、それが平成１４年度は１８％から１９％に伸びておりますので、滞納繰越が伸びてくれば景況は上がっているのではないかというふうに考えております。ただ、住民税の場合は課税の時期、所得の時期、納税の時期、微妙にずれております。","voiceIndex":268,"id":"exchange-116"},{"speaker":"須貝委員","kind":"質問","question":"実際徴収率が今上向いておりますから、その辺も加味すると、実際どうなのかなというところはありますけれども、当面品川区内の特別区民税、歳入については、ある程度安心した判断をできるのかなと安心いたしました。次に総務費負担金についてお聞きいたします。","respondent":"西島経理課長","answer":"使用料の算定ですけれども、貸すにあたりましては、区では公有財産管理運用委員会というところで議論をいたしまして、お貸しするということになるわけですけれども、時価といいますか、現在の台帳の価格に基づきまして平米を計算をいたしまして。","voiceIndex":270,"id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"引き続きまして、例えば区民から、土地を売りたいと思って、区のほうで購入していただけないかなという要請があった場合、どこの課に足を運んだらいいのか、また、これも大ざっぱでいいんですけれども、例えば区で区民の土地を買う、もちろん高い値段では買えないと思うんですけれども、区民の税金ですから、それを買うにあたって、土地の評価額に対して。","respondent":"西島経理課長","answer":"金額ですけれども、もし買うという結論が出た場合には、財産価格審議会という第三者機関を設けてあります。そこで金額を決めまして、財産価格審議会の額以下で交渉をして、購入するという形になろうかと考えています。","voiceIndex":274,"id":"exchange-118"},{"speaker":"須貝委員","kind":"意見","question":"これからも区民のためによろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":276,"id":"exchange-119"},{"speaker":"伊藤委員","kind":"質問","question":"私は成果報告書の６９ページの保育園保育料に関連をしまして、それから、１７０ページの職員費に関連して、午前中もございましたが、名誉昇給のことについて質問をいたします。いろいろ調べてまいりますと、過年度分の未納額が対前年比約３００万円程度増えているという数字もいただきました。そういうことについての見解と、それに対する品川区の対応を改めてお伺いしたいと思います。","respondent":"金子保育課長","answer":"委員のお話に抗弁するつもりではないんですが、現年度分としましては徴収率がアップしておりまして、滞納繰越分と合わせた額につきましてもアップしているというところで、私どもとしましては。","voiceIndex":278,"id":"exchange-120"},{"speaker":"伊藤委員","kind":"意見","question":"残りの５％の部分を保護者の皆さんに負担していただいているわけでありますから、そのことについて、どこかで品川区の考え方、対処の仕組みとか、取り組みが甘いのではないかという思いがいたします。そこの部分についての対処の考え方とか、保育園保育料の考え方、もう一つ突っ込んてご答弁をお願いしたいと思います。","respondent":"金子保育課長","answer":"そういう意味では、今後とも私どもとしては、保育の充実、あるいは待機児解消策、あるいは次世代育成支援対策推進法に基づく子育て支援施策の拡充、こういったものをにらみながら、より適切な利用者負担というものを考えながら。","voiceIndex":280,"id":"exchange-121"},{"speaker":"伊藤委員","kind":"質問・要望","question":"あまりこのことに入っていきますと、款別のところに重なってまいりますので、ここでは要望をいたしておきますけれども、私どもの考えの中では、国基準の保育料のことについてを視野に入れて対処をしていくべきだと考えていますし、受益者負担のあり方についても、これだけの大きな事業を展開されて、しかも、事業自体が延長、夜間さまざまな形で拡大されてきたわけですから、それについて保護者の負担。","respondent":"桑村人事課長","answer":"私どものほうでは、その意味で、それを運用いたしまして、功績顕著に当たらない、いわゆる実績については、長年はお務めだったけれども、いわゆる辞められる時点で判断すれば、昇給するにはちょっと難しいだろうという方を１割程度これまで落としてきた経過があります。","voiceIndex":282,"id":"exchange-122"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もう少し具体的なことを教えていただきたい。功績顕著の者というのは、どういう評価なんですかということをお伺いしたいので、教えていただきたい。それから、私どもの考え方といたしましては、昇給そのものがだめだということではありません。","respondent":"桑村人事課長","answer":"その意味では、ただ受ける者が例外になってはいけないだろうというような判断が別途あります。その意味では、一生懸命やっている者がある程度報われる制度というものをどの程度の水準にしていこうかというところを今検討をしています。","voiceIndex":284,"id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問・要望","question":"間違いなく該当をしていく。果たしてそれでいいんでしょうか。そういうふうなことの基準はどうなんだということ、そのことについてはめりはりをつけていったほうがいいのではないでしょうかということで質問しておりますので、今の人事課長の答弁は、ただ長いだけでいいという評価だったわけです。それで、そういうふうな思いの中で質問をしておりますので、改めて答弁をお願いいたします。","respondent":"本間総務部長","answer":"ただ、それでも９割の職員が対象となるというような現実は確かにあります。こういう中で、委員ご指摘のとおり、きちんとした勤務実績のある者、それが報われるような制度の運用等について、今後そういう方向に検討をしていくですので、ひとつご理解のほどお願いいたします。","voiceIndex":286,"id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"結果として、多くの区民に功績を与えることができた。このそれぞれの職員の対象枠が違って、当たり前なんです。だから、なぜそれができないんですかという、非常に単純なところからお伺いしているわけですので、制度は制度として品川区のことは分かりました。でも、もう一つ評価の方法とか、品川区独自の取り組みをはっきりとして教えていただければありがたいんですが、いかがですか。","respondent":"濱野助役","answer":"もっと進めば、給料の年俸制などということも出ている、そういう時代の中で、公務員の給与制度がどこまで妥当性を持つのかというのは、真剣になって考えなければならないことだろうというふうに思います。","voiceIndex":288,"id":"exchange-125"},{"speaker":"伊藤委員","kind":"質問・要望","question":"非常に心強い答弁をいただきましたが、先輩から教えていただきました、「休まず、遅れず、働かず」というのが、品川区ではないと思うんですけれども、公務員のそういうふうな仕事をなさって３０年近く務めた方でも名誉昇給される話ですから、これはどういうふうに考えてもおかしい話であって、先ほども繰り返し述べさせていただきましたけれども、なぜ１４の手当とか。","respondent":"濱野助役","answer":"そういう意味では、全体というのは社会の常識でありますし、社会がどういう状況になっているかということに立脚しながらの公務員制度、このことについて努力を重ねてまいりたいというふうに思っております。","voiceIndex":290,"id":"exchange-126"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは３点ほどお伺いいたします。１点は、５ページから数ページにわたりまして、主要施策の成果について。３点目は７５ページ、歴史館使用料についてお伺いをいたします。それで、平成１４年度の主な施策として、事業部のそれぞれの施策の成果がその次に書いてあるわけですが、この問題につきましては、午前中にも質問がございまして、私は、この中から会計制度についてお伺いをしたいと思います。","respondent":"市岡企画財政課長","answer":"しかし、今日のように事業が複雑になってくれば、当然私どもの日々の業務でも、歳入との関係、それから長期的な総コストの関係、これらを考えなければマネージメントはできませんので、そこで通常官庁方式の今の方式というのはストック情報がないだとか。","voiceIndex":293,"id":"exchange-127"},{"speaker":"山路委員","kind":"質問・要望","question":"もう１点は、発生主義というのは、金利を計算したり、減価償却費を計算されることになるので、どれくらいのコストがかかったかが一目瞭然になる。より少ない費用で大きな効果を出そうというコスト意識が出てくる期待が大きいということなんですね。東京都が現在これの導入に向けて検討しているということですが、品川区ではどのように今後考えていらっしゃるかお聞かせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"先ほど申し上げたとおり、企業会計手法の導入については取り組んだのですが、今委員ご指摘のとおり、日々の業務を、例えば私ども差引簿と称する官庁形式の帳簿を日々記帳しているわけですが、それを複式簿記で記帳する、あるいはそれの累積が自動的に貸借対照表ですとか。","voiceIndex":295,"id":"exchange-128"},{"speaker":"山路委員","kind":"質問・要望","question":"ロケーション・写真撮影等については、決算書に４１５万１,３８０円計上してありますけれども、品川区内にとりましては、区内の特に歴史、文化、新名所等の撮影は区のアピールにもなり、私も大変好ましいと思っているわけですが、平成１４年度は何件ぐらい撮影が行われ、主にどういうところで撮影され、どういう規則が設けられ、撮影するにあたってはどういう規定があるのか、お伺いをいたします。","respondent":"岩田管理工事課長","answer":"これについては平成１４年度でロケーション・写真撮影合わせまして２０６件の実績があります。","voiceIndex":297,"id":"exchange-129"},{"speaker":"山路委員","kind":"質問","question":"ここで、申請書とか、そういうものは書いて出すんでしょうか。事務所に申し込むだけでいいんでしょうか、その辺を教えていただけますでしょうか。","respondent":"岩田管理工事課長","answer":"ただ、事前にそれぞれの公園によっては、地域の感情もいろいろありますので、一律に使っていいよということではございませんので、その地域の状態を一番よく把握しております土木事務所のほうで事前に相談をしていただいて、希望する日時において、住民の利用状況から。","voiceIndex":299,"id":"exchange-130"},{"speaker":"山路委員","kind":"質問","question":"子どもを遊ばせるための公園で、子どもが追い出さられるのは納得いかないということで、私がお叱りをそこで受けたのですが、こういうトラブルは、両方ともその公園で楽しもうということで、ましてや２０６件という、回数も非常に多いですし、お互いにスムーズにいくように、お互いが分かりやすいように、何かの掲示板を設けるとかの表示をここでお願いしたいわけですが、どのようにお考えでしょうか。","respondent":"松代道路公園課長","answer":"今委員からのお話、十分調査をし、またそういったことでトラブル等が今後ないように、表示の点も含めまして、検討をしたいと考えております。","voiceIndex":301,"id":"exchange-131"},{"speaker":"山路委員","kind":"質問","question":"もう１点の歴史館使用につきましては、時間がきましたので、また日を改めてお伺いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":303,"id":"exchange-132"},{"speaker":"高星委員","kind":"質問・要望","question":"２点目には、成果報告書の９７ページ、繰入金１億６,０００万円余です。こういう時期こそいろいろな意味で勤労者に対するフォローというのが必要なんじゃないかなというような気がするものですから、その辺の考え方をお聞きしたいと思います。","respondent":"市岡企画財政課長、桑村人事課長、市川産業振興課長","answer":"公有財産の表との関係で言いますと、決算書の２４２ページに有価証券の増減のところが出ておりまして、区が持っている有価証券、株券との関係では。現在借りている職員ですけれども、大体１４０人前後です。背景といたしましては、利用者が極めて減ったこと、また、区で実施しておりました事業内容とほぼ同じ内容のものが東京都の制度としてご利用いただけること。","voiceIndex":305,"id":"exchange-133"},{"speaker":"高星委員","kind":"質問・要望","question":"職員住宅資金融資の関係、１４０人前後の方にお貸ししているという話でございました。調査はしないだろうけれども、その辺のところを推して知るべしみたいなところで、何か押えているところがあったら、お聞かせいただきたいと思います。３点目に聞いた、産業振興課長から答弁のあった、勤労者生活資金融資の関係、これは需要は全然ないんですか。もう一度お聞かせいただきたいと思います。","respondent":"桑村人事課長、市川産業振興課長","answer":"その意味では、ある程度工夫されてお返しになられているのかなというふうに理解しています。勤労者生活資金融資の申込者の推移で申し上げますと、廃止に至るまで５年間の推移で、申し込みされる方の人数自体もかなり急激に減ってまいりました。","voiceIndex":309,"id":"exchange-134"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１７０ページの民生の職員費のところでお伺いをします。初めに、調理代行に先駆けて栄養士の削減もあったわけですけれども、栄養士の削減と調理師の削減のところを、年度に沿って人数を教えていただきたいのと、改めて保育園の給食業務代行を導入した理由をお伺いしたいと思います。","respondent":"金子保育課長","answer":"それによりまして、園長、保育士についても給食のことに関心が深まりまして、なおかつ、認識が深まりまして、現在では導入主体につきましては順調に調理代行の成果を上げて、具体的には園児の喫食量が増える等々非常に効果の上がっている事業だというふうに考えているところです。","voiceIndex":313,"id":"exchange-135"},{"speaker":"飯沼委員","kind":"質問","question":"順調に進んで、効果を上げているということですけれども、まずその辺の効果のほどをちょっとお伺いしたいんですが、今、栄養士が保育課に６名配置されて、保育園にはすべていなくなってしまったということと、調理が３１人の定数ということですけれども、今まで経験豊かだった栄養士と調理師がいなくなった後、業務代行の園のところがどういう配置になっているのか、お伺いをしたいと思います。","respondent":"金子保育課長","answer":"ただし、給食がそういうような形できちっと提供できるような形であるかどうか、これについては確認をしているという内容です。","voiceIndex":315,"id":"exchange-136"},{"speaker":"飯沼委員","kind":"質問","question":"私がなぜ聞いたかというと、東五反田保育園はＩＳＯ取得をしています。研修の中身、だれがどれだけ受けたのかとか、業務代行の届出、変更の届けというのがあるので、これはもちろん課長が把握していることで、これを伺わないと、今までの給食と今と比較することができないわけです。なので、今日はあえてＩＳＯのところも、ここのところいろいろ調査が進んでいますので、お伺いしました。","respondent":"金子保育課長","answer":"先ほどもご答弁申し上げたとおり、私どもとしては、先ほどの仕様が完全に遂行できるような体制であるかどうか、こういうことを確認するためにいろいろな諸表については提出していただいておりますが、正規が何人であるとか、非常勤が何人であるとか。","voiceIndex":317,"id":"exchange-137"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は逃げだと思うんです。きちんとお答えいただきたいと思います。品川区はＩＳＯ９００１、品質マニュアルをきちんと持ったにもかかわらず、区民に明らかな表示ができない、保証の中身が示せないというのは、私ははっきり言ったら、言葉だけで、正確ではないと思います。ぜひ数字を出していただきたいと思います。数字が出ないで、何で以前と現在と比較ができるのでしょうか。再度お願いします。","respondent":"金子保育課長","answer":"それを私どもとしては完全に執行されるように把握しようですので、ご理解いただきたいと思います。","voiceIndex":319,"id":"exchange-138"},{"speaker":"飯沼委員","kind":"質問","question":"もう１点は、厚生労働省のところには「入所の児童および保護者に対する栄養指導をするように」と、きちんと１項目入っているんです。この項目はどのようにクリアをしているのか。前々からぜひ試食会を行ってほしい、この要求が出ていて、以前課長はかなり前向きなご答弁をされたのですが、いまだこれが実現をされていないというところでは、ここの部分をお聞きしたいと思います。","respondent":"金子保育課長","answer":"例えば料金についてもどうするのかというようなこと、あるいは量についてもどうするのかということがきちっとできていませんでしたので、そのことを整理してから実施するというふうに申し上げてまいりました。これについては近々に実施できるように、ただいま検討をしています。","voiceIndex":321,"id":"exchange-139"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど財政効率ということが言われましたけれども、これは凄く関心が高いことなんですけれども、本当にコストの削減になっているのかというところをお伺いしたいんですが、私が既に給食の委託をしている台東区からいただいた資料によると、ここに並んでいる委託の会社の名前を見ると、品川区でもおなじみの会社がいっぱい並んでいるわけですけれども、ちょっと保育園のところが手に入らなくて、小学校。","respondent":"金子保育課長","answer":"全園委託になった暁には中身が変わるかということですけれども、これはあくまでも民間企業の考え方で私どもの給食の内容というのはつくっているわけではなくて、品川区の保育の考え方で給食をつくって、それの仕様に基づいて給食をつくっていただいているわけですから。","voiceIndex":325,"id":"exchange-140"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私の心配が取り越し苦労だったら、それはそれでいいんです。私は、区が今までのように地元の業者から安全な食材を調達をして、今の給食が内容ともに子どもたちにとって安全でおいしい給食である、これを守る、その辺の決意をお聞かせいただきたいんです。","respondent":"金子保育課長","answer":"これは私どもとしても当然のことながら守ってまいりましたし、今後とも守っていかなければならないものだというふうに考えております。","voiceIndex":327,"id":"exchange-141"},{"speaker":"飯沼委員","kind":"質問・要望","question":"手づくりで、安全で、おいしい給食をよろしくお願いいたします。ぜひ直営のところを守ってほしいと思うのと、栄養士の配置が不可欠だと思います。この間よそで行われている給食の業務代行、また委託においても、学校などはどこも栄養士が１名配置されているんです。そして、どちらもこれから小学校、中学校に拡大をしていくというような発言も一般質問で出たので、ぜひこれを守っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-142"},{"speaker":"三上委員","kind":"質問・要望","question":"短くお伺いをいたします。成果報告書の７０ページの総務使用料で、集会所使用料という、平塚橋会館と区民集会所と挙げられているんですけれども、特に区民集会所を利用されている方たちの要望とか、希望とか、切なる願いというか、そういうような声というのを頂戴しているようなことはないかどうか、ちょっとお伺いしたいんです。","respondent":"志村地域活動課長","answer":"その都度できる限りその場で対応するようにしています。私どものほうで大規模に手を入れなければならないということにつきましては、例えば来年度ということで対応せざるを得ないものもありますけれども、でき得る限りその場で対応をするということを心がけているところです。","voiceIndex":331,"id":"exchange-143"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、いろいろ改善すると今おっしゃっているわけですけれども、そういう中にあって、金額的にはそれこそエレベーターだったら１,０００万円とか、２,０００万円、３,０００万円、いっときは６,０００万円ぐらいしますなどという答弁をいただいたことがありましたけれども、そういう金額の一桁違うようなもので、昇降機なども考えられるということもあるんですけれども。","respondent":"志村地域活動課長","answer":"今ご説明いたしましたとおり、今年度補正予算の中で、実は品川第二地域センターに昇降機を付けていきたいというふうに考えてあります。ご質問に出ました荏原西集会所となりますと、実はあれは表の階段になりますので、委員ご指摘のとおり、コストの点もあります。","voiceIndex":335,"id":"exchange-144"},{"speaker":"三上委員","kind":"質問・要望","question":"外付けの階段ですけれども、そういったところもいろいろ私も勉強してまいりましたし、技術的にも最近はいいものができている、こういったことから、ぜひ検討をする、また今年の第３０回国際福祉機器展というのが１０月１５日から１７日まで、３日間やりますけれども、こういったところもご参考にされていただいて、そういった品川第二地域センターの昇降機だけでなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":337,"id":"exchange-145"},{"speaker":"林（宏）委員","kind":"質問","question":"東京都の財政が逼迫している中で、財調で見てもらいながら、特例交付金もきている、それは絶対なんでしょうか。安心していていいのでしょうか。それを一つ。事業部それぞれがほとんど９５％前後の執行率なんですけれども、９５％前後という数字が適切なのかどうか、その辺をまず聞かせてください。勘定項目のところと、職員費のところは後で聞きたいと思います。","respondent":"市岡企画財政課長","answer":"第１点目の、区の財政をできるだけ分かりやすく区民の方にお知らせするという点では、バランスシートは確かに委員おっしゃるような側面がありまして、私どももいろいろ区民の方と財政の説明の機会があるときにお話ししますと。","voiceIndex":339,"id":"exchange-146"},{"speaker":"林（宏）委員","kind":"質問","question":"僕は企画が決算を見ながら書いていたのかなというふうに思っていたものですから、そういう形で事業部なりの、独立採算ではないんでしょうけれども、そういう意識の中で予算・決算に取り組んでいくというのが大変必要になってくるだろう。減債の部分は、しっかり見ていかないと、１０年に一遍ぐらい借り換えのときがくるわけで、どさっという数字も出てくるわけですから、その部分だけお答えいただきます。","respondent":"市岡企画財政課長","answer":"あらましは企画で原案を書きますが、これは最後に必ず事業部長にご確認の判こまでいただいて、責任を持った成果報告書とさせていただいてあります。","voiceIndex":341,"id":"exchange-147"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"部長だけではなくて、それぞれの部の皆さんが決算をつくり上げて、成果報告書ですから、自分たちの成果をきちんと評価をしながら進んでいっていただきたい、それはお願いしておきます。だけど、委託料の２億９,０００万円の中には人件費が入っているわけです。それが一つ。なぜ防災対策でいくのか。こういうふうに決算が毎年出てくるわけですから、その辺の考え方を説明していただけますか。","respondent":"市岡企画財政課長","answer":"もちろんいろいろな重要な仕事を委託方式でやる場合にも、その仕事自体は当然重要なものとして実施していかなければいけないわけですが、実施方法、あるいは時間の経緯とともに、事業の存廃を含めて人件費よりは見直しのフレキシビリティが高いわけですから。","voiceIndex":343,"id":"exchange-148"},{"speaker":"林（宏）委員","kind":"質問","question":"趣旨は分かりますけれども、災害のほうは今まさに地震のこと、それから、品川区で言えば、水害という問題、対策は防災という観点からはいろいろ仕事をされている。クイックプランを東京都に要請している。いろいろな形でされているけれども、某かの災害がくるわけですよ。事故はだめなんですかね。でも、それではない年が生まれるように祈念して、災害対策のほうだけお願いします。","respondent":"市岡企画財政課長","answer":"それともう一つ、これはあまり大きな声では言えないんですが、予備費に災害対策費として実際に起きてしまった水害等の経費をきちんと明瞭にしておくと、財調の中の特別交付金を取るときに、これ以上明瞭なものはありませんから、表裏極めて説明がしやすいと。","voiceIndex":345,"id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1212#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":111158,"voices":347}},{"id":"h15-20031007-4","meetingId":"h15-c-settlement","date":"2003年10月7日","dateIso":"2003-10-07","committee":"決算特別委員会","time":"午後１時０５分～午後７時５８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を157件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは歳出第２款総務費、第１項総務管理費、１０６ページ、水と緑の市町村交流事業につきましてお伺いをさせていただこうと考えています。それからもう一つは、ここでの事業のあり方です。最終的には、交流事業のあり方についてお伺いをしたいと思うんですが、ここの事業を打っていく部分、そしてまたひだまりの里の管理等々を含めて、お考えがありましたらお知らせいただきたいと思います。","respondent":"長田区民課長","answer":"山北町にしてみれば、農園をやっている方は定期的に行っていただいておりますし、共同農園の方も誘い合って行っていただいているというようなことで、それから事業の数もそれほど何十種類の事業を実施しているわけではございませんので、気に入った事業があると。","voiceIndex":4,"id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"数字的推移はいただいておりますので、よろしいんですけれども、そこでかかった経費と１人当たりどのぐらい経費を享受しているかというところを聞きたかったわけでございまして、それは後でお答えをいただきたいと思います。そういう意味からいっても、この事業内容はもっと精査する必要があるのではないかなと思うんですが、その辺はいかがでございましょうか。","respondent":"長田区民課長","answer":"１人当たりの経費ですけれども、単純に割り返しますと、山北町のほうが２,８７０円ぐらい、早川町のほうが３,９５０円ぐらいになるだろうというふうに思います。","voiceIndex":6,"id":"exchange-002"},{"speaker":"原委員","kind":"質問・要望","question":"私の故郷ですので、私も年間少なくとも２回か３回はそちらのほうへお墓参りには行きますけれども、そのたびにひだまりの里へ寄って、どんなかなと非常に興味があって行ってくるわけですけれども、何か利用されていないなと。そういう意味では、そこの部分はもう少し今後の中で考えていかなければならない課題だと思うので、その辺の交流の定義と今後の方針についてお述べいただきたいと思います。","respondent":"長田区民課長","answer":"いずれにいたしましても、神縄地区の人たちと今後事業のあり方について協議を持つ場もありますので、そちらの中で十分双方が納得いくような、さらに効果的な事業のあり方について検討はしていきたいというふうに思っているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうから、３点お伺いをいたします。初めに、１０５ページの人権啓発費について、二つ目には、１０５ページの庁舎管理維持費についてお伺いをいたします。初めに、人権啓発費についてですが、男女共同参画センターの運営についてお伺いいたします。やはり、男女共同参画センターの中では相談事業が一番大きい事業かなと考えていますので、よろしくお願いいたします。","respondent":"阿部人権啓発課長","answer":"１点目のセンターの相談の内容ですけれども、法律相談とカウンセラー相談をやっているわけですけれども、一番多いのは法律相談関係で離婚問題が一番多いということです。次には、健康相談あるいは生き方の相談、そういうものが多いということになってあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"嶋委員","kind":"質問・要望","question":"昨日可決されたばかりなので、条例的には私もしっかり勉強していきたいと思います。上乗せをしたということで、今日の朝のニュースを聞いてまいりました。それから、先ほど言った性同一性障害の窓口の設置といいますか、ここが窓口ですということを告知をしていただきたいと思いますが、いかがでしょうか。","respondent":"阿部人権啓発課長","answer":"そういうことで、窓口はセンターが中心になりますけれども、区全体でも保健所あるいは児童課等でも相談しているということで、広くなお一層周知はしていきたいというふうに考えてあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"嶋委員","kind":"質問・要望","question":"冊子を多くしていただいたということで、幅広く品川区の方に見ていただけると思います。以前にも私は要望させていただいたんですが、この冊子を女性がたくさん集まる小児科とか婦人科とか病院とか、また郵便局とか銀行ということをお願いをいたしましたが、その点はいかがでしょうか。","respondent":"阿部人権啓発課長","answer":"医院ですけれども、健康課が所管していますけれども、そちらのほうを通しまして、医師会を通じて医院に配ってあります。従来から郵便局等にも配ってありますので、今後とも配布先をなるべく多くしまして、多くの区民の方の目に触れるということで考えていきたいと思ってあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"嶋委員","kind":"質問","question":"二つ目に、６月の第二回定例会で一般質問をさせていただきました不必要な性別欄、男女規制性別欄の削除についてお願いをいたしましたところ、区のほうからは行政文書は４０件ある中で、今後印鑑登録証明書を含めて性別記載の必要性の有無を精査した上で、不要なものは削除する方向で検討してまいりますというようなご答弁をいただきましたが、その後品川区の削除に対する準備といいますか。","respondent":"阿部人権啓発課長","answer":"ですから、現在全庁的に申請書についての性別記載の調査をしておりまして、そろそろ結果がまとまります。その状況を踏まえまして、行政文書だけではなくて、申請書についても不必要なものは削除していこうという方向で検討したいと考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"今お話を伺いましたら、品川区も申請書も含めてということなので、大変うれしいお返事をいただいたと思いますが、また実施に向けてもう一歩積極的に、いつまでにというか、そういうのがもし出ましたらお聞かせいただきたいと思います。","respondent":"阿部人権啓発課長","answer":"それを一つ一つ検証し、あるいは精査しながらやっていきたいと考えていますので、時期ということでは、なるべく早くやりたいというふうには考えてありますので、ご理解のほどをお願いいたします。","voiceIndex":19,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、一日も早く実施の方向に向けて、よろしくお願いしたいと思います。二つ目に、１０５ページの庁舎等維持管理費に移らせていただきます。そういう意味では、役所にいらっしゃる区民の声とか反応のことがありましたら、お聞かせをいただきたいと考えています。","respondent":"西島経理課長","answer":"第二庁舎と議会棟につきましては、これから準備を進めているところですが、特に区民の方から私のところには声が直接入っておりませんけれども、利用状況を見ていただきますと、第二庁舎の３階、本庁舎の２階にきちっとした形の喫煙コーナーをつくりましたので。","voiceIndex":21,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問・要望","question":"ただ一つ、私がここで言いたかったのは、本会議場の５階です。それほど朝とか５階のエレベーターを下りた途端、息をしたくない。なぜ５階の本会議場の前が遅れているのか、やはりあそこにはいろんな方が傍聴にいらっしゃいますし、ずっと煙が残っているわけです。そういう意味では、あの前を通ると息をしたくないという状況がありますので、遅れている理由をぜひお聞かせいただきたいと思います。","respondent":"西島経理課長","answer":"外へ出す排気の問題等がありますので、検討しています。いずれにいたしましても、議会棟につきましても議会事務局と十分協議をいたしまして、早急に整備する予定ですので、ご理解をいただきたいと思います。","voiceIndex":23,"id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、いち早くやっていただいて、あそこにつくらなければいけない理由もないかなと考えています。ですから、一日も早く深呼吸ができる５階にしていただきたいと考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"対象物件については昭和５６年以前に建てられた建物が大半なんですけれども、倒壊の危険性がかなり高いと言われる部分を対象物件にして助成制度を設けているということがわかりまして、改めて品川区の耐震診断について、今までは紹介はするし、ビデオも貸し出しはしますけれどもという、そういう程度にとどまっていたことについて、不十分過ぎるのではないかというふうに思いますので、改めてこの点について。","respondent":"片田建築課長","answer":"ただ、なかなか利用率が少ないという話も聞いてありますので、その辺も視野に入れて検討を始めたといったような状況です。","voiceIndex":27,"id":"exchange-012"},{"speaker":"南委員","kind":"確認","question":"ですから、こういう実態について、概要の報告が出されたばかりですから、これについて検討はこれから始まるというふうに理解しますけれども、こういう実態についての認識、耐震診断との関係でどういうふうに持っていらっしゃるのか伺いたいし、防災の観点からも、ぜひ所管の課長からの見解もお願いしたいと思います。","respondent":"片田建築課長、久保田防災課長","answer":"火災危険度について、建物が倒壊というお話もありますけれども、東京都では新防火という新しい制度もつくってきてありますので、そういうものを合わせて、検討する必要があると思いますし。今、建築課長からお話があったとおり、まちづくり事業部と連携して、そういうことを進めていきたいというふうに考えております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"ですから、２３区の自治体の半分が耐震診断を助成制度として持ってやっているわけです。倒壊によって人が亡くなる、圧死の状況をなくすということですよね。したがって、検討という段階にとどめていられないし、そういう点で少なくとも来年度の予算に、できるだけ反映できるように検討の速度を早めていくべきだということを思うわけですから、そこについて改めて伺いたいというふうに思います。","respondent":"片田建築課長","answer":"検討の速度を早めてほしいというご質問ですけれども、確かに最近２カ月おきに震度６弱、７月２６日、９月２６日にそんな地震が来てあります。その中で、やはり住民の意識が大事だと思っています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"やはり、何回答弁を聞いても、非常に消極的だというふうに感じます。他区に私も聞いたんですけれども、そういう意識を啓発するためにも設定したんだという話なんですね。ですから、そういう意識を啓発していくと同時に身を守る、そういう一石二鳥、三鳥の効果があるわけですから、これはやっぱり早急に進めていくべきだということを強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-015"},{"speaker":"高星委員","kind":"質問","question":"声高にマンションの倒壊の調査を言うのはいいんですけれども、先ほどの南委員の話の中に、あたかも品川区のマンションの実態調査の中で、２０年以上の建物はそろそろ危ないんだみたいなニュアンスの話は、うちのマンションは実は２３年経つんです。つまり、集まっているお金も、そういうことも全部絡んでいるわけですから、私は心配するんです。その辺の方向性を明確に言ってください。","respondent":"片田建築課長","answer":"東京都についても、防災都市づくり推進計画の考え方の中で整備地域あるいは重点整備地域をそれぞれ決めた中で、それぞれの施策の中で地域の防災まちづくりに強いということを考えてありますので、耐震についても、その施策の一つとして検討するということで考えてあります。","voiceIndex":36,"id":"exchange-016"},{"speaker":"高星委員","kind":"質問・要望","question":"いずれにしても、僕も管理組合の役員は最初からやっているんですけれども、管理組合としてものすごく自助努力しているわけです。町会長会議でやってもいいでしょう。それから、できればさっき言ったように、そういった義務づけられている報告の中に、そういうものがきちんとリンクできないのかどうか、震災対策はどうなのかということも含めて一項を設けるとか、そういったことを前向きに考えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-017","title":"町会・自治会支援"},{"speaker":"大西委員","kind":"質問","question":"私のほうから４点ほど質問をします。１０９ページの防犯体制整備費ですが、三宅島で噴火等がありまして、こちら側に避難してこられている方が多いんですが、その際にペット等の扱いは避難しているところでどのような形になっているのか。品川区で実際に災害が起こったときに、犬や猫のペット等の避難における扱いについてお聞かせください。","respondent":"久保田防災課長","answer":"ただ、避難所にペットの扱いどうするかというのは大きな課題だというふうに、私どもも十分認識していますので、いろいろな関係団体とか、あるいはそういう方と今後協議をして検討していきたいというふうには考えております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"大西委員","kind":"質問","question":"それと、先ほど４点と言いながら言い忘れましたが、今言っておきます。１０６ページの地域相互支援推進事業、１０７ページの防犯協会助成金、１０８ページの世論調査です。１０９ページの学校等の避難所機能の充実、仮設便所用便槽の設置６校ということがありますが、これは何名ぐらいの方々の使用を想定されておられるのでしょうか。","respondent":"久保田防災課長","answer":"ペットの今後の考え方ということでお話をさせてもらいますけれども、少なくとも私ども早急に検討をしていかなければならない課題だとは思っています。","voiceIndex":42,"id":"exchange-019"},{"speaker":"大西委員","kind":"質問","question":"防犯協会助成金についてお尋ねしますが、これはどういう趣旨で実際に使われているんでしょうか。","respondent":"志村地域活動課長","answer":"昭和４９年から行っているものでございまして、平成１４年度は総額といたしましては１５０万７,０００円、各区内５カ所にあります防犯協会に補助をしています。","voiceIndex":46,"id":"exchange-020"},{"speaker":"大西委員","kind":"質問","question":"そうすると、防犯カメラ等の助成ということでしょうか。防犯カメラ自体、区のほうで何台ぐらい現在までに助成されているんでしょうか。","respondent":"志村地域活動課長","answer":"先般の本会議で区長からご答弁をしましたとおり、防犯カメラにつきましては、それぞれの方の発意に基づいて行うべきだというのが、現在の区の考え方です。これまでの助成ということですけれども、これまでには１件もございません。","voiceIndex":48,"id":"exchange-021"},{"speaker":"大西委員","kind":"質問・要望","question":"非常に私としては不自然だなと。今の時代に防犯カメラを設置したいという要望がないというのは、何らかの告知の方法の問題なのか、それとも助成が少ないからそういう状態が出てこないのか。これを助成すると、１台について総費用として幾らかかって、そしてまた助成金はその金額の何割を助成されるのか教えてください。","respondent":"志村地域活動課長","answer":"私どもで聞いていますのは、東京都において商店街の助成ということを聞いてあります。装飾灯の補助の一部というふうに聞いてあります。経費につきましては、３分の１というのを聞いてあります。","voiceIndex":50,"id":"exchange-022"},{"speaker":"大西委員","kind":"質問","question":"地域相互支援推進事業の地域食事サービスについてお尋ねします。これは小学校の配食サービスだと思うんですが、この点は間違いないでしょうか。","respondent":"志村地域活動課長","answer":"地域食事サービスですけれども、現在のところ小学校の給食を使いましたサービスと、それから中学校を使いました夕食の配食サービスの二つを行っているところです。曜日につきましては、火曜日と木曜日ということで、米飯給食のときというふうにご理解をください。","voiceIndex":52,"id":"exchange-023"},{"speaker":"大西委員","kind":"質問","question":"１週間に２回と承知しておりますが、そのときに材料費等は、その給食を受けられる方から１食につき２８０円徴収しているというふうに認識しているわけですが、その場合に１カ月当たりどれぐらいの赤字が出るのか。そしてまた、この利用者が区内に何名おられるのかを教えてください。","respondent":"志村地域活動課長","answer":"夕食につきましては４００円です。それぞれ材料費ということでいただいてございまして、赤字というのは、そこまで計算したものはございません。学校の給食設備を使って調理しておりますので、そういう意味では赤字という認識ではございません。","voiceIndex":54,"id":"exchange-024"},{"speaker":"大西委員","kind":"質問・要望","question":"先般、さくらハイツでは元気なお年寄りが入居した場合には２１食ついている。私も以前に地域で食事サービスをやっている人たちと一緒に会食をしたときに、２食では足りないということで、お年寄りの間からいろんな要望が出ているというふうに聞いているわけですが、区役所として２食が適正と思われている根拠を聞かせてください。","respondent":"志村地域活動課長","answer":"それともう一つは、安否の確認という視点もございました。これを開始するにあたって、ボランティアの方の配食ということで始めたものです。私どもの努力の不足かもしれませんけれども、ボランティアの方の確保が非常に難しゅうあります。","voiceIndex":56,"id":"exchange-025"},{"speaker":"大西委員","kind":"意見","question":"もし、ボランティアの人がいないということであれば、小学校、中学校等での空き教室を利用して、その場に歩いて来られる方々ついては、歩いてきて学校の中で食事を取っていただくという考え方について、お考えをお聞かせください。","respondent":"志村地域活動課長","answer":"私どもはただいまふれあいサポート活動を始めてございまして、この中の一つのメニューといたしましては、高齢者懇談会を現在社会福祉協議会で実施していますけれども、これを秋以降は順次地域センターで開催していきたいというふうに考えてあります。","voiceIndex":58,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"私は１０８ページ、インターネットに関係しての質問、それともう一つ、１０９ページ、消火器整備に関しての質問、２点の質問をします。関連いたしまして、７０ページの施設使用料のところからお伺いします。款別が違いますか、違えば変えますけれども。大きな目で胸をお借りするつもりでお伺いしていますので、知識の不備、ご勘弁を願いまして、ちょっとお答えを願いたいと思います。","respondent":"山田広報広聴課長、諸岡区民生活事業部副参事","answer":"ご指摘のとおり、平成１３年度は年間で２０万１,７９９件のアクセスがありましたのが、平成１４年度は４１万９,２２３件のアクセス、倍増というような利用状況です。１,４００万円ほど平成１３年度に比例しまして減額している利用ですが、平成１４年度に大ホール等の改修工事を行いました。その間、それぞれ施設ごとに異なりますが、２カ月から１０日間程度閉鎖をいたしまして工事を行っております。","voiceIndex":61,"id":"exchange-027"},{"speaker":"大沢委員","kind":"質問","question":"先ほどのインターネットの話に戻りますけれども、私が何を言いたかったと言いますと、数を比べながら、次のような質問事項を伺いたかったのであります。そういう部分に関して、何か受け手側、また発信側に何か不都合な点はないのか、差異に関してどのようなフォローをされているのか、そういうことをお伺いしたいと思います。","respondent":"田中情報システム課長","answer":"今、委員お尋ねの件ですが、施設予約で特に抽選等の関係で、受け付けの締め切りを決めまして、そこの締め切りまでにインターネット等、それから窓口、はがき、インターネットだけではなくて、多様な施設予約に対する窓口を用意しておりますので、一定の日にちまでにやれば。","voiceIndex":64,"id":"exchange-028"},{"speaker":"大沢委員","kind":"質問","question":"いずれにいたしましても、人口におきましてもだんだん図式が変わりつつあります。次の質問に行かせていただきます。消火器の整備についてでありますけれども、昨年９７８本、消火器の機能点検が行われておりますが、本年の施策の実績表には書いてございません。これは行われていないのでしょうか、まずお答えを願いたいと思います。","respondent":"久保田防災課長","answer":"消火器の機能点検ですけれども、平成１３年度は確かに９７８本の実績があります。ここの中には表示していないんですが、平成１４年度は２９１本やってあります。","voiceIndex":66,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"消火器８１本を加えているわけですけれども、開発指導要綱に基づいて設置されたと聞いておりますけれども、これは品川区の条例の中のどのような条例に基づきまして開発指導要綱というのが出ているわけでしょうか、お伺いいたします。","respondent":"久保田防災課長","answer":"８１本街頭消火器が増えておりますが、これは今お話が出ていました開発指導要綱に基づいて、民間業者がある一定以上の建築物を建てるときにお願いして、設置しているものです。これは要綱でございまして、条例ではございません。条例設置はしてございません。","voiceIndex":70,"id":"exchange-030"},{"speaker":"大沢委員","kind":"質問","question":"それに対しては物を申す余地はないんですが、ちょっと疑問というか別のことなんですが、最近テレビでスプレー式の消火器というのを見まして、これは初期消火にはいいんじゃないか、量的には劣ると思いますけれども、初期消火には高齢者でも子どもでも、とっさのときというのはまず逃げるというよりも消すという行動が起きると思うんですが、決してスプレー式がいいというわけではなくて。","respondent":"久保田防災課長","answer":"スプレー消火器ですけれども、最近テレビの通信販売等でよく目にするわけですけれども、この消火器については消防署にお聞きしましたところ、消火力はそんなにないということですけれども、てんぷらなどの火災の発生直後には対応できるけれども。","voiceIndex":72,"id":"exchange-031"},{"speaker":"大沢委員","kind":"質問","question":"どうも、いろいろときめ細かなお答え、ありがとうございました。これをもちまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"私は１０７ページの生活安全推進事業についてお伺いしますが、この事業は具体的にどのような事業をしたか、まずお尋ねいたします。","respondent":"志村地域活動課長","answer":"３回目は先日あったんですけれども、それにつきましても、そのような対応をこれからもっと、私どもで今度新しく組織をつくりましたということで、これから進めていこうです。","voiceIndex":76,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、課長から組織をつくりましたというお話が出たんですけれども、私もちょうど今から１年１カ月前だと思います。私はそのすぐ後の第三回定例会でも質問させていただきました。その点も含めて、地域と警察との協力というのは不可欠ではないかと、そのパイプ役という意味においても、その組織というのはこれからどのように係わっていくのかお尋ねしたいと思います。","respondent":"杉浦生活安全担当課長","answer":"重ねて、よろしくお願いをいたします。ご質問の生活安全という部分の組織の説明ですけれども、これは私のほかに兼務の主査が１名、それから警察官ＯＢの３名の非常勤職員、それにガードマンが各２人ずつついて、今のところポイ捨ての警告指導にあたっている。","voiceIndex":78,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"それで、ぜひ課長に質問なんですけれども、今まで警察組織といいますか、警視庁の組織にずっといられたわけですが、品川区にお見えになってちょうど１週間しか経っておりませんが、警察組織の中で働いていたときと、１週間区役所の中にいらっしゃって、一番の違いといいますか仕事上の違いで、ちょっとここは違ったなとかという感覚といいますか、考えがありましたら教えていただけますか。","respondent":"杉浦生活安全担当課長","answer":"いずれにいたしましても、皆さんのご支援、ご協力をいただきながら、品川区のために尽くしていきたいと考えておりますので、どうぞよろしくお願いをいたします。","voiceIndex":80,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"最後に一つお伺いしたいんですが、新組織ということで区民の期待もあったことは確かにわかるんですけれども、私は議会の一員として、本当に警察と行政という、いろいろな形で質問をさせていただきました。この新組織をつくることは、区民の期待もあるかもしれませんけれども、やはり議会側からこういう発言した結果、こういう組織ができたということもあるんでしょうか。","respondent":"志村地域活動課長","answer":"それと私どもで、こうした考えを警察の方と意見を交換した際に、「品川区はそこまでやるんでしたら」ということで、ＯＢの方も含めて話を進めておりました。警察からも、ぜひもっとバックアップしたいということで、今回現職の方の派遣をいただいたと、このような経過です。","voiceIndex":82,"id":"exchange-036"},{"speaker":"中島委員","kind":"質問","question":"初めに、決算書の８６ページに報酬というのがあるんですが、４億５,１０４万６,６００円ですけれども、これは成果報告書の代替職員雇用経費とか嘱託非常勤職員経費と金額が合わないんですが、どういう方が対象の報酬費になっているのか、初めにお伺いします。","respondent":"桑村人事課長","answer":"臨時職員の場合は賃金という項目に変わっておりますので、その意味で各款にまたがった形で報酬の項目が出てまいるというふうになってありますので、嘱託非常勤経費だけではないということで、ご理解をいただきたいと思います。","voiceIndex":85,"id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"そこでお伺いしたいんですが、この代替職員というのは、例えば出産を控えた方のかわりの代替の方とか、そういう対象だと思うんですが、嘱託非常勤というのはどういった形が対象になっているんでしょうか。","respondent":"桑村人事課長","answer":"そのために今までいた再雇用制度を一部変えまして、嘱託非常勤と呼んです。いずれはなくなるという制度ですけれども、その形で区のＯＢをいろんな部署で活用しているという制度です。","voiceIndex":87,"id":"exchange-038"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、ちょっとここと外れてしまうのかもわかりませんが、非常勤職員というのはここには載っていないんですか。","respondent":"桑村人事課長","answer":"それは各仕事の事業の中で入ってありますので、総務管理費の中では一括して計上してございませんので、その仕事によってそこの部署のところに出てくるという形の非常勤という制度です。","voiceIndex":89,"id":"exchange-039"},{"speaker":"中島委員","kind":"質問","question":"そうしましたら、少し関連した質問になってしまうかもわからないんですが、品川区には非常勤また嘱託非常勤の方がたくさんいらっしゃると思うんです。非常勤で働く方たちに対する正規職員の方の振る舞いというか考え方、こうしたものは正規職員の方には何か指導をなさっている部分がありますでしょうか。","respondent":"桑村人事課長","answer":"逆にその意味では、一定の部分しか担当されないかもしれませんけれども、同じようなサービスをしていただくというようなこともありますので、その意味では差がつかないというんでしょうか、同じような情報をなるべく共有いたしまして。","voiceIndex":91,"id":"exchange-040"},{"speaker":"中島委員","kind":"質問","question":"今、非常勤の方たちは、非常によく仕事をされていただいていると思うんです。ところが、例えば保育園に非常勤で行っていらっしゃる方、１０分でも早く行って引き継ぎをしたいという思いで行くと、「まだ時間が来ていないので向こうに行っていてください」というふうに阻害をされる。こういう一つの例があります。そういう現状もありますが、こういった点については、どのようにお考えでしょうか。","respondent":"桑村人事課長","answer":"その意味でいろいろ足りない点はあろうかと思いますけれども、そのたびごとに対処してまいりたいという所存です。","voiceIndex":93,"id":"exchange-041"},{"speaker":"中島委員","kind":"質問・要望","question":"その際、やはり非常勤の方たちのこうしたいろんな問題を受け付ける場所、話ができる場所というのは必要だと思います。学校事務をなさっている方は、この問題を言ったら「学校の中で解決してください」と、これで終わってしまったということなんですね。これは、決意だけをお聞かせいただきたいと思います。","respondent":"桑村人事課長","answer":"もちろん、私ども人事課でもお話を伺えば、その中で所管と一緒になって対処してまいりたいと思いますので、よろしくお願い申し上げたいと思います。","voiceIndex":95,"id":"exchange-042"},{"speaker":"中島委員","kind":"確認","question":"そうしましたところ、選挙の真っ最中でしたが、区役所のほうからお電話をいただきまして、「あれはどういうことですか」という問い合わせがあったわけなんです。私はそれをきちっと説明をいたしました。その交番が見えないということでは、非常に困るんではないかと、そのときに話をしたんですが、それ以来、何の音沙汰もないんですが、その件はどのようになったかだけ確認しておきたいと思います。","respondent":"冨田戸籍住民課長","answer":"私のほうもＪＲと話をしたんですけれども、むしろ例えばの話なんですけれども、サービスコーナーの前にいらっしゃって、携帯電話で場所を聞いているような方もいらっしゃいまして、要するにサービスコーナーの上のほうにちゃんとした表示があるんですけれども。","voiceIndex":97,"id":"exchange-043"},{"speaker":"中島委員","kind":"質問・要望","question":"サービスコーナーは確かにご努力いただいたんですが、今日は幸いにも生活安全担当の警視庁からの方もいらっしゃいますので、ぜひ交番の位置がわかりづらいというまちの声があるということは、ぜひご認識いただいて、努力していただきたいと思うんですが、いかがでしょうか。","respondent":"杉浦生活安全担当課長","answer":"かしこまりました。初めて私は聞きましたけれども、交番というのはまちの大切なところでありますので、必ず警察署に伝えておきたいと思います。","voiceIndex":99,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私は成果報告書１０５ページ、職員住宅関係経費、それから１０８ページ、ＣＡＴＶ事業、１０９ページ、事業部支援プロジェクト、１１０ページ、区民保養所経費、この４点について簡潔にお聞きしたいと思います。区民保養所の件ですが、昨日時間がなくて、最後半端になってしまったので、再度確認をします。要するに、品川区が委託している費用の中で、本当に保養所が賄っていけるのか。","respondent":"長田区民課長","answer":"ですから、基本的には、私どもは仕様書に規定をしたサービスがきちっと提供されれば、そのお金がどう使われようが、本来は関知をしないところですけれども、そうは言いながらも、やはりそれぞれ３カ所につきましては報告書等をいただくなりして、チェックは重ねてあります。","voiceIndex":102,"id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先に質問を続けします。職員住宅関係経費の中で１,１３０万６,０００円、これは職員経費の中で、例えば大崎待機寮ですと、今度西五反田のプリスクールに変わっていくということで活用なさっています。小学校ですと「４０色のパレット」、中学校が「学舎１８章」の制作費もこの中に含まれているのか、その点をお答えください。","respondent":"桑村人事課長、山田広報広聴課長、長田区民課長","answer":"旗の台の入居率ですが、今現在３３％という入居率です。「４０色のパレット」については、平成１２年、１３年度の２年間にわたって４０本製作をいたしまして、平成１４年度につきましては。保養所の今後の考え方ですけれども、私ども過去からずっと保養所を持ってきたわけですけれども。","voiceIndex":104,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"確認","question":"職員住宅の件なんですが、旗の台は３３％の入居率というのが非常に疑問を持っています。建物が５８０m2ぐらい、この中でたった３３％の入居率で本当にいいんでしょうかということをお聞きしたい。学校選択ということを考えての放送だと思うんですけれども、学校の中は２年間同じなんですか。ただ、１本制作費は幾らになるか確認し損なったので、それがわかれば一緒にお願いいたします。","respondent":"桑村人事課長、山田広報広聴課長","answer":"平成１５年４月ですが、先ほどもご紹介のありました大崎待機寮と西五反田待機寮につきましては転用するという方針を決めました。今度、平成１６年４月ですけれども、西大井待機寮についても転用しようという考えです。年間２０本という形の契約を取りまして、１本約８０万円の製作ですけれども、約２０本を製作していくという３カ年計画ということで実施をし、必ず選択をする時期には小学校。","voiceIndex":108,"id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"女子寮に関しては、寮の必要性は十分認めますが、もうちょっと別の形もあるんじゃないかと。〔「８０万円」と呼ぶ者あり〕８０万円の中で、確かにかかると思うんですけれども、なるべくなら新しい学校の中をどんどん紹介していただきたいと思います。もう１点、事業部支援プロジェクトなんですが、今年度の決算で１２万５,８５５円という、予想より非常に低かった。","respondent":"榎本行財政改革担当課長","answer":"事業部支援プロジェクトの執行率が低かったということで、実際には1．5％という形で入っておりますけれども、これにつきましてはそもそも平成１０年度の事業部支援プロジェクトが事業部の充実を図る中で、全庁的な対応を図る。","voiceIndex":111,"id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問","question":"確かに、当初の事業部制の予算を組んだ中で、事業部間の中のフォローをしていく部分でというお話を伺っていたと思っていましたし、確か、今年度は５００万円の予算を組んでいらっしゃいます。その辺で、新しい施策に入っていっているのか、どのような対応をされているのか、またこれが次の政策判断の中にも出てくると思うんですが、その辺の絡みはどのように考えていったらいいのか。","respondent":"榎本行財政改革担当課長","answer":"今年度の事業部支援プロジェクトにつきましては、やはり昨年度に引き続きまして、区政全般の基礎的なデータ収集をどう行っていくかということで、やはり品川都市白書の作成ということで今検討を進めているところです。","voiceIndex":113,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問","question":"政策の判断という点では、今後の次世代育成の行動計画も絡んでくると思うんですが、この辺も企画課が中心になってやっていくのかという点と、もう１点、事業部の中の政策判断はどのように、政策評価の仕組みづくりと各事業部の間というのは、どのような関係になっているのか。予算特別委員会の総括でもお聞きしたんですが、その後方向性が出ているかどうか、２点お願いいたします。","respondent":"榎本行財政改革担当課長","answer":"事業部と政策評価の関係につきましては、いろいろ検討していく中で進めていきたいと考えています。","voiceIndex":115,"id":"exchange-050"},{"speaker":"井上委員","kind":"質問","question":"私からは成果報告書１０５ページの自動車運行管理費と１０８ページの広報費、そして１１０ページの区民施設費関係についてお伺いをいたします。品川区の区有財産としての車両台数が１９９台と決算書にありますけれども、この４月から一部の車両を各所管保有から経理課に管理を移しまして、有効活用としていると伺っております。実際には、どのような取り組みをされているのかお聞かせください。","respondent":"西島経理課長","answer":"その結果、今年度ですけれども、６台廃車をいたしまして有効に活用するように図っているところです。それからもう１点は、この庁舎の集中化に合わせまして、庁内のイントラを利用しまして予約等も、そこから予約できるというようなシステムに変えたところです。","voiceIndex":119,"id":"exchange-051"},{"speaker":"井上委員","kind":"意見","question":"車両の有効活用は進んでいるかと思うんですけれども、その中に私たち委員会で視察に使っておりますマイクロバス２台だと思いますけれども、マイクロバスはどういった目的に使われているのか、また年間利用実績が何回なのかお聞かせください。","respondent":"西島経理課長","answer":"マイクロバス２台所有していますが、これは議会の活動用に購入したものですが、平成１４年は８８回利用しています。","voiceIndex":121,"id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"年間８８回といいますと、いつも２台一緒に出るとも限りませんから、大変少ない利用かと思うんですけれども、先ほど経理課で車を有効利用するというようなこともありまして、このマイクロバスについても何らかの有効活用ができるかと思いますけれども、その辺のご見解はいかがでしょうか。","respondent":"西島経理課長","answer":"マイクロバスにつきましては、当初は議会用にということで購入いたしましたけれども、議会で実際にお使いになれるのは委員会の視察の際がメインであるということで、回数にしますと月に２回ぐらいということでございましたので、平成１４年度から有効活用を進めるということで。","voiceIndex":123,"id":"exchange-053"},{"speaker":"井上委員","kind":"提案","question":"区民モニターを対象に１回と、一般区民を対象に５回、合わせて年間６回、品川区の施設見学会が行われていますけれども、平成１３年度の参加実績が２４０人、平成１４年度が２２１人、この事業では大型マイクロバスをレンタルして使用しているわけですけれども、１回の平均を考えますと３０人前後ということで、区所有のマイクロバスを２台使うことも可能になるかと思いますけれども。","respondent":"山田広報広聴課長","answer":"基本的には大型車５０名で募集をし、実際の参加がそのとき８割方になりますので、４０名程度の見込みで実施をしております。","voiceIndex":125,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"次に区報しながわについて伺います。区報しながわは年間３８回、１万７,４００部が発行されていますけれども、区報では区政情報、地域行事の紹介、公共施設を使った区のイベント、また品川区の新しい施策についての意見募集などを行っています。区報は行政からの一方的な情報提供ではない役割を持つと思いますけれども、区報の役割をどのように認識されているのかお伺いいたします。","respondent":"山田広報広聴課長","answer":"それと同時に、地域の情報も合わせて、区民の皆様方に品川区に愛着を持っていただくためということで、さまざまな情報も入れご紹介をし、ご意見についてもモニターの募集でありますとか、さまざまな区民参加の機会ということでご紹介をするということも実施をしています。","voiceIndex":127,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"一方的に区の情報ではなく、区民側からの意見の聴取ということも行われるということでしたけれども、区民が公募して載せられる区民のページが年間何回あるのか、そしてまた１回の紙面にどのぐらいのスペースが取れているか、また公募するにあたって掲載予定のどのぐらい前に申し込むのかお伺いいたします。","respondent":"山田広報広聴課長","answer":"これについてはそれぞれの安定した活動、いわゆる宗教的、政治的、営利的な活動は排除いたしますけれども、区民の皆さんの自主的な活動のご紹介の場ということで、月１回紹介をしています。","voiceIndex":129,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問・要望","question":"そしてまた、希望者が多いので、随分待たなければならないという苦情もたくさん寄せられているんですけれども、今現在区報の紙面を見ますと、かなり空きスペースがあるように思いますので、その辺のことで企画の工夫や紙面レイアウトの工夫で、区民の方が利用できる部分の掲載回数を増やしたり、方法があれば考えていただきたいと思いますが、いかがでしょうか。","respondent":"山田広報広聴課長","answer":"それと、区民の皆さんがご利用できる今のコーナーの拡大についてですけれども、平成１３年度に紙面を大きく刷新をしたときにスペースを現在のほうが３分の１増やしています。そういう状況もありますので、今のところ難しいかです。","voiceIndex":131,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"私からは１０５ページの奨学金貸付事業と１１２ページの選挙費についてお伺いしたいと思います。平成１４年度で小・中学校ともに２６％、４人に１人の家庭が就学援助を受けていると伺いました。品川区奨学金制度は１６年前から条例がつくられ現在に至りますが、奨学金制度の導入の背景および趣旨、平成１３年の申請数と受理数および平成１４年、１５年についてお伺いしたいと思います。","respondent":"長田区民課長","answer":"平成１４年、１５年の実績ですけれども、平成１４年につきましては、６６名の方に貸し付けをしています。それから、平成１５年度につきましては、７８名の方にお貸ししたところです。","voiceIndex":134,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"もしよければ、申請数も教えていただければと思います。お金がないと学べない社会では、科学の発展は望めない、そんな声を伺っております。１６年前につくられた条例ですが、今後の品川区の育成事業の充実がますます期待されているのではないでしょうか。区としての大学生の学生生活費をどのように分析し、把握しているのでしょうか。大学生の就学保障についてもお伺いしたいと思います。","respondent":"長田区民課長","answer":"日本育英会ですけれども、現在育英会を廃止して新たな独立法人に事務を引き継いでいこうというような動きがあります。その中で、新たな法人の設立というものは、平成１６年４月１日ということで予定をされていますけれども、まだ詳細については通知が来てございません。","voiceIndex":136,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"今、大学生の話が出されましたけれども、例えば隣の大田区では対象枠を、現在大学・短大と拡大し、年間１００名ほどの利用があるとも伺いました。江戸川区では昭和５５年から人数制限が厳しいものの、区民から寄せられた寄附金を財源に充て、貸し付けではなく給付の奨学金を行われていると伺っております。改めて、大学生の育成事業についてどのようにお考えなのか、よろしくお願いします。","respondent":"長田区民課長","answer":"先ほど申し上げましたとおり、行政の役割として、やはりほかの奨学制度もある中で、品川区としてこれをやらなければいけないかというようなことについては、必ずしもその必然性はないだろうというふうに考えているところです。","voiceIndex":138,"id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"今、大学生の話が出ていますけれども、例えば今の大学生の学費の負担になりますと、私立・公立さまざまありますけれども、１９０万円でしょうか、かなりの高額になってきております。しかし、バイト代は月１２万円、これでは生活費だけで精一杯。青年の雇用対策という視点からも、奨学金の対象枠を大学・短大に広げていくということを、積極的に行っていくべきではないでしょうか。","respondent":"太川区民生活事業部長","answer":"大学につきましても進学率が大変向上していますが、先ほどいろいろご説明いたしましたとおり、他の制度がかなりいろいろ充実したものがありますので、そちらのほうの活用を十分図っていただくということで、区の役割といたしましては高校生。","voiceIndex":140,"id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、大学・短大に広げていただきたいと思いますので、ぜひ検討していただきたいと思います。次に、１１２ページの選挙費についてお伺いしたいと思います。今回の選挙につきましても、新しい取り組みが実施されておりますけれども、その実績と効果についてお伺いしたいと思います。特に、青年の低得票率の原因はどこにあるのか、区の分析と対策についてよろしくお願いいたします。","respondent":"野田口選挙管理委員会事務局長","answer":"そういった意味では、日頃から私どもは明るい選挙推進ということで、現在２００名の推進委員を抱えてありますので、日常の話し合い活動の中、またいろいろな区の施策の中でいろいろなところに参加してもらう、そういった主権者意識を育てることの中から。","voiceIndex":142,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"いろいろ分析と対策を話していただいたんですけれども、少し昔の話になりますけれども、立会演説会を行っていたという話を伺いました。これを復活させてみたらいかがかと考えています。従来どおりの投票日の周知だけで、低得票率を上げることができるのでしょうか。きちんと投票日だけではなくて、立会演説会なども含めて、今後検討する課題ではないかと思いますけれども、いかがでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"ただ、それぞれの支援する候補者の運動員の方を中心に支持する方が来て、立候補者の政見を聞くということよりも、応援したらさっと帰る。次に応援すればさっと帰る。","voiceIndex":144,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"立会演説会のあり方というのは、いろいろ工夫と努力が求められると思うんですけれども、私の周りの青年からは、こんな声が寄せられております。「候補者の公約や政策を知る機会が少ない。もっと活発な候補者同士の討論をしてほしい。候補者が何を訴えているのか、もっと見える形に示してほしい」と、話しておりました。ぜひ、今後とも立会演説会の工夫も含めて、検討をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私は１０９ページの防災対策費に関連して質問をいたします。それから、災害弱者の安全確保につきまして、ずっと質問しておりますが、新たな取り組みとして地域総合防災訓練の中で、要介護者の名簿を確保していく。これはこれでぜひやっていただきたいんですが、進め方の確認と、ずっと言っておりますのが、こういうところに出てこられる要介護者については、ある意味問題はないと思います。","respondent":"久保田防災課長","answer":"災害時、いわゆる発災時直後には、警察とか消防などをはじめとした行政機関が被災現場に駆けつけるには非常に時間がかかるということから、地域の皆さんが協力して。","voiceIndex":148,"id":"exchange-065"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、一つのワークショップの取り組みも必要でしょう。みんな助けなければいけない。そうすると、ＩＴ機器の取り扱いの内容とか、携帯電話の対処の問題、いろいろ取り扱いにくいというふうに表現してよろしいでしょうか、不慣れな方もいらっしゃる。常時持ち歩いていない、それからどういうふうに使っていいかわからない、いろんな現場の声が聞こえてきます。","respondent":"久保田防災課長","answer":"そういう機能を全部使いこなせるかというと、また難しい問題がありますので、一つは地域センターとの連絡に今後も十分使ってもらうということを、やはり町会長にもお願いしていきたいというふうに考えてあります。","voiceIndex":150,"id":"exchange-066"},{"speaker":"伊藤委員","kind":"質問","question":"課長の答弁の中に、まさにありましたように、配ったものは高度な情報端末なわけです。確かカメラもついているはずですから、災害現場の具体的な写真を、メールを通して災害対策本部に送るということだって十分できる話なんです。だから質問をさせていただいたわけですので、もう少し具体的な対処ときちんとした防災てるテル等に対する考え方を改めてお聞かせください。お願いいたします。","respondent":"久保田防災課長","answer":"幸いなことに、中止になったケースがございませんので使えなかったという状況があります。いずれにしましても、今後防災てるテルがより活用されるように、地域センターからの連絡用に十分使ってもらうということをまず皮切りに、充実させていきたいと考えております。","voiceIndex":152,"id":"exchange-067"},{"speaker":"伊藤委員","kind":"質問","question":"それが目の前にあるわけです。それをほんの少し町会長の皆さんにご理解していただいて、具体的にはこうやって写真を撮るんですよ、こういうふうにしてメールを送るんですよ、そして災害のときにはこういうふうに役立つんですよということさえ理解していただければ、すぐにでも素晴らしい情報のシステムができるわけですから、そのことについてもう一言いただければありがたいんですが、いかがでしょうか。","respondent":"久保田防災課長","answer":"せっかくの機器ですので、十分により効果的な活用ができるように、私どもも一生懸命努力していきたいと考えております。","voiceIndex":154,"id":"exchange-068","title":"町会・自治会支援"},{"speaker":"山村委員","kind":"質問","question":"私からは成果報告書１０９ページ、行政評価システム経費と事務事業評価結果一覧について、また１０９ページの防災センター維持管理費、防災センター展示・体験施設運営費、そして３番目に１１０ページの区民斎場運営費、平塚橋会館運営費について質問します。それから、行政評価システムおよび事務事業評価結果をどのような意識で皆さんの仕事に生かされているのかということを教えていただければと思います。","respondent":"榎本行財政改革担当課長","answer":"この評価を生かすものについては、決算の審議の中でご意見をいただくというものと、それを来年度の予算編成、実施計画等にどう生かしていくかというところを、一番改善していかなければいけない点だと考えております。","voiceIndex":157,"id":"exchange-069"},{"speaker":"山村委員","kind":"質問・要望","question":"事実、これを本当にやられている現場の方がどういうふうに事業をとらえているのか等々が全くわからないというか、反映されていないというか、もし悪いような意見が出ても隠せるというか、載せないのが通例になってしまうと思うんですが、職員の意識改革を図ることを目的としていると書いてあるんですから、もっと皆さんの仕事に関していかに反省すべき点があるとか。","respondent":"榎本行財政改革担当課長","answer":"事務事業評価の仕組みについてのお尋ねだと思われますけれども、まず内容量ということが１点目にありましたけれども、最終的に全部で６００を超える事業の評価をどう表していくかというときに、一時期この仕組みを行財政改革特別委員会で検討している中では。","voiceIndex":159,"id":"exchange-070"},{"speaker":"山村委員","kind":"意見","question":"最後にこのことに関しては、職員の意識改革を図るということですので、事務事業評価をつくるようになりまして、意識改革が起きたかどうかということと、これをどのような意識で仕事に生かされているか、この評価に関して意識改革が起き始めているのかどうかということを聞かせていただければと思います。","respondent":"榎本行財政改革担当課長","answer":"それがきちんと実績が上がっているかどうか、それと予算が適正に執行されているかどうか、そういう面からきちんと事業間の資源の配分までも含めて、どういうふうに優先順位をつけて事業をやっていけばいいのかというものが。","voiceIndex":161,"id":"exchange-071"},{"speaker":"山村委員","kind":"質問","question":"防災センターの維持管理費および展示・体験施設の運営費についてですが、防災対策費の中でもこの２点を合わせますと３,４００万円を超える歳出になっておりますが、防災対策費の中ではまあまあの割合だと思いますが、その割には、私が見ている限りではそんなに活用されていないような気がいたしますが、まず年間の利用者数は大体どの程度なのかということをお聞かせいただきますでしょうか。","respondent":"久保田防災課長","answer":"この中で、私どもも防災区民組織をはじめとして防災訓練の場、あるいはあらゆる機会を利用してＰＲに努めているわけですけれども、どうしても今年みたいに地震が若干多いときには、かなりの人数も見込めるわけですけれども。","voiceIndex":163,"id":"exchange-072"},{"speaker":"山村委員","kind":"質問","question":"３番目の質問に移らせていただきます。黒字にするというのは、人がたくさんお亡くなりになるということでいいことではないわけですから、いかに歳出を効率化を高めていって、お金がかからなくなるようにするというか、そういう努力を今後一層していただければと思いますので、今後斎場の運営費の削減についての効率化の考えをお聞かせいただければと思います。","respondent":"長田区民課長","answer":"こちらの運営につきましても、さまざまな委託や何かも含めまして、効率的な運営に努めていきたいというようなことで努力をしています。","voiceIndex":165,"id":"exchange-073"},{"speaker":"武内委員","kind":"質問","question":"私は歳出の１１２ページの選挙費に関連してお伺いしたいと思います。選挙の掲示板についてお伺いしたいと思いますが、これは選挙終了後にどのように処分される、もしくは利用されているのでしょうか、教えてください。","respondent":"野田口選挙管理委員会事務局長","answer":"もう一つ、支柱等も含めて、区の小・中学校あるいは児童センター等にお配りして、６月ごろの小学校の事例で、再生で家を建てたというような記事が載っておりましたけれども、そういったようなことで２０校近く、掲示箇所でいけば１５０カ所ぐらいの部分については。","voiceIndex":169,"id":"exchange-074"},{"speaker":"武内委員","kind":"質問","question":"本会議の第２回定例会で自民党の田中議員から掲示板についてご質問があったんですが、今回都知事選挙と区長・区議会議員選挙が重なったこともありまして、区民の方からは都知事選挙の掲示板を、区議会議員選挙はちょっと難しいにしても区長選挙のほうで再利用できないのか等々の意見があったんですが、そういった意味でリサイクル等をされているということで、また先日の第二定例会のところで、今後区長選挙。","respondent":"野田口選挙管理委員会事務局長","answer":"この利用につきましては、一応都知事選挙が終わった後、区議会議員選挙があるということで、都知事選挙と区議会議員選挙があるということを一体的に想定して、区議会選挙用にポスター掲示を立てて、それを都知事選挙にも活用していくというようなことで、４年後になりますか。","voiceIndex":171,"id":"exchange-075"},{"speaker":"武内委員","kind":"質問・要望","question":"小・中学校、児童センターのほうに再利用されて、非常に喜ばれているというお話も伺っているんですけれども、どこの児童センターか具体的に名前は挙げませんけれども、一部児童センターの屋上にポスターが何名かの分が見える形で立てかけてありまして、しかも掲示板はかなりあります。その実施における病院の基準等々がありましたら、教えていただきたいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"病院につきましては５０人以上の入所、それから老人ホームについても５０人以上です。ただ、特別養護老人ホームにつきましては、３０人以上の入所ということが基準になってあります。","voiceIndex":173,"id":"exchange-076"},{"speaker":"武内委員","kind":"質問","question":"そうすると、病院の中で、実際にどのような形で投票が行われているかということでお聞きしたいんですけれども、例えばどういった方が立ち会って、どういう状況の中で投票が行われるかということを教えてください。","respondent":"野田口選挙管理委員会事務局長","answer":"これは例外的な方法ということで、必ず最低２名です。それから、代理投票、自分で書けないといった場合については、もう１人補助者をつけて、必ず投票の秘密が侵されないような形で投票していただくということが仕組みです。","voiceIndex":175,"id":"exchange-077"},{"speaker":"武内委員","kind":"質問","question":"立会人なんですけれども、これは選挙管理委員会の方ではなくて、病院の施設長がやられるということですが、その方が第三者的になるとは思うんですが、病院と関係ないような方で立ち会うようなことというのはありますでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"この立会人の資格は、日本国民で２０歳以上という要件になってあります。指定施設の投票は区内に２１カ所ありますけれども、区民の方が全国いろいろなところの施設に入ってありますので、そういった意味では要件がそういうふうに緩和されているです。","voiceIndex":177,"id":"exchange-078"},{"speaker":"武内委員","kind":"質問","question":"そうすると、今回区長・区議会議員選挙、都知事選挙等が行われましたけれども、この中で病院による投票について、選挙管理委員会のほうで問題があったとか、そういった指摘があった等々のことがあったかどうかということをお聞きしたいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"結論から言えば、２１カ所の中では特に問題はないというふうに認識しています。","voiceIndex":179,"id":"exchange-079"},{"speaker":"武内委員","kind":"質問","question":"いろいろ配慮されていただいた結果、問題なかったです。おそらく近々国政になりますけれども、衆議院選挙が予定されておりますが、こちらのほうも品川区内の病院に関しては、品川区の選挙管理委員会で、そういった形の配慮をしていただけるのかどうかお伺いしたいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"４月に回ったばかりですので、今回は２１カ所回るということはしませんけれども、指定病院との打ち合わせということで打ち合わせ会を持ちますので、そういった部分では、引き続き選挙の適正な執行については協力を求めていきたいというふうに思ってあります。","voiceIndex":181,"id":"exchange-080"},{"speaker":"武内委員","kind":"提案","question":"これは一つ提案なんですが、目の前のそういった形でいろいろ啓発されることも、もちろん一番必要なことなんですけれども、特に中学生、高校生の若い世代の方々、行く行くは選挙権が出てくる方たちに啓発する意味で、目黒区だと思うんですが、本物の投票箱を中学校の生徒会の選挙に貸し出しをしまして、本物ということですごく緊張して、いい経験になった。","respondent":"野田口選挙管理委員会事務局長","answer":"投票箱のほかに、投票用紙の交付機あるいは計数機、あるいは選挙の七つ道具まで、要綱をつくりまして、チラシもつくりまして、小・中学校に私どもの職員が「使っていただくならお持ちします」というようなことで、校長先生あるいは教頭先生にご案内を差し上げて。","voiceIndex":183,"id":"exchange-081"},{"speaker":"武内委員","kind":"意見","question":"大変、失礼しました。私が存じなかったのであれなんですけれども、ただ、結構知らない方が多いんじゃないかなと思いますので、非常にいいことをやられているので、どんどんＰＲをしていただければいいかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":185,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"私からは１０８ページの広報費の中の区民相談経費関係と、時間がありましたら１０６ページの青少年対策費に関してご質問をいたします。","respondent":"山田広報広聴課長","answer":"区民相談室ではなく、あくまでも区民の声として広聴が受け付けたというところで説明をさせていただきたいと思います。私どものほうに陳情として平成１４年度来ておりますのが、８９件のうち項目的には３３６件と、大変多岐な内容で陳情をいただいております。","voiceIndex":187,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"１０８ページにあります区民相談、法律相談、各種相談等あるんですけれども、それらとの関係ですね。広報広聴課にさまざまなご意見等々、悩み事相談とか来られると思うんですが、そちらからこちらのほうに移管されるというケースがどれだけあるのか。それとも、ここを利用するときに、直接区民の方が利用されているという形になっているのか、その辺の関係を教えてください。","respondent":"山田広報広聴課長","answer":"ですから、必ずしも区民相談に来た方が私どものほうに不満があって、改めて陳情に来るというような正確のものとはちょっと違いますので、リンクという話にはならないかというふうに考えてあります。","voiceIndex":189,"id":"exchange-084"},{"speaker":"西本委員","kind":"質問","question":"私が考えるには、ある程度のことは説明ができるんじゃないかと。すべてが各所管のほうに行くということ、確かに責任という範疇もありますので全部は難しいというところはあるかと思いますが、先ほど言った各種相談の窓口に紹介するという状況の判断ができるのであれば、そこである程度の解決ができるんじゃないかなというふうに考えるんですが、いかがでしょうか。","respondent":"山田広報広聴課長","answer":"ただし、事実関係をきちんととらえるというところについては、所管と私どもときちんと連携を取って、そのとき即答できないことについては、後ほど調べてお答えをするということで、比較的内部的なやり取りの中だというふうにご理解いただけたらというふうに思います。","voiceIndex":191,"id":"exchange-085"},{"speaker":"西本委員","kind":"意見","question":"その場合、苦情処理という形での担当の専門的なところがあってもいいんじゃないかなというふうに考えていまして、例えば書面で出したり、必ず区のほうから返答がいただけるということなんですけれども、結構時間がかかっているというケースがありまして、なるべく早くということは努力されているとは思うんですが、ちょっとした情報があれば２週間待たなくても。","respondent":"山田広報広聴課長","answer":"やはり、それぞれの事業課の法的な内容であるとか、いろいろな拘束のある中で事実関係を調べて、これはきちんとできるかできないかという判断を聞いた上でお答えしなければならないときは、一定の時間がかかっております。","voiceIndex":193,"id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと時間もなくなってきていますので、要望という形でお願いしたいんですけれども、確かに今の流れでするというのは、正規のルートで正しいのかもしれません。区内の中でいろいろな団体がそれぞれにやっているんですが、どうも横のつながりがないような感じがするんです。児童福祉調査会の今回の諮問においても、私たちもいろいろ考えている。","respondent":"志村地域活動課長","answer":"私ども青少年対策地区委員会のいろいろな活動の中で、一番今困っているのが、実は中高生の取り組みです。私どものほうではさまざまな機会で参加をいただけるように、それと一歩進んで参画をしていただけるということを今お願いしています。","voiceIndex":195,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"それらがばらばらでやっているというのは、あまり効率的ではないような気がしますので、その辺を区のほうでやっている事業なのでまとめるとか、お互いの情報交換をしていくというような仕組みづくりをしていただけたらもっと効率が上がって、いろんな方たちが係われるのではないかなというふうに思っているんですが、その点、ご意見をお聞きしたいと思います。","respondent":"志村地域活動課長","answer":"品川区の青少年行政の指針といいますか、方向を定めるべく年２回行ってあります。７月、２月ということで、例えば夏休み前、新学年に移る前ということで、さまざまなそういった機会をとらえて、その中でこれからも進めていきたいというふうに考えてあります。","voiceIndex":197,"id":"exchange-088"},{"speaker":"西本委員","kind":"提案","question":"ですから、そこはばらばらでやるのではなくて、やっぱり中高生に対して、地域の方たちも何とかしなければいけないという気持ちが多いものですから、横のつながりをつくっていくというのが、やっぱり区のほうの役割ではないかなというふうに思いますので、ぜひとも今後そういう仕組みづくりに、こちらも提案していきますけれども、つくっていだけると大変ありがたいなというふうに思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":199,"id":"exchange-089"},{"speaker":"塚本委員","kind":"質問","question":"１０７ページの生活安全推進事業に関連してお伺いします。今日も二、三の方から治安ということで質問が出てきております。ピッキング、それから空き巣、青少年のドラッグと、いろいろ問題が出てきておりまして、どうしたらいいだろうか。そういう視点でものを見られるのも一つの仕事だろうと思いますが、現時点ではどのようにお考えですか。","respondent":"杉浦生活安全担当課長","answer":"現時点で連携についてどのように考えるかということでございましょうか。現在におきましては、第一歩を踏み出したわけですけれども、安全については警察の仕事であるという部分がまだまだというのがはっきり申しまして、私見ではありますが私の見解です。","voiceIndex":201,"id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"ある部分、警察ではなくて、そこは自治体が積極的に関与しなければいけない時代が来ているというふうに思っております。そういう時代になって、非常にプライバシーがわしづかみされている状況が一歩手前まで来ているということを考えると、監視社会に向かっていくことに対して、自治体はどういうスタンスを取るかということをそろそろ議論しなければいけないと考えていますけれども、いかがでしょうか。","respondent":"太川区民生活事業部長","answer":"私も、今そういう状況の中で、常に監視されているという、常に見張られているという状況につきまして、まだ具体的に体験している部分というのはないものですので、これからその状況につきまして、どういうふうに我々としてとらえていくのか。","voiceIndex":203,"id":"exchange-091"},{"speaker":"塚本委員","kind":"質問","question":"商店街の規定の中でという、「俺は見張るぞ」と言って見張る人はいないわけでして、徐々にそういうところからじわじわとならされてくるということがあるわけで、そういうことを行政が補助金という手段で関係したということになってくるわけですから、一歩先には間違いなくそういうことをどうするんですかということを考えなければいけない、そのことを聞いているわけです。","respondent":"太川区民生活事業部長、中尾根企画部長","answer":"やはり、その辺につきましては、こういう社会が到来しているということと、監視カメラの設置等々も含めまして、生活安全については真剣に今後議論して検討していかなければいけない課題だと思ってありますので。したがいまして、地域全体としてこれを見守るという形がどうしても必要でございまして、そのためのコミュニティーの醸成ということを今後区の方針として持っていかなければならない、こういう見解に立ってあります。","voiceIndex":205,"id":"exchange-092"},{"speaker":"塚本委員","kind":"意見","question":"視点を投げかけさせていただきました。犯罪が厳しくなっている、特に繁華街では想像を絶するような事件が起きていると承知しておりますけれども、一方でそういう心配がある。議論をする入り口に来ていますよということを指摘させていただいて、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":208,"id":"exchange-093"},{"speaker":"三村委員","kind":"質問・要望","question":"２年ごとに見直しということで、今後見直されていくときにはこういった視点が入っていくのか、そして少子化対策について別に調査をされているというだったんですけれども、もし少子化対策、子育て支援対策についてほかに調査等がございましたら、どういった調査をされているのかと内容、そして検証結果を教えていただければと思います。","respondent":"山田広報広聴課長、榎本行財政改革担当課長","answer":"ですから、改めて来年の調査の期間になりましたら、また所管の中で新しい課題として何を取りたいかというところをとらえながら、実施してまいりたいというふうに考えてあります。例えば、夫婦のほうですと、実際に子どもがいる人数と理想としている人数の差がどれぐらいかというものも回答の中に出てきておりまして、実際に平均的な人数として１.３人の子どもに対して。","voiceIndex":210,"id":"exchange-094"},{"speaker":"三村委員","kind":"質問・要望","question":"少子化対策ということで、重要な課題にはなっているんですけれども、品川区の中で所管するところが、次世代育成対策ということでやられているかと思うんですけれども、この世論調査の中にも入らないということは、重要な課題であるにも係わらず入らないということは、これから要望があればということなんですけれども、次世代育成をどういうふうに取り組んでいくのか。","respondent":"山田広報広聴課長、榎本行財政改革担当課長","answer":"決して少子化が重要ではないということではなくて、第１３回世論調査で一度少子化については、区民の皆さんからどういう問題意識を持っているのかお聞きしておりましたので、それについてはやっていないということで。実際に国が求める行動計画のものがかなり網羅されておりますので、まずそれの現状分析なり実績なりの検討をした上で、必要であれば調査の部分もしていくというような形で考えております。","voiceIndex":213,"id":"exchange-095"},{"speaker":"三村委員","kind":"質問","question":"インターネット等経費についてお聞きしたいんですけれども、アクセス件数を見ますと、大分利用状況が定着してきたかなと思いますけれども、これからインターネットによる意識調査ですとかアンケート調査の実施を計画されているとお聞きしておりますけれども、内容を教えていただければと思います。","respondent":"山田広報広聴課長","answer":"現在やっておりますのは、それほど深いものは難しいであろうということで、イメージ調査的な部分が大変合ってくるだろうというふうに思っておりますけれども、今後の開発の中で充実した内容にさせていきたいというふうに考えております。","voiceIndex":216,"id":"exchange-096"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ、インターネットを利用して、これから始まる次世代育成の行動計画策定については、ニーズ調査をしっかり踏まえて、市民参加ということでぜひやっていただきたいと思うんですけれども、市民参加という観点で、これから次世代育成についてどのような取り組みをされていくのか、もしよろしければお伺いしたいと思います。お答えをもって終了とします。","respondent":"榎本行財政改革担当課長","answer":"その審議会につきましては、国のほうも既存の審議会等も含めて考えてもよろしいという形になっておりますので、既存の審議会でやるか、それとも新たに立ち上げるか、その辺も含めて検討していきたいと考えております。","voiceIndex":218,"id":"exchange-097"},{"speaker":"飯沼委員","kind":"質問・要望","question":"職員の方々が健康で笑顔で仕事をしていただきたいという立ち場で質問をしますけれども、最初にちょっと厳しいところか入ってつらいんですが、私がびっくりしたのが、在職のままで亡くなられた方が平成１４年は８名もいらっしゃったということで、非常に驚いているわけですが、まず、亡くなられた原因とここ数年来の傾向を教えていただきたいのと。","respondent":"桑村人事課長","answer":"死亡者の人数ですけれども、平成１０年が４名、平成１１年度が６名、平成１２年度が８名、平成１３年度が３名、平成１４年度が８名です。どのような原因で亡くなられたかということですが、一つ大きいのは病気が高じられて亡くなられた方が一番多いということです。","voiceIndex":221,"id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３カ月以上の長期病欠者の人数はお伺いしたので、平成１４年度が１１名、休職者が１４名ということなので、この辺の病名を教えていただきたいのと、この間の傾向がもしあったら教えてください。","respondent":"桑村人事課長","answer":"今、お話がございましたけれども、細かい病名は避けしますけれども、休職も長期の病欠を同じですけれども、一つは難病というんでしょうか、ある程度長くかかる病気にかかられて、治癒できないということで休まれている方が長期の病欠を過ぎまして。","voiceIndex":223,"id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問","question":"残業についてですけれども、どういうふうにお伺いしたら全体が見えてくるかなと悩んでいるんですが、１人当たりの１カ月の時間数というのは出ますでしょうか。病気にならない健康を保っていくためには健康診査が行われていますけれども、この辺の受診率と、安全衛生委員会というのがあると思うんですけれども、その辺の役割が大変大きいと思うので、病気にならない対策についてお伺いしたいと思います。","respondent":"桑村人事課長","answer":"これに対する対応ですけれども、基本的に健康診断の結果等も留意いたしまして、特に何らかの対応が必要だという職員につきましては、私どものほうにお呼び申し上げまして、産業医等の面談をしまして、その結果何らかの対応が必要だ。","voiceIndex":225,"id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問・要望","question":"健康診断の受診率は９６％ということで、かなり高いので、こういうところで早く発見をして治療していく。安全衛生委員会は使用者と労働側の両方で出席をして行われているということを伺っていますけれども、月に１回開催されているということですけれども、今年度は何回ぐらい開催をされているのか教えていただきたいと思います。","respondent":"桑村人事課長","answer":"月に１回というのは、清掃事務所は月に１回やってあります。それから、総括的な安全衛生委員会につきましては、研修会あるいは安全衛生委員会を含めて、今年は１１月で研修を含めて３回やる予定です。","voiceIndex":227,"id":"exchange-101"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私も仕事を始めてしまうと、構わずに何時間も画面を見続けたりして、すごく疲れたりするんですけれども、その辺の時間の管理もちゃんと教わっていないと、自分の体をむしばんでいることに気がつかないというのがあると思うので、その辺をどのぐらい働いたら休みなさいとか、姿勢も画面を見るときに上を向いたりするとドライアイになっちゃうとかいろいろあるので。","respondent":"桑村人事課長","answer":"今の作業時間のことですけれども、例えば４５分を過ぎますと、非常に疲労もしますし、また目にもよくないということで、小休止を取るべきだとか、あるいは作業形態によっては非常に続けて打たれているような方につきましては、もう少し頻繁に取るべきだとか。","voiceIndex":229,"id":"exchange-102"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは要望で終わらせていただきます。次に、非常勤の雇用について、どこで聞いたらいいかよくわからないんですが、今日は総務費ということで、全体的にお伺いしたいんですが、一つは非常勤職員の項目はどこに載っているのか、まずそこから教えてください。","respondent":"桑村人事課長","answer":"保育園ですとかあるいは学校、図書館等で働かれている非常勤の方は、専門というよりもむしろ正規職員と一緒になって働いていらっしゃるような方につきましては、同じくそれぞれの科目の中で計上しています。","voiceIndex":231,"id":"exchange-103"},{"speaker":"飯沼委員","kind":"質問・要望","question":"非常勤の全体のところは、総務費のところでお伺いすればわかるんでしょうか。非常勤の方が品川区の中に何人いらっしゃるのかというのと正規職員との比率、それからどのような形態で働いていらっしゃる方が多いのか、例えば１日何時間で週何日とか、どのぐらいの形態が中心なのか教えていただきたいと思います。","respondent":"桑村人事課長","answer":"形態ですが、今、資料を持ってございませんけれども、非常に時間的なものあるいは先ほど言った専門的な方は月２回ですとか、そういうふうな形態ですので、まさに非常勤ですのでばらばらというのが一般的です。","voiceIndex":233,"id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問","question":"非常勤だからばらばらということ、そのとおりだと思います。一つは、雇用保険とか健康保険、厚生年金保険に加入されている方の割合が、先ほどの９５８名の中でとのぐらいいらっしゃるのかお伺いしたいのと、もし入っていらっしゃらない方がいたら、なぜ入っていないのか、その辺の理由も教えてください。","respondent":"桑村人事課長","answer":"これは入る条件がございまして、例えば雇用保険ですと、月２０時間以上、１年以上勤めることが条件とか、普通の健康保険ですと職員の大体４分の３ぐらいの勤務時間、これは社会保険事務所によってはいろいろあるようですけれども、大体そのぐらいが平均になってあります。","voiceIndex":235,"id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問・要望","question":"長い時間働きたい、例えば月１３日間とか、日に５時間ではなくて、できたら８時間働きたいし、もっと長い日数を働きたい。１年の雇用ではなく、安定して更新して働き続けたいとか、通勤手当も当然出してほしい。そのためにぜひ研修を十分にしていただきたいという声、もっと時間をかけて定期的に、最初だけではなくてもっと繰り返しやってほしいんだという、こういう声をたくさんいただいています。","respondent":"桑村人事課長","answer":"その意味で８時間勤務ということの条件であれば、これは正規職員で対応するのが基本だろうと思ってあります。その意味では、有機的雇用ということで、どうしても１年ですけれども、その中で力を発揮していただくというのが、今の区の考えです。","voiceIndex":237,"id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問・要望","question":"８時間働きたかったら正規対応でというところですが、新規採用がないというところでは、どんなに優秀な方でもなかなか採用されない状況があると思うんですけれども、私は今の答弁からすると、やはり限りなく人件費を少なくするために、優秀な方を使い回しているというような状況があると思います。これは強い要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-107"},{"speaker":"土井委員","kind":"質問","question":"今、安全衛生委員会のお話がございました。その中で、清掃の皆さんは毎月きちんと開いているというお話がございました。働く者にとっては、経済的な賃金、一時金等々の問題に加えて、安全衛生というのは非常に大きな課題です。そこでお伺いしたいんですけれども、教職員、学校現場における安全衛生委員会というものについては、どのようになっているのかお伺いをしたいと思います。","respondent":"鷹倉庶務課長","answer":"人事課長からもお話がございました。私どものほうは給食安全衛生委員会という形で、定期的に開かせていただいているということです。学校現場を視察したり、ときどきの課題を検討していくという形でやらせていただいているというのが現状です。","voiceIndex":241,"id":"exchange-108"},{"speaker":"土井委員","kind":"質問","question":"区の職員については、一定のそういう形のものがあるなというのは、薄々お話を伺っていてもわかったんです。問題は学校なんです。学校の教職員は、都費職員ではありますけれども、派遣をされているのが区立の小・中学校なんです。そうすると、そこの職場における安全衛生委員会というのはどうなっているんですかというふうにお伺いをしているんです。","respondent":"鷹倉庶務課長","answer":"学校ですので、学校の校長が把握しているですけれども、定期的に今のところ開催されていないという現状だと思います。","voiceIndex":243,"id":"exchange-109"},{"speaker":"土井委員","kind":"質問","question":"特に教員の話です。いわゆる都費職員の問題です。うちの親も教員をしておりましたけれども、結核にやられていろいろありました。そういうことも含めて考えると、どうなっているんだろうということでお伺いしています。","respondent":"古川教育次長","answer":"実際に学校における安全衛生委員会につきましては、都費ではなくて区費の部分については私のほうが責任という形で実施しています。今、お尋ねの教職員ですが、制度としては確かに持ってございません。","voiceIndex":245,"id":"exchange-110"},{"speaker":"土井委員","kind":"質問","question":"学校の先生方も労働者という言い方が適切であるかどうかは別ですけれども、そういう皆さんの健康を自らでいろいろ話をするのは、どなたと一緒に話をしたらいいのかということになるわけです。したがって、区として教育委員会としてきちんと安全衛生委員会をつくってやっていく、こういう方針を打ち出すべきではありませんか、どうですか。","respondent":"若月教育長","answer":"ただいまご指摘いただきました点につきましては、これから本区におきましても、それに対応できるような体制をこれから考えていきたいと、かように思っています。","voiceIndex":247,"id":"exchange-111"},{"speaker":"川西委員","kind":"質問","question":"質問いたします。私立幼稚園の預かり保育モデル事業。質問の１番目は、事業の目的、そして平成１４年度の利用人数、これは総人数で結構です。それからもう一つは、モデル事業として結構経過をしておりまして、平成１５年度もまだモデル事業ということで予算上は執行されておりますが、これがモデルという文字を消して本実施に移行できるのはいつ頃になるのか、今後の方向について伺います。","respondent":"宮地総務課長","answer":"きんだぁくらぶのお尋ねです。この目的ですが、私立幼稚園の在園児を対象にいたしまして、通常の時間外等、夏休み等に保育園と同じ時間帯で預かり保育を実施するもので、保護者の多様の保育ニーズにこたえるとともに、子育て支援、私立幼稚園の振興を目的とした事業です。","voiceIndex":251,"id":"exchange-112"},{"speaker":"川西委員","kind":"質問・要望","question":"今後、モデル事業から本事業への執行をできるだけ早くしていただきたいと思います。そういう点で、お願いしたいと思います。そういう点では、ぜひ公・私立合わせて、東海道から海側のほうの実施についての来年度予算における実施を強く要望をいたします。平成１４年度の備蓄物資の状況ですが、何をどういうふうに入れ替えたのか、賞味期限のすれすれのものを入れ替えて、どのように活用されたのか伺います。","respondent":"久保田防災課長","answer":"期限はそれぞれまちまちですが、例えばアルファ化米については５年ぐらいですけれども、一応期限間近のものにつきましては、防災訓練の焚き出し訓練に使ったり、町会等が独自にやる訓練に使ったり。","voiceIndex":253,"id":"exchange-113"},{"speaker":"川西委員","kind":"質問・要望","question":"その処分が問題だと思います。せっかく賞味期限がまだあるのに、処分をしてしまうということは、これからの時代に考えていかなければならない。こういうふうに、防災訓練に来られない人たちに試食をしてもらうという機会を、今後考えていただきたいと思いますが、いかがでしょうか。","respondent":"久保田防災課長","answer":"学校等でも町会の人とやっている場合もありますので、そういうときには焚き出し訓練で使っていただいていますし、またご要望があったときには、私どもはできる限りおこたえしているわけですけれども、それでも大量に抱えておりますので。","voiceIndex":255,"id":"exchange-114"},{"speaker":"川西委員","kind":"質問・要望","question":"防災訓練に参加できる人、あるいは学校のいろんな行事に参加できる人はいいんですけれども、アルファ化米の炊き方とか、味をどうなんだというときに、子どもたちに持って帰ってもらうということも大変いい試みだというふうに、品川区以外のところで聞いてきました。いろいろ有効利用ということで、活用を順次進められておりますが、旗の台の寮についての再検討を、ぜひ強く要望をして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-115"},{"speaker":"山路委員","kind":"質問・要望","question":"３点ほどお伺いいたします。私も平成１３年の決算特別委員会の総括質問の中でお伺いいたしましたけれども、職員の方が非常に細かいことで苦労されている。そこで観光協会とか、文化振興事業団とか、委託されたほうがいいんじゃないでしょうかということで、あれから２年経ちますが、その後どういう検討をされたかお聞かせをいただきたいと思います。","respondent":"長田区民課長","answer":"こちらにつきましては、やはり交流事業というようなこともありまして、自然の中で体験をしていただく貴重な経験にもなるということで、私ども内容の充実を図っていきたいというふうに考えてありますけれども、今のところ区が仲立ちをするような形で。","voiceIndex":259,"id":"exchange-116"},{"speaker":"山路委員","kind":"確認","question":"一つ、確認しておきたいんですけれども、小・中学校との姉妹交流等も行われているんでしょうか。いろんな農業体験とか、そういうものは承知しているわけですが。もう一つ、民間レベルでというと、今と同じ底辺が広がらないんじゃないか。思い切って、ここで委託という方法を検討されたらと思うんですが、どのようにお考え方でしょうか。","respondent":"長田区民課長","answer":"そういった中で、今後民間の持っている活力をどう活用していくのかという部分につきましては、私ども検討してまいりますけれども、当分の間は区が中心になって交流を続けていくべきかと思っているところです。","voiceIndex":261,"id":"exchange-117"},{"speaker":"山路委員","kind":"質問・要望","question":"方法を考えていただきたいということです。今日、山北町と早川町のホームページを開いてみたんです。もっとそういう深いつながりを持って、もっと多くの区民の方が行って楽しめるようにしていただきたいことを要望しておきます。続きまして、インターネット等経費につきまして、バナー広告についていろいろ研究をされているですが、どういう研究をされているかお伺いいたします。","respondent":"山田広報広聴課長","answer":"バナー広告につきましては、現在品川区ホームページ広告掲載取扱要綱を作成いたしまして、７月から私どもの職員が区内の大学等に営業活動をいたしまして、早ければ１０月からバナー広告を掲載していく予定でございましたけれども、大学の中で窓口も含めてつくっていただく部分。","voiceIndex":263,"id":"exchange-118"},{"speaker":"山路委員","kind":"質問・要望","question":"バナー広告は品川区にとってはプラスになるから喜ばしいことだと思いますけれども、課題はないんでしょうか、その点の研究から何かあったらお知らせいただきたいと思います。","respondent":"山田広報広聴課長","answer":"そこでの部分で、今、大学と申しましたけれども、大学も年度途中ですと予算の計上ができないということで、来年度からお願いしたいとか、１カ月だけ掲載できないかとか、いろいろな経済事情があるということを、初めてこの営業活動の中で私ども把握をいたしまして。","voiceIndex":265,"id":"exchange-119"},{"speaker":"山路委員","kind":"質問","question":"バナー広告につきましては、大変苦労して研究をされているということをお伺いしておりますので、成功されることを祈っております。町会長に相談したところ、家に倉庫があり置いてくださるとのことで、また雨にも盗難にも心配もなく置くことができますので、何とか区のほうでリヤカーを補助していただけませんでしょうか」という相談ですが、どのようにお考えでしょうか。","respondent":"久保田防災課長","answer":"これからもワークショップ等をやっていただいて、そういう形で町会のほうでも要援護者の取り組みに強めていただければ、そういう資機材の充実等についても、やはり今後検討していきたいというふうには考えております。","voiceIndex":267,"id":"exchange-120","title":"町会・自治会支援"},{"speaker":"山路委員","kind":"質問・要望","question":"町会によっていろいろ要望も違うと思いますが、そういう条件で検討していただくということですので、要望がありましたら、どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-121"},{"speaker":"石田委員","kind":"質問","question":"私は成果報告書１０６ページ、地域振興事業に関連して質問をしたいと思います。先ほど、塚本委員からも地域のコミュニティーというお話がありました。自らのまちは自ら地の手でつくり上げていこう。それでさまざまな施策を打っているわけでしょうから、現在の状況をどういうふうに考えていらっしゃるのかお聞かせ願いたいと思います。","respondent":"志村地域活動課長","answer":"大変、難しいお尋ねです。ただ、私ども日常的に区政協力委員会等々で町会長の方と、その中でいろいろご議論をいただいてあります。その中で必ず言われますのが、高齢化している、それと町会に加入されている方が少ないということは聞いてあります。","voiceIndex":271,"id":"exchange-122"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう形で私も結構だと思いますが、今いみじくも言って、参加の問題があります。この辺読めば読むほど、みんな地域の方とともに参加をしていただいて、ともになってやっていこうというようなことがくまなく書かれているわけだけれども、この辺の点をもう一度改めて教えていただきたい。","respondent":"志村地域活動課長","answer":"私どものほうでは、このたびふれあいサポート活動を始めてあります。この中のきっかけになりましたのが、実は地域福祉計画です。品川区では福祉に関する取り組み、主にハード面、ある一定の部分はでき上がっただろうという考えです。","voiceIndex":273,"id":"exchange-123"},{"speaker":"石田委員","kind":"質問・要望","question":"そのとおりで結構なんですが、地域活動の拠点づくりというか、地域の皆さんとともになってやっていこうということです。その施策を打つときの考え方、今、地域の方とともにやっていこうという施策の考え方、そういう考え方の中においてさまざまな施策を打っていると、最初に考えるときですよ、そういう形で理解をしていいのかどうか教えていただきたい。","respondent":"志村地域活動課長","answer":"私どもはあくまでも地域コミュニティー、例えば地域センターは建物をつくっただけでできるとは考えてございませんので、地域に応じたきめ細かな福祉を進めるにあたっては、町会をはじめとした多くの地域の方々と一体となって進めないと。","voiceIndex":275,"id":"exchange-124"},{"speaker":"石田委員","kind":"質問","question":"改めてお伺いしたいんですが、そうなってくると、一体となって取り組もうということは、相手がどういう状態であるかということを、もちろん把握をしてやっていくことだろうと考えています。もちろん、今課長のところですべてを把握できないと思うし、教育も絡んできたりしたらたくさんあるわけで、そういうものをどこかで、これは大体これぐらいの数だというのをまとめているところはあるんでしょうか。","respondent":"志村地域活動課長","answer":"周年行事あるいは町会会館を新しくリニューアルしましたというときにご案内をいただいている例があります。それと全庁的にまとめているかということですけれども、私どものほうではそのようなことは聞いてございません。","voiceIndex":277,"id":"exchange-125"},{"speaker":"石田委員","kind":"質問","question":"そうなってくると、さまざまここに第三次長期基本計画含めて書いてありますが、区の施策を打っていくものと、参加をしてもらう部分のバランス、また参加をしていく部分のバランス、この辺のバランスを、もちろん区が強制的にやっていくということがすべていいとは思いませんし、逆に区民が参加してくれる、それをもっとやっていったほうがいいわけですけれども。","respondent":"志村地域活動課長","answer":"私どものほうでは、なるべくそういった意味で町会に参加していただく、あるいはそうした中でもっと若返りといいますか、多くの若い人に参加していただけるような指導も合わせて行っていきたいと思ってあります。","voiceIndex":279,"id":"exchange-126"},{"speaker":"石田委員","kind":"質問","question":"今の話をするのであれば、具体的に若い人をどうやって町会に参加をさせる、ボランティア団体に参加をさせる、具体的に何をやっているか教えてください。","respondent":"志村地域活動課長","answer":"ある地域ですけれども、先ほど申し上げましたように区民まつりに参画をしていただいたというような例があります。は地域の清掃等をやっていただいているところもあります。こうした活動を、これからも増やしていきたいというふうに考えてあります。","voiceIndex":281,"id":"exchange-127","title":"町会・自治会支援"},{"speaker":"石田委員","kind":"質問・要望","question":"これだけ学校も含めて全部のところに参加を求めているのであれば、それなりの支援をどういうふうにしていくかというところとか、逆に区が出ていく部分は我々のほうでやりますよというある程度の仕分けがないと、ふれあいサポート活動はいいけれども、ずっと増えていくだけみたいな形になって、本当に下請けみたいな形になっているというのは、私は非常によくないと思うので。","respondent":"太川区民生活事業部長","answer":"それは単に福祉だけの部分ではございません。そういうことで取り組んでまいりますので、ご理解いただきたいと思います。","voiceIndex":283,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"今、せっかく石田委員から質問がありましたので、まず成果報告書の１０６ページ、青少年対策費について、それから１０９ページ、防災対策費、１０４ページ、私立幼稚園関係費について質問をします。そのような青少年対策ということで動いているわけですけれども、それでいいんでしょうかということで、その辺のご見解をお解きかせください。","respondent":"志村地域活動課長","answer":"地区委員会の取り組みです。私どものほうでは、地域センター単位に毎年１３地区にそれぞれ地区委員会を設けてございまして、それぞれの委員会に事業を委託していますので、それぞれの各地区委員会でそれぞれ内容、行事等を決めてあります。","voiceIndex":286,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただいまお聞きしましたけれども、一応行事に関しては区のほうで、こういう行事をやってくれということで、我々町会のほうには「今年はどのような行事をいたしますか」という問いかけは一切ありません。何ヶ月後には近くでラジオ体操をやりました。町会のほうにもっと話を持っていってやっていただきたいと思います。その辺、よろしくお願いします。","respondent":"志村地域活動課長","answer":"青少年の地区委員会の取り組みです。先の石田委員のご質問にもお答えしたとおり、なかなか参画していただける方が少ないというのが現状にあります。","voiceIndex":288,"id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"引き続きまして、防災対策費についてお伺い申し上げます。そういうことも加味しまして、ぜひその地域に避難場所等の確保をお願いしたいと思います。そして、またそこの場所に水、食糧、医療品、消火器、担架も含めまして用意してあれば、かなりの人命が助かるんじゃないかと思うんですけれども、その辺区長に質問してもよろしいでしょうか、ちょっとお答えいただければありがたいと思います。","respondent":"久保田防災課長","answer":"ただ、これは一時的に火災の避難を避けるところですので、本来の避難所はやはり学校に行っていただく。そこには一定程度の食糧とか仮設便槽等も用意していますので、そういう形で今後も対応していきたいというふうに考えているものです。","voiceIndex":290,"id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"区民サービスの点におきましても、保育料について同じ土俵の上でサービスを提供すべきではないかなと。それは区が事業として私立幼稚園の事業を脅かす一つの問題じゃないかなと思うんですけれども、その対策としまして、現在の区立幼稚園の保育料を上げるべきではないと思うんですけれども、逆に私立幼稚園の補助金を上げて同一にして、同じ土俵の上で子どもたちを育成していくという考え方はどうでしょうか。","respondent":"宮地総務課長","answer":"格差是正のための区の上乗せですが、全体の総額を１０といたしますと、４が東京都の補助金、６が区の上乗せ分ということで、かなり力を入れて取り組んでいるという状況です。","voiceIndex":292,"id":"exchange-132"},{"speaker":"木下委員","kind":"質問","question":"主要施策成果報告書の中の１０９ページ、防災対策費に関連いたしまして四つほど質問をします。その点で、弱者の避難の観点じゃないですけれども、避難誘導ワークショップで見直しをされているかとは思うんですが、区のほうではその辺の大幅な見直しですとか、チェックをされていらっしゃるんでしょうか。","respondent":"久保田防災課長","answer":"これを地域の方たちの協力で、１人ではなくて何人かがグループになってやるという訓練をやってあります。私ども昨年の小山二丁目の東部町会を皮切りに、今年は４地区ということで５地区実施しております。","voiceIndex":298,"id":"exchange-133"},{"speaker":"木下委員","kind":"質問","question":"本当にいつ起こってもおかしくないですから、早急に避難路の再検討をお願いいたしたいと思います。特に密集住宅市街地においてでは、避難道路および避難道路に準ずる道路の両側２００ｍ以内の地域は大体６０ｍ間隔でやっているということですから、そのぐらいの間隔では危険度の高い地域においては設置すべきだと考えているんですけれども、区の考えをお聞きしたいと思います。","respondent":"久保田防災課長","answer":"消火器整備のことですけれども、まず街頭消火器につきましては、区内約８０ｍから１２０ｍごとに区全体で５,３００本強設置しております。これは２３区でもトップクラスです。他区は、これほど設置していないという状況があります。","voiceIndex":300,"id":"exchange-134"},{"speaker":"木下委員","kind":"質問・要望","question":"本当に実際に言われるとおり、取り出しやすいところに消火器を置いておくというのは、家庭の防災意識のあらわれでもありますし、重要だと考えています。現実問題は、私も防災支援ボランティアをやっていますけれども、なかなか取り出しにくい。それから、確認なんですけれども、町会の要望があればどんどん設置していく、場所があればということも含めて、そういう認識でよろしいですか。","respondent":"久保田防災課長","answer":"それからもう一つは、街頭消火器は維持管理が非常に難しいという面があります。よく暮れになると、中の消火器を取り出して消火器をばらまいてしまうというようなことが数回あります。","voiceIndex":302,"id":"exchange-135"},{"speaker":"木下委員","kind":"質問","question":"続きまして、防災区民組織の件で質問をします。各町会・自治会に区民消火隊ですとか、防災ポンプを置いて消火隊を設置されていらっしゃると思うんですけれども、品川区内の何町会、何自治会があって、そのうち動力ポンプですとか、小型防災ポンプを設置して、実際に機能させている町会・自治会がそのうちの何割ぐらい、また何箇所ぐらいあるのかお聞きしたいと思います。","respondent":"久保田防災課長","answer":"なかなかそういうふうにできないところにつきましては、年に１回機械を動かしてやってほしいという私どもの要望もありますので、地区訓練に出て消火の一斉放水などの訓練に参加しているという状況です。","voiceIndex":304,"id":"exchange-136","title":"町会・自治会支援"},{"speaker":"木下委員","kind":"質問","question":"そういう訓練をされていらっしゃるということなんですが、区民消火隊６６隊、ミニポンプ隊１８８隊の全部がそういう訓練をやっていらっしゃるのでしょうか。","respondent":"久保田防災課長","answer":"中には、休眠状態というものもあります。そういう場合には、できるだけやってほしいということで、私どもは積極的に声かけを行っているという状況です。ほとんどのところは、年１回は訓練に参加して動かしています。","voiceIndex":306,"id":"exchange-137"},{"speaker":"木下委員","kind":"質問・要望","question":"最後にもう１点、品川区総合防災訓練について質問をします。私も上級救急救命の資格を持っているんですけれども、この訓練では初級の認定書を受けている方がやっていらっしゃるかと思うんですが、また資格の有効期限は３年ですけれども、現在何人が資格を持っていらっしゃるのでしょうか。それから、防災区民組織の中で、それをどのように活用されていらっしゃるのかお聞きしたいと思います。","respondent":"久保田防災課長","answer":"実際の災害時には、こちらの方をボランティアとしてどういうようにして活用していくか、今後検討していくというようなことを考えているところです。それから、町会の中で資格をお持ちになっている方がどのぐらいいるかというのは、私どもはちょっと把握できない状況です。","voiceIndex":308,"id":"exchange-138"},{"speaker":"木下委員","kind":"質問","question":"せっかくそういう訓練を行っているわけですから、心肺蘇生ですとか、いざというときにけがの手当てができるようになるわけですから、これからも多くの方に指導してくださるようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１０８ページの広報費、情報公開と区民参加についてお聞きしたいと思います。先ほど、広報広聴課のほうに区民からの意見や声がどれぐらい届いているかというでは報告がありましたけれども、その中で保育や学童に関してどれぐらい出されているのか、平成１３年、１４年、１５年度の３年間にわたって教えていただけないでしょうか。","respondent":"山田広報広聴課長","answer":"その中の福祉事業部が３４件になってございまして、保育園については２件、乳幼児医療等について８件、子育て支援、学童保育についても２件というような、アバウトな数字ですけれども、そのような中身です。それが平成１４年度です。","voiceIndex":312,"id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回、学童保育のすまいるスクールへの移行というのが６月３０日に厚生委員会に報告されて、私たち議員にもメールとか手紙とかたくさんいただいているんですけれども、学童保育のすまいるスクールへの移行については、広報広聴課にどれぐらい来ているのか、そしてその内容についてもどんなものが来ているのか教えてください。","respondent":"山田広報広聴課長","answer":"説明会後については「説明会をもう少し開催を増やしてもらえないか」ということ。それから、これは学童保育からの声なんですけれども、「すまいるスクールと学童保育とは別機能なので残してほしい」などというような声が届いている状況です。","voiceIndex":314,"id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区はホームページで情報公開・情報提供について、こういうふうに書かれているんです。そして父母に説明してくださいという要望書や意見が品川区のほうにたくさん出されてきたと思うんです。６月３０日に厚生委員会に発表されてから、８月２６日に９学童保育クラブを閉鎖するという報告までの２カ月間、児童課としてどのようにこの問題について対応されたのかお聞かせください。","respondent":"山田広報広聴課長","answer":"区については、条例の中でも情報提供に努めていくというのは確かに明言されておりますけれども、情報公開については私どもでは受け付けしていないです。","voiceIndex":316,"id":"exchange-142"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"広聴広聴課に学童保育連絡協議会が８月８日に要望書を出して、８月２８日に回答をいただいたと。保護者会で意見を聞いているから、これで学童保育のすまいるスクールへの移行をしていくんだという答弁なわけですけれども、保護者会の中では一体学童クラブを閉鎖してくれという意見が父母の中から出されたんでしょうか、このことについてお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-143"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは広報広聴課のほうで、こういう形で答弁を出されているので、その中身についてお聞きしているんですけれども、問題でしょうか。","respondent":"山田広報広聴課長","answer":"私どものほうは、それぞれ教育委員会と福祉事業部等所管のところからそれぞれ検討していただいて回答をいただき、合わせた形で区長の名前で要望書についてお答えをさせていただいているわけです。","voiceIndex":320,"id":"exchange-144"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこでは、「計画策定段階においてサービス利用者としての地域住民の意見を反映させるため、公聴会、懇談会または説明会の開催などを通じて、計画策定に係る情報を提供するとともに、住民の意見を幅広く聴取し反映させることが必要である」と、こういうふうにはっきりと国が示しているんですけれども、これとの関係でどういうふうに考えられるかお聞かせください。","respondent":"榎本行財政改革担当課長","answer":"住民参加と情報公開につきましては、先ほども審議会を設けて、その中で十分意見を取っていくという方向で考えておりますので、その審議会についてはどういう形態にするかこれからの検討ですけれども、既存の審議会を使うとか、新規に使うとかも含めて。","voiceIndex":322,"id":"exchange-145"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民参加で区民の意見をしっかりと聞いて、政策をつくる段階から聞いて行えというふうに、しっかりと国が出している指針ですので、私は改めて国がこういうふうに進めているものに沿って、計画策定段階から区民への情報提供、そして区民参加で行うように、学童保育の問題でも求めたいと思います。これは一般質問でも取り上げたんですが、区長にお聞きしたいと思います。","respondent":"高橋区長","answer":"大変、お待たせをいたしました。タウンミーティングの問題ですが、一応１２月１７日に実施する予定をしております。したがいまして、この問題につきましては広報等で公募をし、タウンミーティングをやっていきたいと、こういうふうに思っております。","voiceIndex":324,"id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１２月１７日にやっていただけるということで、本当に楽しみにしています。この中身は、具体的にはどのような中身でやろうとしているのか、そしてまた、これからもどういうふうな間隔でやろうとしているのか。区長自身が区民と直接対話ということでいいのか、そのことについてもよろしくお願いします。","respondent":"高橋区長","answer":"具体的な問題については、今現在検討しています。","voiceIndex":326,"id":"exchange-147"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは区長の公約ですので、区長自身がどういうふうに考えるかということによって決まってくると思うんです。区長自身がタウンミーティングについて、どういうイメージでどのようにこの４年間進めようとしているのか、このことについてお聞かせいただきたい。","respondent":"高橋区長","answer":"一応、何か将来に希望の持てるような名前でタウンミーティングができたらいいなという思いで、今計画をしているところです。タウンミーティング以外に何か考えているかというようなご質問ですが、おいおい考えていきたいと思っています。","voiceIndex":328,"id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"公約の中にはしっかりとそのことが書かれていて、「区民の皆様と同じ目線で考え、ともに行動する区政をモットーに」ということですので、ぜひ１２月１７日のタウンミーティング１回だけではなくて、具体的にあとどのようなイメージを持たれているのか、どのような考えを持たれているのかについて、もう一度お考えをお聞かせください。","respondent":"高橋区長","answer":"先ほども申し上げましたように、おいおい考えていきたいと思っています。","voiceIndex":330,"id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"おいおいということですけれども、私は公約にこれだけはっきりと掲げられているわけですから、もう公約をつくる段階でかなりのイメージは持たれて書かれているんじゃないかというふうに思っているわけですけれども、この区民との直接対話に対しては大変期待をしているところです。長野県の状況を聞いて、すごく感動をしたんですけれども、長野県の田中康夫知事は知事室をガラス張りにしたんです。","respondent":"高橋区長","answer":"品川区では、そのような経費をかけたくないと考えています。ガラス張りにしたから、よく見えるから区長の生活がわかる、そういうものではないと思います。区政というものは、品川区全体が行っているわけでございまして、区長一人が行っているわけではございません。","voiceIndex":332,"id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に徹底した情報、これは県民に知られて困る情報は何一つないと、こういう徹底した情報公開と、そして県民参加という中で、政治が大きく変わっていくということを象徴的にあらわしているんじゃないかなと思いますので、ぜひ区長にも１２月１７日のタウンミーティング以外にも、区民に開かれた区政をいろいろな施策で進めていっていただきたいと、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":334,"id":"exchange-151"},{"speaker":"藤田委員","kind":"質問","question":"私は決算に直接係わる問題を行わせていただきます。２点お伺いいたしますが、まず成果報告書の１０５ページ、庁舎等維持管理につきまして、もう１点は１０６ページの美化対策と、関連して１０７ページの公共サインについてお伺いをいたします。私がお聞きしたいのは、今年の夏は冷夏ということもありまして、屋上緑化をした効果は測定をされているのかどうか、その辺をまずお伺いをしたいということです。","respondent":"西島経理課長、志村地域活動課長","answer":"２点目の温度の問題ですけれども、昨年の６月から９月にかけまして、１８１会議室、屋上緑化のすぐ真下の部屋ですけれども、そこにデジタル温湿計を設置いたしまして温度を計測しています。これは１０月１日付で歩行喫煙等の条例の施行の１カ月前に、シルバー人材センターに撤去についてお願いをしたところです。現在、１５３カ所撤去したというふうに報告は聞いてあります。","voiceIndex":336,"id":"exchange-152"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは我々聞かなければ全然わからないことですね。ですから、これは区民に対してモデルケースでやっているわけですから、これは広報紙等で紹介をしてもらいたいと思います。わずか１カ月弱ぐらいで、そういう状態になっているんです。要するに、素材をどうするかというのを検討されたのでしょうか。これはずっとこれから永久的にこの地域を表示していくわけですから、その辺を教えていただきたいと思います。","respondent":"志村地域活動課長、西島経理課長","answer":"それと現在の路面表示のいろんな素材を検討してみましたところ、今回採用しましたものが、今のところ一番最新で、なおかつ一番耐久性に優れているというふうに考えました。実際は９月に入ってから張りました。ただ、庁舎の場合は工事を伴いますので、それについてもよく検討をさせていただきたいと考えています。","voiceIndex":339,"id":"exchange-153"},{"speaker":"藤田委員","kind":"質問・要望","question":"おそらく、そういうものを研究していただいて、ぜひ取付けをお願いしたいと思って、これは要望いたしておきます。ですから、同じ予算を投入するのであれば、そういうところまで、これは滑り止めはちゃんとついていますよ、もちろん横浜で足を滑ったとかそういうのはあまり聞いていませんけれども、そういうような形でこの際４カ所についてはやるべきだと思うんですが、いかがでしょうか。","respondent":"志村地域活動課長","answer":"私どもで、今回禁止区域を設定させていただきました。その表示につきまして、いろいろ検討してまいりました。今のところ一番有効だというのが、路面の表示だというふうに考えてございました。路面の表示ですけれども、ご案内のとおり、国道、都道、区道、いろんな形態があります。","voiceIndex":342,"id":"exchange-154"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"電算化ですけれども、つらつら挙げますと１０４ページに基幹事務管理システム整備費１億８,９００万円、１０９ページに行政評価システム経費２,４００万円、１１１ページに戸籍電算化開発経費１億５,２００万円、１１２ページに住民基本台帳ネットワークシステム開発経費２,５００万円。","respondent":"長田区民課長、田中情報システム課長、桑村人事課長","answer":"臨海広域斎場のオープンの日ですけれども、委員ご承知のとおりでございまして、城南５区で実施しているものです。既存のシステムについては大きく見直して、コストダウンをアウトソーシング等を含めて、手法を考えてコストダウンを図って。今回予定したものは、管理監督者向けにどういう研修ということで、一つは講演会という形を取りました。","voiceIndex":345,"id":"exchange-155"},{"speaker":"林（宏）委員","kind":"提案","question":"あれは２５０人ぐらいの方が参加されていましたから、それだけの大人数で研修というか、ああいうパターンになるんでしょう。先ほど、東京都と合同あるいは２３区合同とか、いろいろなケースを考えてやっている。それから電算化ですけれども、ここで４億５,０００万円、財調でほとんど……。防災ですけれども、今日いろんな方々それぞれのお考えで防災に取り組まれる、ご提案、ご意見がありました。","respondent":"市岡企画財政課長","answer":"これはまず診断ということが前提になりますので、個人住宅の耐震診断というものについて、具体的に検討をして始めたいというふうに考えてあります。","voiceIndex":349,"id":"exchange-156"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だから、改修を前提に、人の命を守るという、品川区の財産を守るという意味から、こういうことをぜひ検討していっていただきたい。おそらく品川区で全部これをやっていったら、１００、２００億円という数字が出てくるはずですから、そういうところも加味しながら、具体的に今おっしゃられた優先順位はいろいろあろうかと思いますけれども、進めていっていただきたいけれども、企画部長からお願いします。","respondent":"中尾根企画部長","answer":"その場合、先ほど言いましたように緊急性はどうなのか、マンションの問題もありますけれども、一番真剣に取り組まなければいけないのはどこか、地域もどこなのか、ないしは仕組みとしても区内企業とのタイアップが考えられるのか、考えられないのか。","voiceIndex":351,"id":"exchange-157"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1214#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":111331,"voices":353}},{"id":"h15-20031009-4","meetingId":"h15-c-settlement","date":"2003年10月9日","dateIso":"2003-10-09","committee":"決算特別委員会","time":"午前１０時０３分～午後６時１１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を159件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私の本日の質問事項を申し上げます。最初にお伺いをいたします。「社会奉仕の精神に基づき、高齢者世帯等の家庭を訪問し、話し相手となり、相談助言を行うとともに、関係機関および地域社会とのパイプ役として、高齢者の精神面でのサービスの充実を図る」と書いてありますが、この中の文言につきまして、１点お伺いをします。「関係機関」と書いてありますが、どちらの関係機関を指し示すのでしょうか。","respondent":"早津高齢福祉課長","answer":"高齢者相談員の任務といたしましての関係機関との調整です。高齢者相談員の場合は、関係機関と申しますと、まず区です。それから、在宅介護支援センター等の介護関係の社会福祉法人等ということになります。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"意見","question":"高齢者相談員とは民生委員がつかさどると書いておりますけれども、近年の少子高齢化によりまして、高齢化社会を迎えるに当たり、現状の民生委員、いわゆるここに書いてあります高齢者相談員の数では、多少少ないような感もありますが、民生委員を増やすという部分においては多少難があると思いまして、その補助的な役割として、ふれあいサポート計画の中で、何か補助要員を増やすようなお考えといいますか。","respondent":"早津高齢福祉課長","answer":"これを補佐する活動といたしまして、さらにふれあいサポート活動等で増員してみたらどうかという趣旨だと思いますが、まず介護の関係等でいきますと、高齢者相談員だけにお任せしているのではなく、先ほども申し上げましたように、関係機関であります在宅介護支援センター。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"非常にプライバシーに深く係わるということで、精神的に多重な負荷を負う役職です。例えば、保護司の場合は仲間同士の情報交換、また、心のケアの仕方、そして対象者の処遇に困った場合は東京保護観察所というところがありますが、民生委員イコール高齢者相談員、こちらのほうは保護司と同様に、どういうところに相談を持ちかけていってよろしいのか、お伺いをいたしたいと思います。","respondent":"日下部障害者福祉課長","answer":"ただ、いろいろ例えば高齢福祉の問題、それから生活保護に係わる問題、あるいは子育て、民生委員は児童委員の役割も担っております。だから、そういったことも含めまして、区内の関係各課が連携をしていろいろご相談に対応していると、そういう状況です。","voiceIndex":8,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"２点目、お伺いをいたします。高齢者実態調査についてですが、高齢者実態調査というのは、区の当該部署のどのような方たちが、どのような方法により、どのようなことを調査されているのか、まず最初にお伺いをしておきたいと思います。","respondent":"早津高齢福祉課長","answer":"これは３年に１回、これは民生委員の改選期を踏まえまして、新しい民生委員が選出されたときに、改めて自分の所管管内の高齢者の全件を実態調査していただくというもので、具体的にはコンピュータから打ち出した名簿をもとに、その名簿と照合しつつ、各世帯を訪れて。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"続きまして、高齢化ということで、品川区の３２万人余の人口のうち、６５歳が６万人、７０歳が４万人、７５歳以上が２.５万人、２万５,０００人いるということですが、高齢化社会と介護という問題を両建てと考えますと、例えば高齢者の方が高齢者の方を介護するという状況、先ほど７５歳以上の方が２万５,０００人いるという数字をかんがみますと、やはり高齢者の方が高齢者の方を見る。","respondent":"早津高齢福祉課長","answer":"現在、法整備等はまだということになっておりまして、その虐待に対する定義等も確立したものはございませんが、大体児童で言われているような身体的虐待、精神的虐待というような区分は当てはまるのではないかというふうに考えてあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"これは先ほど申し上げましたように、介護者が配偶者であったり、年老いた娘や息子であったりする場合がありますが、結論としまして、質問を端的にまとめますと、まず本区において、どのくらいの高齢者の虐待の実態を行政側として把握をされているのか、ちょっとお伺いをしたいと思います。","respondent":"早津高齢福祉課長","answer":"虐待の実態ですが、実は虐待に当たるかどうかの判定というのは、かなり難しい面があります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"大沢委員","kind":"意見","question":"十数件虐待というお話がございましたけれども、仮に虐待がわかった場合、子どもの場合は児童相談所なりに駆け込めばいい、また、養護施設等々ありますけれども、高齢者の場合は、どちらのほうに相談をしていったらよいのか、お答えをお願いいたします。","respondent":"早津高齢福祉課長","answer":"具体的には、高齢福祉課が基本的に中心となりまして、在宅介護支援センターの当該ケースを担当しているケアマネージャーあるいは保健師、それから場合によっては痴呆の専門医との連携、それから民生委員とも連携をとりつつ、初動期の早い対応を心がけ。","voiceIndex":16,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"第１の質問の最後ですが、この在宅介護者激励研修というのは、どのような事業が行われているのか、端的にお答え願います。","respondent":"早津高齢福祉課長","answer":"介護者への支援事業といたしましては、区で主催しております激励の集いという在宅介護を多年行っていた方に対する表彰と、それからそのねぎらいの会、それから各在宅サービスセンターでは、介護者に対する介護者教室等を行っているところです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"１点目の質問を終わらせていただきます。そのような考えに基づきまして１点と、またそれに派生した質問をお伺いします。この生活保護制度には、「もっぱら困窮状態」という文言がありますが、「もっぱら困窮状態」というのは、現在にかんがみますと、どのような困窮状態を指すのでしょうか、お答え願います。","respondent":"黒田生活福祉課長","answer":"生活保護制度ですが、戦後制定されまして、もう五十何年たったということですが、今回、今年度初めて基準が改定されました。ということで、一部基準改定は入ってあります。社会状況の中で変わっているということで、平成１６年度にかけて大幅な改正というのは予定されてあります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"最後の一番聞きたいことなんですけど、生活保護の支給を受けていながら、本来の趣旨と違って、例えばほんとうに困っているわけですから、私たちの税金が投入されているわけですから、ほんとうに困っての使い道、例えばお酒を飲んでしまったり、ギャンブルをやってしまったり、そういう方に対しての支給をちょっと何か本旨からして、私たちの血税からして範囲が違うと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"中島委員","kind":"質問","question":"私は成果報告書の１１４ページ、民生委員のところの質問と、それから１２４ページ、児童福祉施設費、ここに関連して質問します。初めに、この民生委員、今も高齢者相談員というのは民生委員の方が兼ねているということで、民生委員の方のお仕事というのは、どういうものがあるのか、初めにお伺いいたします。","respondent":"日下部障害者福祉課長","answer":"高齢者であるとか、障害者あるいは生活保護の世帯であるとか、そういった皆さん方の相談に応じまして、助言や援助を行うと、そういったことでは、民生委員は地域でお困りの方と区との一つのパイプ役ということで、幅広いご活動をいただいていると、そういうことです。","voiceIndex":24,"id":"exchange-011"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、民生委員の中に児童委員というんですか、主任児童委員、こうした仕事もあると認識していたんですが、これは別の管轄でしょうか。","respondent":"日下部障害者福祉課長","answer":"それからさらに、民生委員は通常はご自身で担当のエリアを持ちますけれども、主任の児童委員というのは、担当のエリアを持たないで、今１３地域に分かれておりますけれども、その各地域全体についての児童をめぐる問題、子育てをめぐる問題。","voiceIndex":26,"id":"exchange-012"},{"speaker":"中島委員","kind":"質問","question":"その主任児童委員の方なんですが、これは専門的に全域にわたってという今お話がございました。この主任児童委員になられる方も、新しく採用される方も何人かいらっしゃると思うんですが、今年度は今新しく採用されている方というのは何人ぐらいいらっしゃるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"たしか今年度に入りまして、１名の欠員を補充したということで、現在２４名の方が活動していらっしゃるという状況です。現在２４名の主任児童委員のうち、新しい方につきましては、たしか１０名ほど新しく主任児童委員にご就任をいただいております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"中島委員","kind":"質問","question":"先ほどお話がありましたように、専門的にやってくださる方ですので、この方たちに対しての主任児童委員というのは、こういう仕事をするんだというマニュアルとか、そういうものはご指導いただいていると思うんですが、１日研修だとか、例えばこういう施設が品川区にはあるんだとか、具体的なそういった指導というのはされているんでしょうか。","respondent":"辻田児童課長","answer":"主任児童委員の活動につきましては、児童課と大変深い関係がありますので、私のほうからご説明いたします。主任児童委員は当然選任された後に一定の研修をいたします。","voiceIndex":30,"id":"exchange-014"},{"speaker":"中島委員","kind":"意見","question":"私の知り合いも主任児童委員として今一生懸命地域に貢献しようとして頑張っている方も何人かいらっしゃいます。非常に不愉快な思いをしたらしいんです。そうした問題を委員会の席上で話をされたそうです。私は、こういうことは絶対にあってはいけないんじゃないかなと思うんですが、こうした問題に対して、どのようにお考えになっていらっしゃるかお答えいただきます。","respondent":"辻田児童課長","answer":"そういうことで、たしか昨年からそういう形になったと思いますけど、いわゆる今までの地区割の中で、主任児童委員の方ときちっと連携をとっていく、その部分が今回ブロック制になったことで、ちょっと再構築する必要があるかなというぐあいに感じております。","voiceIndex":32,"id":"exchange-015"},{"speaker":"中島委員","kind":"質問・要望","question":"ですから、お互いにやはり、そこら辺のところというのは、ある一線を引きながらしっかりキープしていただきたいと要望しておきたいと思います。そこで、引き継ぎの問題なんですが、これはどのように、大事な子どもたちがいるわけですから、その子どもたちのいろんな状態をどのように引き継いでいらっしゃるのか、その点をお伺いいたします。","respondent":"金子保育課長","answer":"保育園におけるさまざまな子どもに関する、あるいはそれ以外の伝達事項のことについてのお尋ねだと思いますが、私どもこの辺につきましては、従来から口頭中心にしてきたというふうな現実は把握しておりまして、さまざまなところでいろいろなご説明をしておりますけれども。","voiceIndex":34,"id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"特に非常勤の方というのは４時間の仕事の中でフル回転の場合もある。こうした中で、文書の引き継ぎというのはどのようにされるおつもりか伺います。","respondent":"金子保育課長","answer":"私どもの基本的な考え方として、非常勤の方の把握した実情等々についても伝達しなければなりませんけれども、非常勤職員の方同士が口頭でそういったやりとりをするということは、基本的には指示しておりません。","voiceIndex":36,"id":"exchange-017"},{"speaker":"中島委員","kind":"質問","question":"これで、保育士さんによって、やっぱりいろんな保育の仕方も違ってくる、そうすると、非常勤の方は保育士さんが変わるたび、その人の顔色をうかがいながらその仕事に当たっているという現場もあるわけなんですが、こうした一貫した指導性、一貫した指示系統とか、そうしたものはないんでしょうか。","respondent":"金子保育課長","answer":"だれに聞いたらいいかわからないというようなことがもしありましたら、それについては早急に改善しなければならないと考えていますので。","voiceIndex":38,"id":"exchange-018"},{"speaker":"中島委員","kind":"質問・要望","question":"これは園を運営している人のあり方によっても随分違うのかと思いますが、ぜひこれは行政のほうからしっかりとこの辺のところは指示をしていただきたいと要望しておきたいと思います。それと、夕方から入る子どもさんもいると思うんです、延長保育で。この辺のところは親御さんに夕食は食べさせないで来てくださいとか、そういった指示はされていないんでしょうか。","respondent":"金子保育課長","answer":"もちろん食事の時間、要するに夕食あるいは補食を提供しておりますけれども、こういったものについては時間を決めて皆さんで食べていただくというふうに提供しておりますが、あくまでも個々の事情によりましては。","voiceIndex":40,"id":"exchange-019"},{"speaker":"中島委員","kind":"質問・要望","question":"小さなことかもしれませんが、こうした食事一つの問題、子どもの精神をゆがめる場合もあります。そういった点で、きめ細かな配慮を要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"おはようあります。私からは、成果報告書の１１５ページになりますけれども、特別養護老人ホームについてお伺いをしていきたいというふうに思います。特別養護老人ホーム、この待機者あるいは建設に係わる問題ですけれども、一般質問で鈴木ひろ子議員が質問しておりますので、短い時間ですので、このご答弁などの中から疑問点についてお聞かせを願いたいと思います。","respondent":"早津高齢福祉課長","answer":"特別養護老人ホームの入所調整会議につきましては、第８回を９月に行いまして、７２１名の方が希望されたです。","voiceIndex":44,"id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"そうしますと、約７割弱の方が何らかの施設で生活をされているという皆さんが申し込みをされているという状況だと思いますけれども、理由はいろいろあるんだと思いますけれども、在宅での生活というのは、いずれにしても困難だという方々が特別養護老人ホームに入所を希望されたんだというふうに思いますけれども、そうしますと、区の施設サービス、それから在宅サービスの拡充でもって。","respondent":"早津高齢福祉課長","answer":"在宅サービスの何をですけれども、在宅サービスはさまざまなサービスを組み合わせて、その方その方の身体状況あるいは痴呆状況等に応じたサービスを提供するのが必要なことでございまして、あるサービスを増やせばいいのではないかというような単純なことにはならないと思います。","voiceIndex":46,"id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"あるサービスを増やせばいいという単純なことにはならないんだということですけれども、私、今８回目の人数を聞きましたけれども、１回目から７回目まで見ましても、大体この比率というんですか、在宅の方と施設に入所をされている、こういう方の比率はずっと大体同じぐらいの比率で推移をしてきているんですよね。実際に人数そのもの、率はそう変わっていないわけですから。","respondent":"早津高齢福祉課長","answer":"そういう方が在宅の中で住みなれた地域で暮らしたいというのは基本的な欲求ですので、それがさらに満たされるようにしていきたい、このように考えてあります。","voiceIndex":48,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと時間がないので、鈴木ひろ子議員が一般質問の中で都南病院、この跡地について触れていますけれども、ここは移転計画を発表した際に、随分昔ですので、私も直接聞いたわけではありませんけれども、老人保健施設をつくる、あるいは診療所をつくる、こういう計画があって、これが白紙撤回をされているんですけれども、いずれにしてももともと病院だったところですので。","respondent":"新美保健高齢事業部長","answer":"都南病院の跡地の件のご質問ですけれども、都南病院については、ご案内のとおり現在社会保険庁のほうが所有ということで管理をしておりまして、私どもは今その推移というのを見守っている段階ですので、現時点ではそういう段階だというふうに考えております。","voiceIndex":50,"id":"exchange-024"},{"speaker":"高星委員","kind":"質問・要望","question":"いわゆる債務負担行為でやったほうがいいのか、一時払いの助成金を出したほうがいいのか、これは債務負担行為にしますと、今後にいろいろと影響するものですから、そのところの基本的な考え方を教えていただきたいということと、それとあわせまして、大崎の百反通りにありますけれども、そこのところに何か新しい民間の老人施設がつくられるというふうに聞いているんですけれども、こういったところ。","respondent":"早津高齢福祉課長、日下部障害者福祉課長","answer":"２０床ぐらいということで、有料老人ホームを民間で建設です。区としては特段の補助等については考えてございません。窓口としましては、東京都の福祉局がさまざまな問題について対応するですけれども、ただ身近なところで申請等について受け付けをできるようにということで、私ども障害者福祉課のほうで申請がございましたら。","voiceIndex":53,"id":"exchange-025"},{"speaker":"高星委員","kind":"質問・要望","question":"これは東京都の福祉局扱いだということで、行政の流れとしてはわかるような気がするんだけれども、そこに行って、いろいろご苦労されてきたのは事実であって、それが何で障害者の窓口になってしまうのかという、ここのところの基本的な考え方をちょっとお聞かせいただきたいというふうに思います。","respondent":"日下部障害者福祉課長","answer":"これはどういうことかといいますと、かつては厚生部の厚生課とか管理課ということで、福祉全般にわたっての事務についていろいろ対応していたと、そういった経緯があります。","voiceIndex":56,"id":"exchange-026"},{"speaker":"高星委員","kind":"質問・要望","question":"関係部署の方々もいろいろ苦労されている、大先輩の処遇のことですから、苦労されているんだというふうに。どこにあるんでしょうかという話じゃなくて、あるのはあるんですよ。それはわかります。そういうふうにやっぱりきちんと尊敬の念を持って対応していただきたい、これは私から要望したいというふうに思います。この方は、まじめに働いてきたものですから、１１万円ぐらいの年金はもらっているんですね。","respondent":"黒田生活福祉課長","answer":"先ほどもご答弁したんですが、「もっぱら困窮」というところで、生活保護基準は年齢、あと世帯構成ということで、その基準に基づいて、収入があるなら、その方が超えているか超えていないかで生活保護の対象になるかならないかですが、この法律の趣旨は、その過去がどうあれ。","voiceIndex":58,"id":"exchange-027"},{"speaker":"高星委員","kind":"質問","question":"そのとおりだと思う。現在、日本国憲法にのっとってきちんと最低の文化的生活は保障しなければならないことになっているわけで、それはよくわかる。ただ、それでいいんですかという何か複雑な気持ちを訴えたいなというふうに思います。","respondent":"黒田生活福祉課長","answer":"年金にしましても、着実に積み上げてきた方、保護の基準に欠けるところを要保護ということでプラスしますので、何も年金をかけていない方と同じ額というのは矛盾があるということは私どももやっている中では感じてあります。","voiceIndex":60,"id":"exchange-028"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、成果報告書の１２５ページ、児童センターの運営に関連をしまして、事業の展開について少しお伺いをさせていただきたいと思います。その辺のところで、現状考えられていること、そしてまた、そこには中高生のアンケートをとられたんじゃないかなと思うんですが、その辺のことをお知らせいただきたいと思います。","respondent":"辻田児童課長","answer":"そういう中で、他区では、ある大きな児童館をつくって、その中で中高生の対応をしていこうということはありますけれども、私どものほうとしまして、それはそれとしてあるわけですけど、もう少し全区的な形で中高生が参加しやすいような状況をつくり出していくために。","voiceIndex":63,"id":"exchange-029"},{"speaker":"原委員","kind":"意見","question":"今後の方向づけとして、今たまたま平塚とか東大井という話が出ているんですけども、今後の方向づけとして、今言われたような事業を展開していくための施設あるいは設備の予定はどの辺までやられているのかということと、それから対象事業をどこまで、例えば今お話のようにスポーツがどのぐらいできて、音楽活動がどうなのか。","respondent":"辻田児童課長","answer":"東大井につきましても、現在その作業を進めているところですけど、これも基本的にはまず一つはスポーツ活動の充実、それからもう一つは、地域的と申しますか、ものづくり活動の創出というような形で、地域特色を持たせながら、ものづくりをテーマとして事業展開させ。","voiceIndex":65,"id":"exchange-030"},{"speaker":"原委員","kind":"意見","question":"地域の人材も含めて、どうそこに参画をさせていくか、これは非常に大きな課題だろうと思う。それともう一つは、現在の児童センターがそのようなイメージチェンジを図っていくということは、地域にやはり知らしめなければならない部分があると思うんですが、その辺のところはどういうふうな考え方を持っていこうとされているのか。","respondent":"辻田児童課長","answer":"いわゆる相談機能などを充実しまして、地域の方々、例えば主任児童委員、民生委員の方々、そういう方々との連携の中で、地域の子育て支援をしていくというような形の交流の中で、地域の方々との連携というのを強化していきたいというぐあいに考えております。","voiceIndex":67,"id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"それで、今お話しされたようなことは、おそらく平塚あるいは東大井、既にスタートされていて、いろいろ反省しながらやられているんだろうと思うんですけれども、一番大切なのは、そこにいらっしゃる職員の意識改革が大きな課題になるというふうに思っているんですけれども、今までの形ですと、例えば小学生なり、あるいは小さいお子さんなりがそこでの居場所を見つけてくるわけですけれども、今後の場合。","respondent":"辻田児童課長","answer":"これは今後私どもの研修等、いわゆる話を聞くカウンセリング、そういうようなものを基本にしながら個々に対応できる能力を十分つけていきたいというぐあいに考えております。","voiceIndex":69,"id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"そこで、今後児童センターを、今２館がこのようなスタートをしておりますけれども、どのような形で、例えば年間何館ずつやっていくとか、そういう予定があったら教えてほしいのと、それから事業内容も、その地域の特性をもっと生かして、みんな同じような事業を同じようにやっていくのでは特色が出てこないと思うので、そこにやはり特色を持たせることが大切だと思うんですが。","respondent":"辻田児童課長","answer":"当然地域の特性を考えて、音楽活動であるとか、それからスポーツ活動、それから先ほど申しましたようなものづくりの活動、それから、いわゆるボランティア、高齢者との交流の中でのボランティア活動であるとか、いわゆる地域地域の特性を生かした形の事業実施。","voiceIndex":71,"id":"exchange-033"},{"speaker":"原委員","kind":"質問・要望","question":"いずれにしましても、若い方々のその地域におけるコミュニティの核になるような事業展開を今後の中でぜひしていっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"私は１２２ページの認証保育所運営助成と施設整備助成についてと、それと１２４ページのＩＳＯ９００１運営費についてお伺いします。多分収入超過額の１９４万７,０００円が何か関係しているのかなと思うんですが、この辺はいかがでしょうか。","respondent":"金子保育課長","answer":"最終的に翌年度で精算するというのが収入超過額の分なんですけれども、これを翌年度で精算して、結果的には２分の１ずつ負担すると、こういうふうな仕組みになってあります。","voiceIndex":75,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、たしかこの間の定例会の中で、鈴木真澄議員からご質問あったときに、部長の答弁において、認証保育所が５園予定されておりますというご答弁があったと思うんですけれども、この５園を具体的にどのような方法でやっていくのかということを教えていただきたいのと、それとこの認証保育所ができた目的というのは、いわゆる認可の保育園が対応しきれない。","respondent":"金子保育課長","answer":"２点のご質問だと思いますが、まず１点目、今後の認証保育所の予定かと思いますが、まずＡ型の部分につきましては、東品川のシーサイド地区、それから大崎駅の東口の第三地区でこれから開発が始まりますけれども、そこがあわせて２件。","voiceIndex":77,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"ＩＳＯの９００１の運営費についてお伺いしますが、まずちょっと単純な疑問なんですけれども、数字の比較だけなので、衛生費の１３２ページの中に環境ＩＳＯの運用の経費が１７３万５,６２６円になっております。ほんとうに単純な疑問なんですけれども、環境ＩＳＯというのは、全官庁的に行う施策だと思うんですけれども、この保育のＩＳＯは保育園のみなのに、なぜ高いのか教えてください。","respondent":"金子保育課長","answer":"これの経費が１２０万円余ほどありますので、その分で私どものほうがかなり多額になっているです。","voiceIndex":79,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、マニュアル本というふうにご答弁の中で出ましたが、そのマニュアル本の印刷は何冊ぐらい印刷して、何冊ぐらい売れたんでしょうか。印刷経費等もわかったら教えていただきたい。単価も含めて、どのような方が買っていったのか、わかれば教えてください。","respondent":"金子保育課長","answer":"印刷経費ですけれども、先ほど総額を申し上げましたが、単価としては１,４３０円です。売値のほうは、２,８００円で販売しておりました。","voiceIndex":81,"id":"exchange-038"},{"speaker":"藤原委員","kind":"意見","question":"この不景気の中、２,８００円という価格で、ほんとうによく、完売したと思うんですが、課長のお考えで、何で、どうしてこれだけ売れたと考えていますか。","respondent":"金子保育課長","answer":"そういう意味では、今まで培ってきました各館の保育サービスの充実、こういったものの、言ってみれば、ブランド力というものが全国的にも注目されて非常に購入が多いというふうに考えております。","voiceIndex":83,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"１２５ページの学童保育クラブ運営費についてお伺いをします。","respondent":"辻田児童課長","answer":"これが時代の流れの中で大きく、子どもたちの健全育成という形で事業が変化してきた、それなりの時代の変化に応じて適切な学童保育事業を実施してきたというぐあいに考えております。","voiceIndex":87,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"提案","question":"児童センターのあり方にも大きく影響を与える提案、今問題になっています。父母の皆さんからきめ細やかな配慮が求められています。それから、２点目は、多くが低学年でまだまだ保護育成が必要とする子どもたちです。すまいるスクールを利用する子どもと、このように学童保育クラブを利用する子どもたちでは、要求に違いがあると思っていますが、この点についての認識も明快にお答えをいただきたいと思います。","respondent":"辻田児童課長","answer":"むしろ、特に現在は在宅でお子様を育てている家庭の子どもに対して、どうやって育てていったらいいのかわからないという自信のなさが数字的にもあらわれているというような状況の中では、子どもたちを分け隔てなく、そして就労家庭につきましては。","voiceIndex":89,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面では、この間、委員会の中でも何度も聞いておりますが、保護者の就労に対する保障、あと、生活の場としての位置づけ、この違いはすまいるスクールを利用されているお子さんと、学童保育クラブのお子さんとは明らかに違うと思うんですが、私はこのところの認識がとても欠けている、この認識を児童課が、教育委員会にしっかりとお伝えをいただけなければ、働くお父さん。","respondent":"辻田児童課長","answer":"いわゆる放課後児童健全育成事業が就労支援につながっていくということは、私どものほうも何度も申しております。ただ、この事業の第一の目的は、児童の健全育成をすることで、親御さんに安心していただいて仕事をしていただく、こういう事業です。","voiceIndex":91,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"働くお母さんたちが、学童保育クラブに何を求めてきたのかというと、毎日安心をして帰れる、そういった生活の場であってほしい、そのためには、健康、そして安全の配慮はもとよりも、一人一人の子どもに安心が持てる人間関係、お友達の関係もそうですけれども、指導員との関係を求めているわけです。私は専任の指導員の複数配置、これが不可欠と考えますが、いかがでしょうか。","respondent":"辻田児童課長","answer":"非常勤といっても、５日勤務の非常勤をつけているということで、私どものほうとしては、十分な体制になっているというぐあいに考えております。","voiceIndex":93,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"親もまた、先生に相談をしたり、親子ともにフォローしてくださいます。もう一点、進め方の問題なんですけれども、この間１万１,０００人を超える請願署名、その中身には、親の意見を聞いてほしい、納得のいく説明をしてほしい、こういった意見が大変多かったわけですけれども、今紹介した世田谷区の新ＢＯＰの移行に当たっても、保護者との情報交換というのがとてもしっかりとやられています。","respondent":"辻田児童課長","answer":"それからもう一点、保護者の方々ですけど、私どものほうは６月３０日、それから８月２６日に報告……。","voiceIndex":95,"id":"exchange-044"},{"speaker":"大西委員","kind":"質問","question":"今日は１１６ページ、高齢福祉費、ならびにちょっと時間がございましたら、１２６ページの生活保護扶助費についてお伺いいたします。","respondent":"早津高齢福祉課長","answer":"要介護認定で３、４、５の方です。","voiceIndex":99,"id":"exchange-045"},{"speaker":"大西委員","kind":"質問","question":"「痛い、痛い」と言ったら、「大げさにするな」ということが言われていて、告発すべきかどうかということが新聞紙上にも出ていたわけですけど、先ほどの大沢委員の話の中では、お答えとして在宅における虐待だったのかなと思うのが十数件ということでしたが、そういう施設における虐待というのがどういうぐあいでこういうところに相談、区のほうに来ているのかどうか。","respondent":"早津高齢福祉課長","answer":"ただ、私どものところに、例えば区内の特別養護老人ホームでの虐待とかというようなことは、私どもの耳には入ってございません。たまたま介護事故というような形で起こる場合というのはあるわけですけれども、虐待というような形で報告は聞いてございません。","voiceIndex":101,"id":"exchange-046"},{"speaker":"大西委員","kind":"質問","question":"今事故という話がありましたが、そういう場合は当然施設のほうからそういう事故があったという報告が上がると思うんですが、それが果たして事故なのか、事故がたまたま起こったのか、それともそれが虐待の原因で起こったのかという面についてのそういう調査とか、そういった方面はどのようになっているんでしょうか。","respondent":"早津高齢福祉課長","answer":"その報告書の中には、どういう状況の中で起こったのかというようなこともるる記載されておりまして、あわせて今後の未然防止のための対応策というようなことも書かれてあります。","voiceIndex":103,"id":"exchange-047"},{"speaker":"大西委員","kind":"質問","question":"今お聞きすると、管理者側からの報告ということで感じるわけですが、こういう場合は実際におけがをされた方に一応どういう形で起こったのかというのを聞いてみないと、一方側のものだけではちょっと私は正確なものには成り得ないんじゃないかと思うんですけど、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"そういう面もあろうかと思いますが、施設におきましては、もう一つのシステムといたしまして、苦情処理委員というものを必ず設置するようにしています。","voiceIndex":105,"id":"exchange-048"},{"speaker":"大西委員","kind":"質問・要望","question":"その委員会がどういうふうになっているか、今ちょっとよく承知できなかったんですが、私とすれば、自分がもしそういう身の上になって虐待を受けていたらと考えると、非常に背筋が寒い思いをするので、新聞に載っていたのがたまたまのケースではないんじゃないかなという想像もしておりますので、ぜひ入所されている側の立場に立った調査というのもぜひ行っていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"その介護者側についてどういうふうにするかということですが、在宅の介護のためのケアプランをつくるときに、支援センターのケアマネージャーたちは、その人、ご本人、要介護者だけではなくて、家族のほうについてもどういった状況であり、介護疲れが非常に見られる場合には。","voiceIndex":107,"id":"exchange-049"},{"speaker":"大西委員","kind":"質問・要望","question":"時間がございませんので、私はこの老老介護というのは、非常に危険性を伴うものだと思います。それについて、品川区のほうでそれを把握していないというのは、私はちょっと問題があるんじゃないかなと。老老介護ゆえに片方の側が非常に介護される側に回りやすいということをご配慮いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"私のほうから成果報告書の１１９ページの聴覚障害者相談と、１２６ページの扶助費の法外援護の２点についてお伺いしたいと思います。初めに、聴覚障害者相談についてですけども、まず決算金額の２４８万４,８００円についての具体的な内容と、また窓口相談１００回、出張相談４５７回についての大体の内容についてお伺いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"窓口の配置につきましては、これは区役所、私どもの障害者福祉課の窓口に毎週２回水曜日の午後、それから金曜日の午前ということで、手話通訳者を配置しまして、聴覚障害者の相談に応じているという状況です。","voiceIndex":111,"id":"exchange-051"},{"speaker":"武内委員","kind":"質問","question":"今出張相談についての大体の内容をお聞かせいただいたんですけども、区内の聴覚障害者の方のこの相談の対象にされている人数と、あと手話通訳の派遣ということで、その手話通訳者の区内で登録されている人数のほうを教えてください。","respondent":"日下部障害者福祉課長","answer":"手話通訳者の方の人数ですけれども、これは区のほうへ登録をいただくことになっております。これについては、現在約２０人の方に登録をいただいております。","voiceIndex":113,"id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"約６５０人の手帳をお持ちの方ということで、それに対して通訳の方が２０人ぐらいということですけども、実際に手話ができない方も６５０人の中で何人かいらっしゃるということですが、現状、この相談でこの２０人の手話の方で、現状足りているという言い方はおかしいんですけど、賄っていかれておるんでしょうかということをお聞かせいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"その方たちである程度対応ができているという状況です。ですから、過去の事例を見ましても、あまりお断りするような、そういうケースはほとんどございません。","voiceIndex":115,"id":"exchange-053"},{"speaker":"武内委員","kind":"質問・要望","question":"今６５０人というのは聴覚障害者という位置づけの方だと思うんですが、実際には軽度の難聴の方も含めると、大体全国で約５％、６００万人ぐらいの方が難聴という形で言われておるんですが、品川区は３２万人ですので、単純にいくかどうかわからないですが、そうしますと、大体１万５,０００人ぐらいの方がいらっしゃるんじゃないかなというふうに思うんですけど、実際に難聴の方の人数の把握と。","respondent":"日下部障害者福祉課長","answer":"ただ、手話ができない方につきましては、残念ながら今は大体筆談が中心でやりとりがされているという状況でありまして、私ども窓口へおいでいただいても、やはり筆談中心で対応させていただいていると、そういう状況です。","voiceIndex":117,"id":"exchange-054"},{"speaker":"武内委員","kind":"意見","question":"そうしますと、難聴の方に対してもある程度相談があるという告知はされておるかと思うんですが、対応のほうがなかなか難しい部分もあると思うんですけど、今後また取り組みをお願いしたいと同時に、この件で最後になりますけど、今事業運営上の課題がもしございましたらお聞かせください。","respondent":"日下部障害者福祉課長","answer":"おそらくこれからいろいろ手話通訳を必要とされる需要も増えてくると思いますけれども、それに対応するためには、手話通訳者の方の人数をやっぱり増やさなくちゃいけません。","voiceIndex":119,"id":"exchange-055"},{"speaker":"武内委員","kind":"質問・要望","question":"いろいろご苦労もあるかと思いますけど、今後とも取り組みのほうをさらに、決算金額の割には非常にいい大事なサービスだと思いますので、よろしくお願いしたいと思います。２点目の生活保護の扶養費の中の法外援護ということについてお伺いしたいと思いますが、この法外という意味ですね、多分生活保護の保護法の外という意味だと思うんですが、その見解を教えていただきたいと思います。","respondent":"黒田生活福祉課長","answer":"法外援護ですが、生活保護は本来法内の基準、先ほどから出ています保護費の中で生活していただくということが原則です。法外援護といいますのは、プラスのものということで、ほとんど区が負担、上乗せの部分を区が負担するです。","voiceIndex":121,"id":"exchange-056"},{"speaker":"武内委員","kind":"質問","question":"そうすると、区独自の取り組みの部分というか、区独自の対応の部分ということかと思いますけども、いただいた事務事業評価の中で、この部分がＣの評価になっておりまして、見直しをこれからされるというような感じになっているんですけど、今後区のほうでどのような見直しをされるかお伺いしたいと思います。","respondent":"黒田生活福祉課長","answer":"先ほどからご質問ありますが、法内の本来の生活保護の基準がやはり今ボーダーの方と上回っているんじゃないかということで、ある意味では、最後のとりでというところが何か虹色に見えているというような方が多うありますので、そういう意味では、先ほどご答弁しましたように。","voiceIndex":123,"id":"exchange-057"},{"speaker":"武内委員","kind":"質問","question":"先ほどから、午前中もありまして、私も法内のほうについては各委員おっしゃるとおりの、わかる部分が非常にありますし、そのとおりじゃないかなという部分もありますし、また国のほうでもいろいろそういった年金との比較とか、最低年金をいただく方との受給額の問題とか、さまざま取り上げられておりまして。","respondent":"黒田生活福祉課長","answer":"入浴券も含めまして、見舞金等、これから国の動向も含めて、品川区の地域性を含めて検討させていただきたいと思います。","voiceIndex":125,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"私は成果報告書１１５ページ、民生費の中の国民健康保険会計繰出金の部分と、国民健康保険全般ということで１７５ページ以降の国民健康保険事業会計のことについてお伺いをいたします。そんな中で、国民健康保険の健全財政をより維持していく上での区の中でさまざまな施策がありますが、そういったものとも連携をしながら、財政的にも健全財政を運営していくというのが基本だろうと考えています。","respondent":"市岡企画財政課長","answer":"区民生活事業部は組織的に言えば、区民生活の具体的なサービスを所管する総合的な事業部として位置づけられておりますので、組織上の分掌事務は区民生活事業部と、こういうことになってあります。","voiceIndex":128,"id":"exchange-059"},{"speaker":"田中委員","kind":"質問・要望","question":"そのような状況の中でご答弁いただいたことを念頭に置きながら、先ほども申し上げた他の施策等もより連携を持ってという部分でちょっとお伺いをしたいと思います。その入りの部分をいかに増やすかということで、収納率の問題になってまいりますが、先日も住宅課長から区民住宅の滞納者に対する対応ということで非常に夜討ち朝駆け等も含めて尽力されて、滞納者を減らしているというご努力を伺いました。","respondent":"太田保険年金課長","answer":"ちなみに、平成１２年度から申し上げますと３６７件、１３年度２６７件、１４年度１８８件、ちょっと件数が落ちてありますが、こういう意味で実施をしてございまして、その分での収入も６,８００万円、６,１００万円、４,８００万円という部分での徴収も努力をしています。","voiceIndex":130,"id":"exchange-060"},{"speaker":"田中委員","kind":"質問・要望","question":"出を減らすということで、事務事業の中に、国民健康保険事業の医療費の通知のところに、健康への認識を深め、医療費の抑制につながるように通知内容を工夫し、継続的に実施していくと、これが評価Ｂとされておりますが、このような観点で健康増進に向けて、所管は民生費ではなく、衛生費の中の保健高齢事業部での事業だと思いますが、区民生活事業部内の国民健康保険の担当課として。","respondent":"太田保険年金課長","answer":"なお、ＰＲ活動、啓発事業も必要だということで、今年の７月の国保だよりにおきましては、区民検診のご案内あるいは成人病についてのコラム的なものも今年は試みとして入れて、意識を持っていただこうということで考えて実施をしています。","voiceIndex":132,"id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"既に３年も経過し、また委員会では通過しましたが、保険料の徴収のあり方も１２カ月から１０カ月に変わる、そういった面で少しずつでありますが、区の独自性がそういった面にも発揮されておりますが、保険料の設定、また特に会計は区の単独会計ですので、その会計の中も見ながらも、よりそういう方向にぜひ持っていくべきだろうと考えていますが、その辺の考え方をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"そうなりますと、基本的な物の考え方としては、各区が横並びをやめて、責任を持って自分の保険運営をしていくという点では、自主的に保険料も財源不足の補てんも決めていくと、これが本来のあり方になるかと考えています。","voiceIndex":134,"id":"exchange-062"},{"speaker":"三村委員","kind":"質問","question":"昨日も少しお聞きしたかと思うんですけれども、次世代育成支援に関して詳しくお聞きしたいと思うんですけれども、品川区の今後の行動計画の策定スケジュール、また、全庁的な取り組みになるかと思いますけれども、どのような部署が係わって、どのような取りまとめを行っていくか、決まっている範囲で構わないので教えていただければと思います。","respondent":"榎本行財政改革担当課長","answer":"必要があれば、新しい施策の部分でニーズ調査を行い、その後行動計画の原案という形になっていくんですけれども、その場合にもかなり幅広い所管が実際行動計画の指針の中でもいろんな事業が幅広く含まれておりますので。","voiceIndex":137,"id":"exchange-063"},{"speaker":"三村委員","kind":"質問","question":"それに関連してなんですけれども、今回の行動計画では、毎年把握、点検、公表というスケジュールが実施されていくかと思うんですけれども、今まで品川区で実施されていた子ども関係の施策、またこれから新たに取り組まれる施策について、こういう名称でいいのかわからないんですけれども、一本化された形で子ども総合計画プランみたいなものを策定する計画はあるのかどうか、お聞きしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"五つの都市像と七つのプランという形で第三次長期基本計画を組み立てておりますけれども、特に重点プランとして、子育ての部分のプランを立てて着実に実施を図っているところです。","voiceIndex":139,"id":"exchange-064"},{"speaker":"三村委員","kind":"質問","question":"それに引き続き関連してなんですけれども、今回この次世代育成に関しての前段階の研究だと思うんですけれども、次世代育成支援に向けた地方公共団体における行動計画のあり方についてというものが発表されておりますけれども、その中に、ニーズ調査においては、市町村職員自身による調査の実施、また実際当事者参加で策定プロセスについて検討、または子育てマップ。","respondent":"榎本行財政改革担当課長","answer":"次世代育成の行動計画については、これから細かいところは詰めていくところなんですけれども、その中で、どういう形の区民参加、情報公開等のあり方についてもあわせて検討していく予定としておりますので、細かいところはこれから議論を庁内で進めていきたいと考えています。","voiceIndex":141,"id":"exchange-065"},{"speaker":"三村委員","kind":"質問・要望","question":"ですから、子育てマップも必要な情報が入っていなければ、つくっただけでは意味がないと思いますので、ぜひ当事者参加でやっていただきたいと思います。次に、一時保育事業と、しながわ出会いの湯事業なんですけれども、品川区における一時保育事業、どういった施策がなされているかお聞かせ願います。","respondent":"金子保育課長","answer":"一つは、各保育園において、最高１園２名という形で、事由としては、保育に欠ける要件として、保護者の死亡であるとか、入院された場合、あるいは出産であるとか、そういったことが理由としてお預かりするというのが一つです。","voiceIndex":143,"id":"exchange-066"},{"speaker":"三村委員","kind":"意見","question":"品川区の一時保育事業、緊急避難的な一時保育というのはとても充実していて、私自身とても心強いところがあるんですけれども、保育に欠けていない、理由を問わない一時保育というのが私たち生活者ネットワークで調査したときも、ニーズはとても大きいものがあったんですけれども、そういった一時保育に対する今後の取り組み、もしお考え等あれば、お聞かせ願いたいと思います。","respondent":"金子保育課長","answer":"今、委員ご指摘の、いわば保育に欠けない状態での、例えばリフレッシュであるとか、あるいはカルチャーセンターであるとか、そういったところに保護者が行かれる場合の保育というふうなことですけれども、私どもこの辺につきましては、将来の課題というふうに思っておりまして。","voiceIndex":145,"id":"exchange-067"},{"speaker":"三村委員","kind":"提案","question":"今、人件費ですとか、コストの問題が挙げられていたかと思うんですけれども、提案という形でなので実施できる、できないというのはあるかと思うんですけれども、品川区においては出会いの湯事業ということを高齢者福祉のほうでやられているんですけれども、子育て世代も実は私も去年１年間０歳児を抱えて生活していたときに、ゆっくりおふろに入る暇もなかった、１人でいる時間。","respondent":"辻田児童課長","answer":"それともう一点、非常に大切なことですけど、４月１日に子どもたちがスムーズにすまいるスクールに行けるように各学童保育クラブと、それからすまいるスクール、そこが連携して子どもたちの交流を図る中で、お子さんが４月からはすまいるスクールのほうに通えるよう。","voiceIndex":147,"id":"exchange-068"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ密接な連携体制を持って、保護者の方に不安を与えないような移行の形をぜひとっていただきたいと思います。今回、移行に関して、私たちのところにもいろいろこういう場合はどうなるんでしょうかとか、今回移行に当たって保護者の方からの不安が数多く寄せられております。もう説明会等も教育委員会のほうでも児童課のほうでもされたと思います。","respondent":"辻田児童課長","answer":"このたび、厚生委員会におきましても、それから本会議におきましても、先ほども質問に対してお答え申しましたように、教育委員会との説明会はきちっとこれからやっていくです。","voiceIndex":149,"id":"exchange-069"},{"speaker":"三村委員","kind":"意見","question":"なかなか情報が詳しい情報がわからない、不確定の情報で振り回されて、かなり心配を募らせている保護者の方が多いかと思いますので、ぜひ正確な情報を、そして早く、一日も早い情報提供をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-070"},{"speaker":"山村委員","kind":"質問","question":"私のほうからは、成果報告書１２５ページ、児童センター運営費と、あと時間がありましたら１２３ページ、入院助産費についてご質問します。意見を吸い上げる方法で、アンケートをとられているというふうにお答えなさったと思うんですが、そのアンケートはどの程度の人数からとられたのか、また、どのような基準で回答してもらう児童、中高生を選ばれたのか、回答率とともに教えていただければと思います。","respondent":"辻田児童課長","answer":"この中高生のアンケートの実施につきましては、まず児童センター６館で行いました。","voiceIndex":153,"id":"exchange-071"},{"speaker":"山村委員","kind":"意見","question":"アンケートのほうですが、児童センターに来ている方からアンケートをとられているということなんですが、このアンケートは来ている人間からとるよりも、来ていない人間からとらないと新しい利用者は増えないような気がするんですが、それについてどのように思われますか。","respondent":"辻田児童課長","answer":"来ていない中高生からアンケートをとるというのは、一つ学校を利用してということがあるでしょうけど、実際に一般的な中高生の利用の傾向ですね、何をしてほしいかということは、この中でも十分つかめるかなということで。","voiceIndex":155,"id":"exchange-072"},{"speaker":"山村委員","kind":"提案","question":"ですから、これだけで、児童センターに来ている児童だけで、ほんとうに全体の意見を吸い上げているというふうに誤解しないでいただきたい。それで、先ほど音楽、スポーツ、ものづくりについていろいろ具体的なことを考えているとおっしゃっていたと思うんですが、その具体的な内容を、どのようなことを今後提案していこうと思われているのか、教えていただければと思います。","respondent":"辻田児童課長","answer":"ただ、今回東品川ティーンズプラザのほうにつきましては、中規模館ということもありまして、近隣の関係もあって、スポーツ部分は載せているんですけど、あまり音楽で音がうるさい状況ですと、いろいろ近隣の問題もあると思いますので。","voiceIndex":157,"id":"exchange-073"},{"speaker":"山村委員","kind":"質問","question":"それとあと、夜、特に大きいガラスがあるようなところのビルを見ますと、それを、夜ですから鏡がわりにして、ダンスの練習をしている子がいっぱいいるんですが、こういうの、大きい鏡を壁に張ってあげるだけでいいと思いますので、そういうことをしてあげたほうが私は児童センターを利用する中高生が増えると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-074"},{"speaker":"南委員","kind":"確認","question":"１２４ページのＩＳＯ９００１についてお尋ねをしたいと思います。保育の質の向上がどうされたのか、また、質が向上したという評価はだれがしたのか、答弁では保育関係者や世情から評価された、こういうふうに言われていましたが、本来質の向上をしたというふうに評価するのは、利用者、保護者あるいは子どもではないかというふうに思いますけれども、この点につていも伺います。","respondent":"金子保育課長","answer":"保育の中身の中で、今まで経験的に暗黙の了解としてやったきた手法が、（「同じ答弁だから」と呼ぶ者あり〕同じ質問かと思いましたので、同じように答えておりますが、そういったものが共通認識が細部まで図られることになったということで。","voiceIndex":161,"id":"exchange-075"},{"speaker":"南委員","kind":"質問・要望","question":"私はこれはサービス現況調査、この中であらわれた親たちの保育園に対する質的なサービスを求める声と全く正反対のことを品川区の保育行政はやっているんじゃないかという心配を払拭できないんです。したがって、ＩＳＯが導入されて、保護者たちが求めるサービスの質、ここについて、どういうふうにその願いをクリアしていこうとしているのか、この点について、改めて明確に答弁をしていただきたいと思います。","respondent":"金子保育課長","answer":"第三者評価のことについて例を引いてご指摘いただいているわけですけれど、確認しておきたいのは、第三者評価を実施したのは、平成１２年度が１４園、それから１３年度が全園という形でやってまいりました。","voiceIndex":163,"id":"exchange-076"},{"speaker":"南委員","kind":"質問・要望","question":"時期が違う、しかし、親たちが思っているサービスの質的向上に対して、結果が出ている中で、その後にＩＳＯを導入して質的向上だとおっしゃっているわけですから、どういうふうに質的な向上がされているんですか。ですから、少なくともＩＳＯが必要だというのであれば、こういう働き方をしなくても導入ができるように、人をつけてやるべきではないでしょうか。この点についていかがでしょうか。","respondent":"金子保育課長","answer":"ご指摘のサービス残業２,０００時間、これは全く私どもは存在しないものというふうに認識しておりますので……。","voiceIndex":165,"id":"exchange-077"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうから３点お伺いいたします。そのときに、『しながわやさしいまちガイドマップ』を今年の３月につくられていますので、これにちょっと合わせてお話を聞かせていただきたいと思います。初めに、在宅サービスの件ですが、この中に短期入所、延べ１,４０６日、また中期保護、また緊急一時保護とありますが、この三つの内容をちょっとご説明いただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"これに対しまして、障害者の方の場合、どうしてもやはり短期間ではなくて、もう少し長い期間でお預かりできないかというような要望もありまして、一つの目安としましては３カ月ということで、かなり長い期間お預かりをするという形で、これは大島のほうにめぐみの園ということで。","voiceIndex":168,"id":"exchange-078"},{"speaker":"嶋委員","kind":"質問・要望","question":"実は今回、知的障害のお子さんをお持ちの方たちがＮＰＯを立ち上げて、いろんなお仕事を広げていくという中で、自分の就労のためにお預けする場所がなかなかないというご相談があったものですから、お聞きをしたところですが、このいわゆる短期入所、また中期保護、緊急一時保護に関しても、基本的にどういう理由でお預けをされているのか。","respondent":"日下部障害者福祉課長","answer":"そこで私どもとしましては、平成１４年度から事業を開始いたしましたけれども、障害児の放課後生活サポート事業ということで、児童学園の１室で、そういう障害児のお子さんをお預かりするということで事業を開始しておりますので、そういった事業のご活用もいただければと。","voiceIndex":170,"id":"exchange-079"},{"speaker":"嶋委員","kind":"質問","question":"今の障害児の放課後生活サポート事業も、ＮＰＯが立ち上げているものもあって、夏休みに私も行きましたけども、都立高専の学生さんたちがほんとうにボランティアで一緒に水遊びをしてくれたりする姿を見て、大変うれしいことではあるんですが、ここはやっぱり年齢制限がある程度あるかと思いますが、何歳から何歳までが、この放課後生活サポート事業で見てくださっているのかお聞きかせください。","respondent":"日下部障害者福祉課長","answer":"このやんちゃっこクラブにつきましては、基本的には０歳から１８歳までと。つまり、養護学校を卒業するまでの間のお子さんをお預かりするということでやっております。","voiceIndex":172,"id":"exchange-080"},{"speaker":"嶋委員","kind":"質問・要望","question":"１８歳までですね。そういう意味で、いわゆるＮＰＯで働いてくださっている、またボランティアで頑張っているお母さん方たちに対する、またお子さんに対する区のお考えを聞かせていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"確かにやんちゃっこクラブについては、障害児ということで、１８歳未満ですけれども、ただやはり、先ほど委員からご指摘ございましたように、就労されているお母さん方、親御さんの実情というのは切実なものであるということも、私どもは受けとめておりまして。","voiceIndex":174,"id":"exchange-081"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、よろしくお願いしたいと思います。次に、しながわお休み石の設置ですが、これも大変皆さんご希望が多いと思います。優先順位というのはつけがたいと思うんですが、私が思うには、やはりバスの乗りかえがいろいろなところでありますね。そういう意味で、乗り継ぎのあるバス停には、優先順位をなるべく早くしていただきたいと考えていますが、いかがでしょうか。","respondent":"蓼沼高齢事業課長","answer":"これにつきましては、委員ご指摘のように、バス停における高齢者、あるいは体の弱った方がお休みできるようにということで、バス事業者と協議をして設置場所をある程度優先的に決めて設置をしてきてありますので、今ご指摘のあった場所につきましても。","voiceIndex":176,"id":"exchange-082"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味でも、りんかい線の乗り入れ、また、新幹線乗り入れでたくさんの方が品川区にいらっしゃっているようですので、品川区においても、いろんなところで新しい街づくりといいますか、そういうのをもっと詳しく載せていただきたいと考えていますが、ちょっとご見解を聞かせていただきたいと考えています。","respondent":"早津高齢福祉課長","answer":"ただし、ご指摘いただきましたように、いろいろな表記、それから載せるべき情報等について、まだまだ私どももこれから検討すべきことが多々あるようです。改訂のときには、そのようなことも参考にして行っていきたいというふうに考えてあります。","voiceIndex":178,"id":"exchange-083"},{"speaker":"伊藤委員","kind":"確認","question":"そこでまず確認したいのが、このカレッジで教える内容は最新の介護技術は当然のことだと思うんですが、もう一つ踏み込んで、そういうさまざまな介護の現場でやっていらっしゃる方々に来ていただくわけですから、そういう方々のいろんな心理的な部分でのケアの問題、それから新しく発生してまいりましたこの大きな介護現場での問題についての対処について、カリキュラムも当然対処していくべきと考えますが。","respondent":"山岡保健高齢事業部副参事","answer":"今、ご紹介ありましたように、３コース昨年は実施したものです。それぞれ簡単に内容を説明しますと、まず一つ、ケアマネジメントの初級コースというのがあります。","voiceIndex":181,"id":"exchange-084"},{"speaker":"伊藤委員","kind":"質問","question":"内容についてはある程度勉強しておりますので、私がお伺いしたかったのは、介護の新しい問題が今起こっているわけですね、新聞報道されているように、大沢委員が今朝指摘をしたさまざまな内容。そのことについて、カレッジ教育でどうされているかということをお伺いしましたので、改めてそのことを教えてください。お願いいたします。","respondent":"山岡保健高齢事業部副参事","answer":"受講したものが現場に持ち帰ってですけれども、これにつきましては、その現場の施設、法人、あるいは会社などの方針がありますけれども、それを受けたものがその知識なり技術なりを有効に発揮するような職場環境をつくっていただくように。","voiceIndex":183,"id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問","question":"ただ、私どもが言っておりますのは、この品川福祉カレッジで生かした内容、それから取得した内容等を展開していく、そのことについての対処法をもう少し対応できないでしょうかということをお伺いしておりますので、そのことの答弁をもう一つお願いしたいのと、それから、これも古い話でありますけど、四、五年前に介護の現場で働くヘルパー等のストレスが、長くなればなるほど当然たまってくる。","respondent":"山岡保健高齢事業部副参事","answer":"今年の４月から活動開始しております。この方たち、現在５５人の会員がおりますけれども、この方たちを中心に横のネットワークを張って、受講された方、まだ受講されていない方、この辺の情報の流れをよくするように、現在活動中です。","voiceIndex":185,"id":"exchange-086"},{"speaker":"伊藤委員","kind":"質問","question":"そこで、まずお伺いしたいのが、卒業生がいろんなところで働いておられるわけですから、区内のところだけでも結構ですが、まず卒業生をどういうふうに評価されているかということ、それから、品川区の介護福祉専門学校で勉強して、区内の社会福祉法人等に就職された方が、現場でのいろんな経験、それから苦労、実体験を通して、それを介護福祉専門学校にヒートアップすることがいくらでもできるわけですから。","respondent":"山岡保健高齢事業部副参事","answer":"２点目の卒業生が学校、在学生に何らかの形のフィードバックをですけれども、これは毎年春、概ね５月から６月にかけて就職ガイダンスの一環として、卒業生に来校していただきまして、その体験した仕事の中身、仕事の印象、それからいろいろ抱えている課題。","voiceIndex":187,"id":"exchange-087"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それぞれよろしくお願いいたします。逆に、区内の介護各福祉施設があります。社会福祉法人等があります。ですから、もう一度聞きたいのは、今度は区内介護各福祉施設からの意見、そういうところの意見と、それからあと、そこの客観的な卒業生に対する評価はいかがでしょうかということ、それをぜひこの介護福祉専門学校のカリキュラムに生かしてくださいということをお願いしたいんですが、いかがでしょうか。","respondent":"山岡保健高齢事業部副参事","answer":"いろんな意見をいただいて、これからもできるだけ新しい技術の取り入れも含めて、教育の充実に取り組んでいきたいというふうに考えておりますので、どうぞよろしくお願いします。","voiceIndex":189,"id":"exchange-088"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは開校して、今まで２８１名の卒業生があったということ、それから評価がされているということをお伺いして安心したところもありますし、さらに高めていっていただきますようにお願いしますが、これからのところの中で、当然広く人材を確保しなければいけないわけでありますから、いろいろなところに働かれていると思われますが、広く人材を確保する方法、具体的な方法について教えていただきたいのと。","respondent":"山岡保健高齢事業部副参事","answer":"この辺の改善をする。あるいは、今年から大井町の駅に学校の看板を取りつけたりいたしました。こういったＰＲをやっていきたいというふうに考えております。","voiceIndex":191,"id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問","question":"まとめていきますけど、ぜひ財政効率のよい効果的な経営をお願いしておきます。そういうふうなことをどうバランスをとっていくのかということを、大まかな質問で、時間がないので申しわけないんですけども、そのバランスをどうとっていくのかということを最後にお答えください。お願いいたします。","respondent":"早津高齢福祉課長","answer":"就学資金との関係が大きいかと思います。区内の法人等で就職している者、直近の状態を見ましても、また今後ケアホーム西五反田等が開設されたことから見ましても、２０名強ぐらいの人員が応募されるであろうというふうに考えてあります。","voiceIndex":193,"id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"私のほうからは、１２４ページの保育園運営費とＩＳＯ９００１、それから関連しまして、保育園ＰＴＡについて質問したいと思います。１日目の質疑において、保育園の事業というのはいろいろ拡大してきたと、その中で、職員がどうなっているかというふうに質問いたしました。それが今どういう形に職員が配置されているのか、その現状をまず教えてください。","respondent":"金子保育課長","answer":"保育園にそれぞれ職員を配置するわけですけれども、保育園の中で、まず何歳児に何人の職員を配置するか、これは各園長が判断しますので、一律に私のほうから申し上げられませんけれども、大体において、幼児の部分については、単数担任を基本としつつ、リーダー格を何人か置くと。","voiceIndex":197,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"この人数が、多いところでは１０名ぐらいが定数をオーバーしている、超過定員という形になっているんですけれども、その上で、具体的に年長児で結構ですけれども、大体何人でどういう体制をとられて、各園ごとに違うというふうに言いましても、ある程度は統一されているかと思いますので、どういう体制をとられて、日々の保育に携わっていられるのか、そこを教えてください。","respondent":"金子保育課長","answer":"３歳児については２０対１、４歳・５歳児は３０対１というふうな基準がありますので、この辺をベースに、先ほど申し上げたとおり、各園長が判断して配置しているということですので、個々具体的な一つの園でどう配置しているかというのは、細かいことですので。","voiceIndex":199,"id":"exchange-092"},{"speaker":"西本委員","kind":"意見","question":"今、国基準というのが出ました。大体国基準ですと、５歳児になりますと３０対１というのが決められていると思うんですが、５歳児を３０人、１人で見られると。きめ細かい対応が必要だろうということで、むしろ少人数の単位で見ていくべきであるというようなことを言われていると思うんですが、そこら辺、品川区のお考えを聞かせてください。","respondent":"金子保育課長","answer":"それは一つの園しかないわけでありまして、そういう意味では、２０人以下の園というのが非常にたくさんあります。実態から見まして、私どもは３０人を超えるとか、そういった現状ではないので、心配をする必要はないかなというふうに考えております。","voiceIndex":201,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"それに対して入所率、入所する人数、定員数が非常に少なくなっていますので、それの拡大というのが今後も必要になるかとは思いますけれども、１歳児、２歳児というところも、非常に定員数が大きくなっているというふうに聞いております。今、正規職員とそれから非常勤職員の割合比というのは、どのくらいになっているんですか。それは過去の経緯、推移、そしてどういうふうな変化があるんでしょうか。","respondent":"金子保育課長","answer":"若干過員がおりまして、採用しなかった年がありますから、現員というのは、だんだん減りつつあるというところはあります。一方、非常勤職員の数ですけれど、４００人をやや超えるというふうな数だったと考えています。","voiceIndex":203,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"推移のほうはいかがでしょうか。これは４月の段階というのは、今年の段階のお話なんでしょうか、それとも、平成１４年度の実績をおっしゃっているんでしょうか。できれば、過去からの経緯、平成１３年度でも結構ですけれども、この非常勤の数がどのぐらい、どういうふうな変動をされているのか、そこら辺の動向を教えてください。","respondent":"金子保育課長","answer":"先ほど申し上げたとおり、正規の職員に関しては、定数がずっと変わっていないと申し上げましたけれども、非常勤職員の数は、ちょっと計算はしていないんですけれど、ここのところ、配置の基準等は大きく変えておりませんので。","voiceIndex":205,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、夜間保育もどんどん毎年増えている、それから緊急一時保育のお子さんたちも預かるようになってきた。そうしますと、全体的な職員の子どもに係わる時間といいますか、そういうものについては薄くなっているという感覚なんでしょうか、そこら辺の職員配置、それから保育のやり方、進め方の考え方というのは変化があるんでしょうか、ないんでしょうか、その点をご質問したいと思います。","respondent":"金子保育課長","answer":"ですので、正規職員、非常勤職員、あるいは臨時職員、それから人材派遣という、そういった種類の職員を活用しておりますので、また、日常保育で、例えば非常に手がかかると申しますか、障害児等のお子さんがいて、１人の職員では足りないというときには。","voiceIndex":207,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"今、答弁の中で、人材派遣を使われているというふうにおっしゃいました。人材派遣というのは、ここ数日間の職員費の中でも、そういう項目というのは、私は紹介されてはいないかなと思っているんですが、この人材派遣の考え方ですね、保育園の中に非常勤職員がいて、それから人材派遣がいる、これはどういうふうな考え方で人材派遣というふうにされているんでしょうか。","respondent":"金子保育課長","answer":"この過員の部分についても、やはり正規の職員としての人件費等々かかるわけですから、この部分について工夫ができないかということで、人材派遣、法制度に適合するような形で昨年度から導入しております。","voiceIndex":209,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"要は足りないところの補充という形で人材派遣もあり得るということになったのかなと認識したんですけれども、この人材派遣というのは、今後どういう形で保育園の運営に取り入れていこうという考えなんでしょうか。","respondent":"金子保育課長","answer":"医療職等は現在のところでは人材派遣は適用できないというふうなこともありますので、私どもとしましては、現在のところ、先ほど申し上げた育児休業あるいは病気休暇の部分についてこれを適用していきたいと考えているところです。","voiceIndex":211,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"よくわからないのが、正規職員がいて、非常勤職員がいて、人材派遣がいて、もちろんそれぞれの立場が違うのはわかるんですが、実際子どもたちは一緒ですから、子どもたちにどういう立場で、どういう関係でやっていくのか、この人たちは業務一つから見ると、非常勤職員だからとか、人材派遣だからということでは全く違うということはおかしなわけですから、そこら辺はどういうふうにしていこうと。","respondent":"金子保育課長","answer":"そういう意味では、非常勤職員あるいは人材派遣、臨時職員、こういった人に対してもきちっと位置づけて、園長の指揮下で円滑な運営ができるように努めているところです。","voiceIndex":213,"id":"exchange-099"},{"speaker":"西本委員","kind":"質問・要望","question":"保育園ＰＴＡのほうについて質問したいと思いますが、保育園ＰＴＡなんですが、学校のＰＴＡの組織といいますのは、どちらかというと職員が入っているよりは、父母たち、保護者たちの自主的な活動でかなり運営されているところがあると思うんですが、今後この保育園ＰＴＡに関しては、どういう方向性で開拓をしていこうというふうに思われているか、そのお考えを教えてください。","respondent":"金子保育課長","answer":"保育園ＰＴＡのお尋ねですけれども、このＰＴＡ、学校のＰＴＡを一つのモデルとして考えてきたものですが、これにつきましては、保育園の職員と保護者という形で、それらがほぼ対等な形で構成員として運営していくということで。","voiceIndex":215,"id":"exchange-100"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうところもありますので、やはり小さいころからお世話になっていただいているわけですから、やはり一緒になって保育園をつくっていくんだというところの指導をぜひともしていただきたいと思いますが、最後にお考えを聞いて終わりたいと思います。","respondent":"金子保育課長","answer":"このＰＴＡそのものは、保護者と保育園が連携協力して園児の健全な心身の発達と保育の知識の向上を図るということで、保育園の運営方針に協力するということが一つの方針として掲げてやっておるもので。","voiceIndex":217,"id":"exchange-101"},{"speaker":"木下委員","kind":"質問・要望","question":"２カ所ぐらい、そういう太鼓等をたたける施設を改修でつくったという話も聞いてはおりますけれども、そこら辺でこれからそういう和太鼓ですとか笛ですとか、思いっきり子どもたちが練習する場を与えていただければと思っている次第なんですが、きゅりあんですとか、ああいうところでは太鼓はたたいちゃいけないですし、子どもたちは今タイヤをたたきながら練習しているという現実があるわけですから。","respondent":"辻田児童課長","answer":"そういう中で、この和太鼓、かなり大きな音がします。防音設備を持ったところでないとなかなか練習ができない。もちろん児童センターの中でも、児童センターの子どもたちの活動として、そういう和太鼓の指導をしながら子どもたちの発表の場を設けてやっていく場合もあります。","voiceIndex":220,"id":"exchange-102"},{"speaker":"木下委員","kind":"質問","question":"ほんとうにそういうタイヤですとか太鼓をたたいて練習できる場がないということでの質問ですので、できましたら、ほんとうにバンドぐらいだったらできるような施設でも、やはり和太鼓になりますとものすごく騒音、振動等ありますので、私何カ所かの団体の方にぜひ思い切ってたたける施設があったらいいのにというお話も聞いておりますので、小学校の音楽室で、例えば和太鼓をたたいたにしても。","respondent":"辻田児童課長","answer":"そういう中で、防音設備を持ったようなことも１点考えられるかなということで、今後検討する。ただ、児童センターだけだと、どうしても無理がありますので、全体の施設の中でいろいろ検討していかなければならないと考えております。","voiceIndex":222,"id":"exchange-103"},{"speaker":"木下委員","kind":"質問","question":"一応前向きに考えていただけるということなんですけれども、そういう予算をつけてやっていただけるんでしょうか、いかがでしょうか。","respondent":"辻田児童課長","answer":"現在、新しい児童センター像を求めて、これから取り組んでいくところです。そういう中で、私どものほうもいろいろな選択肢を考えながら事業の充実に努めてまいります。そういう中ですので、すぐに予算をつけるというような形ではございません。ご理解いただきたいと思います。","voiceIndex":224,"id":"exchange-104"},{"speaker":"木下委員","kind":"質問","question":"それについていろいろアンケートや調査なんかをされていらっしゃるかとは思うんですが、実際、社会的弱者、例えば高齢者の方々ですとか、それから、母子家庭ですとか、いろいろなところに調査ですとかやっていらっしゃると思うんですが、その方々の中で大体生活にお困りになっていらっしゃる方はどのぐらいいらっしゃるのか、教えていただければと思います。","respondent":"黒田生活福祉課長","answer":"先ほどもご答弁申し上げましたが、収入が基準を下回る場合ということと、あと体の状態が、健康状態がどうかということで、年齢の若い方で働けないという方はやはり指導をし、どういう状態かというのを継続して見ながら、やはり適正な保護を目指したいと考えています。","voiceIndex":226,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国民健康保険の問題についてお聞きしたいと思います。そこでお聞きしたいんですけど、まず一つは、今年の第１回定例会で国民健康保険料の値上げの条例が通されましたけれども、この間、保険料がどのように変化したのかをお聞かせいただきたいと思うんです。それでもう一つ、続けて聞きます。滞納者がこの間どれくらいなのか。この３年間の人数と主な理由も教えてください。","respondent":"太田保険年金課長","answer":"資格証ですけれども、これは平成１３年の１０月に交付をいたしまして、そのときで４０件、それから平成１４年度の４月で３３件、平成１５年度が９月３０日現在５２件です。","voiceIndex":229,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３００万円、５００万円、７００万の世帯それぞれが、この１０年間で２倍に増えてきたんですね。これでは、ほんとうに滞納者も増えるはずだなというふうに思いますけど、その滞納者に対して、短期証と資格証、こういうことで発行されているわけですけれども、これで収納率が上がったんでしょうか。１０年前の収納率と平成１４年度の収納率がどういうふうになっているのかを教えていただきたいと思います。","respondent":"太田保険年金課長","answer":"収納率の関係ですけれども、１０年前は委員もお持ちかと思いますが、しながわの国保に載ってありますけれども、現年で８９.８５％、平成１４年度は８６.５０％です。","voiceIndex":231,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はこの短期証や資格証になぜなったのか、そして、相談に乗った結果どうだったのかというふうなところをしっかりと記録に残して、この短期証や資格証の人の実態というのをきちんとまとめるというか、調査するということが必要なんじゃないかと思うんですけれども、そのところを一つお聞きしたいと思います。そういうところで、ぜひ実態調査をきちんとつかむべきだと思うんですが、いかがでしょうか。","respondent":"太田保険年金課長","answer":"基本的に分納約束をしていただいて、履行されている方については私どもで郵送をさせていただいていますし、履行ができない方、あるいは何の連絡もない方については、私どもで更新時期、６カ月たった時点で窓口での交付を通じて納付機会を持っている。","voiceIndex":235,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"仕組みについてはよくわかっていますので、説明はしていただかなくても結構です。私は、国民健康保険というのは、だれも皆保険でできているものですから、やっぱり誰もが安心して医療にかかれるようにということでできたものです。そのためにも、国の負担金が、これは１９８４年までは４５％だったものが、３８.５％に引き下げられたままなんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-109"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害関係のほうなんですが、障害をお持ちになったお子さんたち、私どもはどうしてもお会いする機会が多い、また、保護者の方ともいろいろお話をする機会も多い中で、ちょっと質問させていただきたいんですが、品川区の中では聾学校がありますけど、養護学校としては品川区にはない。ですから、今品川第二地区、南品川地区なんですけど、おふろ屋さんが１軒もなくなってしまったのが現状です。","respondent":"日下部障害者福祉課長、蓼沼高齢事業課長","answer":"最初に養護学校に通っていらっしゃる生徒さんの数ですけれども、まず身体障害児の養護学校であります大田区の城南養護学校が２５名、それから港区にあります知的障害児が通っていらっしゃる港養護学校、こちらが８０名ということで。公衆浴場の関係につきまして、私どものほうとしても、所管の健康課のほうとそういった実情について十分情報を得ていきたいというふうに考えてあります。","voiceIndex":239,"id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２点ありがとうあります。４０日ぐらいの、長期の夏季休暇がほんとうに必要なのかなという思いを私は持っております。その家賃の中で部屋を借りると、どうしてもおふろがついていない部屋になってしまうのではないか。だけど、その中で、どう対応していくかという部分をちょっと考えがあったらお答えいただけないでしょうか。","respondent":"日下部障害者福祉課長、黒田生活福祉課長","answer":"実際には今ご質問の中にもございましたように、やんちゃっこクラブで１日の預かりをしたり、あと品川総合福祉センターのほうでもショートステイということでお預かりができるようになっておりますので。やはり、その地域の８割以上の方がおふろがあったりとか、そういういろんなものがありますので、住宅扶助の中でのおふろの対応、金額でおふろをつけるというのはまだまだ難しいところがあります。","voiceIndex":242,"id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺、今後どう対応できるか、もう対応できる場所がないのか、その辺をどう考えていったらいいのかということの質問もまたさせていただきたいと思います。繰り返しになりますけど、確かに民間の問題だからしようがないけれど、その辺の健康面を考えると、担当課長もいらっしゃるので、どう考えたらいいのかなということも一つお答えをいただければと思いますが、よろしくお願いします。","respondent":"日下部障害者福祉課長、田中健康課長","answer":"ただ、あの児童学園の中でスペースをさらに拡大するということは、現実問題無理ということもありますので、何らかの別の方法がとれないものかということで、今後検討を進めていきたいと、このように考えております。区としましては、公衆浴場の設備の整備のための補助ですとか、整備資金のための利子補助ということで、転業あるいは廃業というのを防止して、何とか区民の方の保健衛生の向上にということなんですが、委員からもご指摘のように。","voiceIndex":245,"id":"exchange-112"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これ以上公衆浴場をやると、款が衛生費になるといけないので、そちらのほうはやめるようにします。現在品川区の中で療護施設の入所を希望していらっしゃる方というのはどのぐらいいらっしゃるのか。数だけでいいんですけど、どのぐらいの方が入っていらっしゃるのか、その辺をお答えいただければと思います。","respondent":"日下部障害者福祉課長","answer":"品川区の場合は、実は幸いなことに身体障害者の入所施設、第一さつき園というのがありますので、そちらに１２名、それからそれ以外の残りの７人の方が区外の療護施設、在宅で今入所待ちの方が７名ほどいらっしゃると、そういう状況です。","voiceIndex":248,"id":"exchange-113"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東京都のほうは、たしかこれ以上療護施設等を進めていく方向がないというふうにお聞きしております。品川区として、昨年の第３回定例会ですか、東京都「福祉サービス提供主体の改革への取り組みについて」に関する意見書、これは区議会からも要望しておりますが、これに対して、区側としてどういうふうに考えているか、もう一遍お答えをお願いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"確かに東京都はあまりあてにできない状況になってきておりますけれども、ただ、民間の医療法人なんかが、最近では併設ということで療護施設の建設も徐々に進んできておりますので、何とか７人の方の入所待ちの解消ということで、全力を上げていきたいと。","voiceIndex":250,"id":"exchange-114"},{"speaker":"鈴木（真）委員","kind":"質問","question":"最後にもう一点簡単に。支援費制度によるホームヘルプサービスの水準の低下みたいなものが、先日新聞記事にあったんですけど、品川区のサービス時間の平均が他区と比べ少なかったが、そこら辺がどういう考え方か、時間内にその点だけお聞きして終わりにします。","respondent":"日下部障害者福祉課長","answer":"そういった意味では、時間数が多いところにつきましては、確かにそれだけ障害の程度が重い方がいらっしゃるということなんですが、ただ、これだけをもってサービスの水準を評価することはできないと、このように考えております。","voiceIndex":252,"id":"exchange-115"},{"speaker":"山路委員","kind":"提案","question":"障害者施設授産メニュー開発検討についてですが、私どもも各地を視察いたしまして、この件につきましては、いろんな研究をして提案も含めて予算編成のときにご意見を申し上げたわけですけど、１年間たちまして、今回の成果報告書に２,５００万円の東京都の都支出金がありまして、やられたわけなんですが、この検討状況について、お聞かせいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"ただ、私どもこれは以前にも申し上げましたが、来年の１月に広域斎場がオープンするということで、昨年度の検討につきましては、この広域斎場の開設に合わせた葬祭用品、具体的に申し上げれば、骨壺、その辺の一つの開発を何とか実現したいと。","voiceIndex":255,"id":"exchange-116"},{"speaker":"山路委員","kind":"質問","question":"もう製品もそろそろつくらなければいけない時期に来ているんじゃないかと思いますが、１点目は品川ブランド葬祭用品と今言われました。これらの研究開発ということですが、ＩＴ関連と福祉機器開発についても研究していきたいという強い平成１４年の予算編成のときに決意を述べられているわけなんですが、この辺の検討はどこまで進んでいるでしょうか、お伺いいたします。","respondent":"日下部障害者福祉課長","answer":"実は率直に申し上げまして、最初の段階ではかなりその辺、実は欲張りまして、ＩＴとか福祉機器ということも含めて何とか実現していきたいということでスタートしたんですが、現実問題、もう葬祭用品。","voiceIndex":257,"id":"exchange-117"},{"speaker":"山路委員","kind":"提案","question":"何か随分トーンが落ちたように感じてきているわけなんですが、障害者の方にとって、法内、法外、非常に難しいところはあるんでしょうけど、一つの夢を持っていらっしゃると思うんですね。一つは製品の価格について、もう一点は、働いている方の工賃を上げてもらいたいということをご提案申し上げたんですが、この状況はどういうふうに検討されたか、お聞かせいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"確かにそのとおり夢を持って何とか取り組めるようにということは基本です。具体的に工賃の問題で申し上げますと、この今回の葬祭用品の取り組みにつきましては、通常の授産施設を超えて、福祉工場ということで、これを進めていきたい。","voiceIndex":259,"id":"exchange-118"},{"speaker":"山路委員","kind":"質問・要望","question":"障害者の方も大変希望を持っておりますので、非常に難しい厳しいということは承知しておるわけですが、品川ブランド葬祭用品に間に合うように、どうか頑張っていただきたいと思います。それで、実態はかなりの数だったと思うんですね。どういうふうな状況であったか説明をちょっとしていただけますでしょうか。","respondent":"早津高齢福祉課長","answer":"西五反田の高齢者施設につきましては２種類ありますが、昨日抽選会を行いましたのは、お元気な方のさくらハイツです。１人部屋は３５人が定員ですが、昨日最終的に抽選に参加された方が１８１名ということで、５.１２倍ぐらいです。","voiceIndex":261,"id":"exchange-119"},{"speaker":"山路委員","kind":"質問","question":"ここで私もご紹介していろいろ相談に行ったとき、さくらハイツに当選した方が寝たきりになった場合、ケアホームのほうに移動できるような相談の内容まで細かく調査をされて、それで抽選に臨まれるということで、非常にいいなと思って聞いていたんですね。その辺のことは今回当選した方が先に行けるような対応というのはできているんでしょうか。","respondent":"早津高齢福祉課長","answer":"この具体的なお１人ごとの相談というのは、昨日の抽選を踏まえまして、当選された方の状況、資産、それから家族状況とかを踏まえまして、個別にご相談をし、万一の事態になったときにはケアホームの入所に結びつくようにしていきたいというふうに考えてあります。","voiceIndex":263,"id":"exchange-120"},{"speaker":"山路委員","kind":"質問・要望","question":"調査のときに、いろいろ内容をお聞きになっていらっしゃるので、その方向に高齢者の人が安心して移行できるようにお願いをしておきます。続いて、品川区シルバー人材センター支援事業の新就業システム推進事業についてですが、新聞に掲載されたり、地域の方が相談に行ってあっせんを受けたとか、いろいろ身近に聞くわけですが、現在の実態はどのようになっているか、お聞かせをいただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"サポしながわですけれども、昨年の９月に完全オープンいたしまして、求職登録者の数、それから求人登録者の数、就職決定の実績等、初期の目標といいますか、一定程度の数字を掲げておりましたのをすべてクリアしているという状況でございまして。","voiceIndex":265,"id":"exchange-121"},{"speaker":"山路委員","kind":"意見","question":"全般的に順調にいっているかなと思うんですけど、相談する人は相談しても行きたい仕事がないとか、まだ出発したばかりですので無理かとは思うんですけど、そういう相談も受けますので、その辺のキャパシティーを広げるといいますか、その辺についてはどういうお考えで臨まれているかどうか聞かせてください。","respondent":"蓼沼高齢事業課長","answer":"現在、職員４名体制で事業を実施しておりますけれども、いわばハローワークにないようなきめ細かな求人開拓、電話１本あればその企業にお邪魔して、いろいろご事情を聞くということで、きめ細かなマッチングに心がけております。","voiceIndex":267,"id":"exchange-122"},{"speaker":"山路委員","kind":"質問・要望","question":"高齢者住宅対策事業の住宅あっせんにつきまして、これも何回か質問したんですが、例えば区民住宅とか、高齢者住宅に住んでいまして、入院しますと、どうしても３カ月過ぎますと出なきゃいけない。宅地建物取引業協会であっせんするということなんですが、なかなか悩んでいる方とつながっていかないんですね。その辺についての新しい情報があったらお知らせをいただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"そういう意味では、先般も宅地建物取引業協会品川支部の皆さんと会合を持ちましたけれども、そういう会員の不動産業者の方にとっても、高齢者の方は非常に歓迎するところでもあるので、今後とも活発にあっせんについて連携を密にしていきたいというお話もしていますので。","voiceIndex":269,"id":"exchange-123"},{"speaker":"山路委員","kind":"質問・要望","question":"そういう方が地域でなくなるように、きめ細かな施策をよろしくお願いいたします。１１５ページの高齢者リハビリテーション・システム推進事業につきまして、身近でリハビリができて、非常にいいなと私自身は考えているんですが、どのように推進してこられたか、お聞かせいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"身近でリハビリですが、このご指摘の高齢者リハビリテーション・システム推進事業、こちらでの検討等を踏まえまして、リハビリの重要性等を踏まえまして、新規事業として登場させたのが身近でリハビリです。","voiceIndex":271,"id":"exchange-124"},{"speaker":"山路委員","kind":"質問","question":"これは、どういうリハビリのアドバイスをしているのか、その状況について、ちょっと聞かせていただけますでしょうか。","respondent":"早津高齢福祉課長","answer":"リハビリテーションというのは、そもそもはできない、歩けない、例えば動けないという、できない状態をできるような状態にすることがまずリハビリの基本になるわけですが、若い方ですと、できるようになれば、そのままするようになっていくということであります。","voiceIndex":273,"id":"exchange-125"},{"speaker":"山路委員","kind":"提案","question":"これは一つは行政でもっと考えてもらってもいいんじゃないでしょうかという投げかけと同時に、各自治体で個人で使える時間に格差がある。いろいろこういう質問があるわけなんですが、今後の対応として提案されているんです。チケット制にしたらどうでしょうか。この辺提案されているんですが、今後の対応について、いろいろな方面から研究されていると思いますが、どのようにお考えでしょうか。","respondent":"日下部障害者福祉課長","answer":"視覚障害者のガイドヘルプの問題ですけれども、この支援費制度全体につきましては、私ども比較的スムーズに移行したと考えています。ただ、時間数が少ないということにつきましては、いろいろヒアリングもさせていただきながら、適正な時間を決定しているという経過もあります。","voiceIndex":275,"id":"exchange-126"},{"speaker":"川西委員","kind":"質問・要望","question":"初めに、高齢者の居宅、在宅サービスについて伺います。その前に、平成１４年度介護保険適用人数、そして例えば要介護度４、５、これの人数を教えていただきたい。そして、今最初に申し上げたように、要介護度５の場合、自己負担がありますが、自己負担が、介護保険適用の範囲と、適用外も含めて、実際には最高で今幾らぐらいかかるものだろうかということを伺いたいと思います。","respondent":"早津高齢福祉課長、山岡保健高齢事業部副参事","answer":"身体介護と家事援助の人数ですが、一月の時間数になりますが、身体介護が約１万５,０００時間、それから生活支援のほうが３万３,７００時間ということで、約２倍というような状況です。この３月に品川介護福祉専門学校を卒業した学生の中で、居宅介護関係の事業者に就職した者の数ですが、３名おります。","voiceIndex":278,"id":"exchange-127"},{"speaker":"川西委員","kind":"質問","question":"せっかく学校を持っていて、民間事業者に就職する人がなぜこんなに少ないのか、ちょっと疑問に思います。それは、残念に思います。最近の話ですが、月々幾らかかっているんですかと聞いたら、この方は痰が９０歳を過ぎていますから詰まる。それから、食べるものを全部おかゆにする、そういうような形で２４時間のヘルパーをお願いしている。これを今後どうしていったらいいのか、できるだけ短くお願いします。","respondent":"早津高齢福祉課長","answer":"大変難しいご質問で、的確なお答えというのがちょっと私のほうには用意できないんですけれども、それでよろしゅうありますか。","voiceIndex":281,"id":"exchange-128"},{"speaker":"川西委員","kind":"質問・要望","question":"将来と言わずに、上司、トップに相談をされまして、少しでも来年度の予算の中で見直しの検討を進めていただきたい。それからもう一つ、家庭あんしんセンター、これは大変有意義な品川区の施策として進められております。今、相談を１０月の初めに申し込んで、１１月６日とか７日とかというような混み状況のようですね。この状況というのは、何とか改善をされないのかどうか。","respondent":"辻田児童課長","answer":"相談内容によりましては、要するに混み状況が大変で、そしてその中でいわゆる専門的な方に相談しなければならないという状況もありますので、今なかなか大変だという状況です。西五反田のほうにも新しくできますので、その辺も視野に入れながら改善方を考えていきたいと思います。","voiceIndex":285,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"１１６ページ、高齢福祉費についてと、１２５ページ、生活保護費、そして１１８ページ、介護について簡単にご質問します。高齢者の先ほど虐待ということが出ましたが、ケアができる、一時避難場所というのが品川区に存在するのか。避難保護する場合に、区で強制力を含めて、その方の保護に対して、法的な救済は今できるのでしょうか。ぜひ先進的な品川区として今後の指針をお聞きしたい。","respondent":"早津高齢福祉課長","answer":"強制力ですが、現段階では強制力というところまではないものというふうに考えてあります。","voiceIndex":289,"id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"強制力がないということは、できればほんとうは区としては、行政は放したいけど、無理に連れていくことはできないという考え方でよろしいでしょうか。","respondent":"早津高齢福祉課長","answer":"ご家族との中で、一定のお話をしまして、背景等をいろいろ判断した上でということになりますが、最終的に強制的にというようなことは今のところはできないかというふうに思っています。","voiceIndex":291,"id":"exchange-131"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ、区のほうとしてもできるだけ法的な処置も考えていただいて、そういう方を助けていただきたいと思います。次に、生活保護費についてお聞きします。生活保護者として認定された方に対して、認定後、どのくらいのペースで観察を行っているのか、社会復帰できている状況なのかどうかという、その途中経過、観察ということは非常に大切だと思うんですけど、その辺について期間等お知らせ願いたいと思います。","respondent":"黒田生活福祉課長","answer":"生活保護を開始しまして、その方の処遇方針をまず定めます。それに基づきまして、訪問計画等を立てます。","voiceIndex":293,"id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"今、ちょっと私の質問なんですけど、認定後、どのぐらいのペースで観察をされているのか、例えばそこで認定されまして、今年１月認定されましたと。でも、行くのは、また観察するのは６カ月後なのか、１年後なのか、そういうことはすごく大事なことだと思うんですね。これだけ目まぐるしい社会情勢ですから、途中で復帰しているかもしれない。","respondent":"黒田生活福祉課長","answer":"ただ、その内容によって、いろいろ疑問が出てきますと、その頻度がもう少し増えるという場合もありますし、あと施設等に入ったときには年に１回ということで、高齢者の場合につきましては、ほかの介護保険制度がありますので。","voiceIndex":295,"id":"exchange-133"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ公正を期するという意味でも、３カ月なら３カ月というペースならペースということで、適正に使われていることをぜひ観察していただきたいと思います。次に、介護についてお伺いしたいと思います。今回単年度におきましては、約１,３００万円の赤字ということなんですけど、今後区のほうとしまして、行政のほうとしまして、このままさらに増えていくんでしょうか。","respondent":"早津高齢福祉課長","answer":"今、介護のことでということで、単年度赤字というご指摘ですが、介護保険会計は赤字ではございません。どこかご指摘のところが違っているのかもしれません。申しわけございません。","voiceIndex":297,"id":"exchange-134"},{"speaker":"石田委員","kind":"質問・要望","question":"それからあと、１１６ページ、品川区シルバー人材センター支援事業について、お聞きをしていきたいと思います。ところが、ケースワーカーの人も、それを確かめに行ったりしていることもあるみたいだ、ご努力をされているみたいだ、そういうのも伺っておりますが、今ケースワーカーが３３名いらっしゃる。","respondent":"黒田生活福祉課長","answer":"といいますのは、やはり就労指導していましても、訪問すると、お昼ぐらいに起きてくるとか、下着姿で出てくるとか、そうしますと、本来朝早く起きて、食事して、ハローワーク等に行きなさいと言っても、それができない。","voiceIndex":303,"id":"exchange-135"},{"speaker":"石田委員","kind":"質問","question":"よくよく伺うと、ケースワーカーの方も３３名いらっしゃって、今突然行っているとか、使い方の指導もされている。結構私は以前からそういうのを聞いていたから、そういう努力もされているというのはわかるけれども、ということは、イメージづくりがうまくないのかなとちょっと思っているので、そこら辺の点をどうお考えかちょっと教えてください。","respondent":"黒田生活福祉課長","answer":"そういう方に関しましては、情報がありますと、ケース診断会議等をかけて、どうするかという検討もしています。","voiceIndex":305,"id":"exchange-136"},{"speaker":"石田委員","kind":"意見","question":"私の言い方が悪かったんですが、そのご努力はよくわかっているので、イメージづくりをもっと広く区民の方にこれだけ話が出てきちゃっているから、不正に拠出しているんじゃないかみたいな話がこれだけ出てくるということは、もっとイメージを、今努力されているようなことを何かの方法で知らしめるというのも一つだと思うんだけど、そこら辺のお考えがあったらお聞かせくださいということなんです。","respondent":"黒田生活福祉課長、小沼福祉事業部長","answer":"ただ、民生委員のところでも、こういう情報がありましたらお知らせくださいと。ただ、地域への周知というのがちょっと難しいものがあります。ですから、今ご提案いただいたことも踏まえまして、今後しかるべき方法等については検討していきたい、こう考えてあります。","voiceIndex":307,"id":"exchange-137"},{"speaker":"石田委員","kind":"質問・要望","question":"これは社団法人ですので、中身に入るつもりはありませんが、また別団体で何と言われても私は嫌なものですから、ここの三つの点を品川区として今助成金とかを出しているところで、この三つの数字を伺いますと、この三つの数字を比べると東京都で一番だとか、契約金でいけば第３位ぐらいだなんていう話も伺いますが、この数字を見て、今後どういうふうに今助成金をしているほうの団体として、品川区として。","respondent":"蓼沼高齢事業課長","answer":"そういったことも踏まえつつ、区としてさまざまな事業運営の活性化について具体的には補助金の助成等ありますけれども、さまざまな形で事業活性化に向けてサポートしていきたいというふうに考えてあります。","voiceIndex":310,"id":"exchange-138"},{"speaker":"石田委員","kind":"質問・要望","question":"現実に幾つも私は話を聞いているけれども、金額の問題等でいろいろあるけれども、そうなってくると、余計ある程度自立は自立として、人が増えてきたときには、ある程度公の側面支援がやっぱり必要だと思いますが、さまざま区の中の、事業の中の側面支援をしていくとか、そういう考え方の中で、４対６なのか、これから５対５にしていこうとか、さまざまな側面支援があると思いますが。","respondent":"蓼沼高齢事業課長","answer":"ただ、そうは言いましても、区としても、高齢者の就業機会の拡大、事業の委託等につきましては、その辺の自立という組織理念も念頭に踏まえつつ、仕事の提供あるいは組織運営についてのサポート等。","voiceIndex":312,"id":"exchange-139"},{"speaker":"石田委員","kind":"質問","question":"ぜひバランスをとってうまくやってください。先ほどちょっとご質問あったときに、結構中身のことを答えていたんだけど、私の感覚はシルバー人材センターの事業かなと思っていたんだけど、それだけ最後にちょっとご答弁いただいて、中身に入らないで私はやろうと思ったんだけど、中身に入っちゃっていたなと思ったんだけど、もし私の間違いだったらごめんなさい。","respondent":"蓼沼高齢事業課長","answer":"サポしながわにつきましては、シルバー人材センターと社会福祉協議会の共同の事業です。それを区がバックアップをしているです。","voiceIndex":314,"id":"exchange-140"},{"speaker":"金高委員","kind":"確認","question":"平成１３年度の実質収支が１０億６,５２８万６,６１５円、これは差し引いた単年度収支が８億４,３１２万２,５１８円の赤字という形の表現でありますけど、まずこれを踏まえまして、今回、毎回ですけど、特別委員会に出されております資料でもって、品川区の各会計歳入歳出決算書、あるいは主要施策の成果報告書、また、品川区監査委員から出されております各意見書などがあるわけでありますけど。","respondent":"市岡企画財政課長、南監査委員事務局長","answer":"主要施策の成果報告書および決算書本体は図書館に配布をしています。すみません、監査の意見書については、ちょっと今確認をしています。区立図書館ですね。送付しています。置いてあります。","voiceIndex":317,"id":"exchange-141"},{"speaker":"金高委員","kind":"確認","question":"はい、ありがとうございました。確認をさせていただきましたけれども。","respondent":"南監査委員事務局長","answer":"我々黒字か赤字かと答えを求められたときには、実質収支というもので見るわけですが、そこら辺の計数というのは、それぞれ形式収支なり、単年度収支なりも大いに財政の推移ということでは参考になりますので、それはこういった文書の性格上。","voiceIndex":320,"id":"exchange-142"},{"speaker":"金高委員","kind":"質問","question":"それを踏まえまして、その次の質問に入らせていただきますけれども、同じ国民健康保険の中に、いわゆる一般会計の繰入金として４１億８,４００万４,０００円、これが一般財源のほうから特別会計へということで入っております。","respondent":"太田保険年金課長","answer":"特別会計のお話ですが、まず国民健康保険の財政は基本的に保険料、それから国庫負担、これで賄うべきである、これが原則だと考えています。","voiceIndex":322,"id":"exchange-143"},{"speaker":"金高委員","kind":"意見","question":"品川区でもって徴収された区民税、その中のまた一部がさらに国民健康保険のほうに入ってくるというふうに解釈してよろしいのかどうか。","respondent":"市岡企画財政課長","answer":"区のほうは、これは財調との関係がちょっとありまして、かつては、つまり平成１２年度の都区制度改革前は８分の６を財調で区の負担分については措置をし、残り８分の２については、国民健康保険法で特別区だけは東京都が財源不足を調整するということで、いわゆる府県財源。","voiceIndex":324,"id":"exchange-144"},{"speaker":"金高委員","kind":"質問","question":"次に成果報告書であと一点だけ質問しますけれども、成果報告書の１１６ページ、高齢者クラブの助成金についてお伺いします。１２３クラブが品川区内であるわけでありますけれども、３月３１日に締め切りまして、各高齢者クラブが実際に決算を出し、またその申請書を出すわけでありますけども、助成金を申請する申請書の書き方が非常にわかりにくいという言葉をよく聞くんです。","respondent":"蓼沼高齢事業課長","answer":"基本的に「高齢者クラブ運営の手引き」というようなものがございまして、こちらにそういう申請書の書き方の見本ですとか、具体的なボランティア活動等に何が対象になるかとかお示しをして説明会も開いているところですけれども、わからない点につきましては。","voiceIndex":326,"id":"exchange-145"},{"speaker":"宮崎委員","kind":"質問","question":"私は事項別明細書２００ページ、介護保険について、成果報告書も２００ページについて伺います。今、黒字か赤字かという議論があったんですけども、改めて３年間終わって、基金の積立金は幾らでしょうか。１号被保険者１人当たりに直すと、この基金は幾らになるか、まずお伺いしたいと思います。","respondent":"早津高齢福祉課長","answer":"３年間ということでございまして、１５億７,４００万円余ということになろうかというふうに思います。１号被保険者が５万９,０００人になりますので、それを割った額ということになろうかと思います。","voiceIndex":329,"id":"exchange-146"},{"speaker":"宮崎委員","kind":"質問","question":"私毎年指摘してきましたけど、改めて驚いております。滞納繰越分のところでは１７.７％ということになっておりますが、そもそも普通徴収の方は何人になっているのか伺いたいというふうに思います。国民健康保険と比べてちょっと介護保険のほうの滞納、収納率がちょっと低いんじゃないかと思うんですけど、そこら辺の原因はどうなっているか、お伺いしたいと思います。","respondent":"太田保険年金課長","answer":"繰越分のお話ですけれども、滞納者分の比率が増えてありますのは、委員もご案内かと思いますけども、介護保険は平成１２年度から制度が始まりまして、平成１２年度につきましては、１０月から本来の保険料の２分の１ですので、本来額に比べますと４分の１の保険料額。","voiceIndex":331,"id":"exchange-147"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとちなみに伺いたいんですけども、この滞納理由ですね、先ほどの国民健康保険のところでは、滞納理由、いろいろお話がありましたけれども、ちょっとここの介護保険の普通徴収のところでの滞納理由、これはつかんでおりますか。つかんでいなければ、ちょっと現場のところでの実感等ありましたら、ご説明いただければと思います。","respondent":"太田保険年金課長","answer":"ただ、６５歳以上の方が対象ということで、一つはなかなか連絡がつきにくいということがあります。それともう一点は、連絡がついても、やはり理解をしていただくのに時間がかかるという２点が担当者等を通じて感触です。","voiceIndex":333,"id":"exchange-148"},{"speaker":"宮崎委員","kind":"意見","question":"私、国民健康保険では、経済的理由が滞納のかなりの部分を占めているなというふうに思いましたけれども、介護保険のほうでも、この実態を調査してほしいというふうに思います。これを利用している方が、それでも滞納しているとか、あるいはそもそも対象にならないとか、その辺の滞納している方がせっかく保険料の減額制度があるんだけども、これが実際に使われているかどうか、こういうところはどうでしょう。","respondent":"太田保険年金課長","answer":"減額制度につきましては、私ども４月の段階に仮算定をいたします。そのときに、納入通知書とともに、パンフレットをお出ししています。そのパンフレットの保険料の５段階の表の右横に特別減額制度ということでのＰＲをさせていただいています。","voiceIndex":335,"id":"exchange-149"},{"speaker":"宮崎委員","kind":"質問","question":"私、この制度は収入が８万円というふうになっていますけど、支出については何で考慮されていないのか、ここのところをちょっとお伺いしたいというふうに思いますけれども、支出のところも、私はアパート代等を考慮してほしいというふうに思っているんですが、ここのところはどうでしょうか。要するに、収入と支出のバランスのところで苦しいわけですから、どうでしょうか。","respondent":"太田保険年金課長、早津高齢福祉課長","answer":"１点目のＰＲの件ですけれども、私どもも先ほど申し上げまたしように、丁寧に実施をしています。それから個別の中でもご紹介を申し上げてあります。支出の面をなぜ考慮しないのかですが、支出の面を考慮するというのは非常に難しいことでございまして、収入面で幾らということを判定材料にすると、こういう考え方です。","voiceIndex":337,"id":"exchange-150"},{"speaker":"宮崎委員","kind":"提案","question":"支出をどこまで見るかというのは、確かに難しいと思うんですよね。そこで、私どもがずっと提案しているのは、せめて住宅費、要するにアパート代、家賃ですね、このところで見れば、明確になってくると思うんですよ。こういう中で年金が減っているということですと、収入基準も変えなきゃいけない、こう思いますけれども、いかででしょうか。これはぜひやっていただきたい。","respondent":"早津高齢福祉課長","answer":"ここは何度も議論しているところでありますし、先ほども申し上げましたように、二つの要素、すなわち収入要件と、それから預貯金要件と、こういうものを二つあわせて保険料減額の対象というのが制度の運用方針です。現在のところ、これについて変更する考えはございません。","voiceIndex":340,"id":"exchange-151"},{"speaker":"藤田委員","kind":"質問・要望","question":"私から３点お伺いをいたします。それから第２点目は、車いすの貸し出しなんですが、普通の車いすはかなり皆さん気軽に各施設に行って貸し出しを受けておりますが、電動の車いす、これは今貸し出し用があるのかどうか、その辺をお伺いしたいと思います。それから、これは障害者ではなくて、高齢者のことに絞って今お伺いしています。","respondent":"早津高齢福祉課長、日下部障害者福祉課長","answer":"２点のご質問のうち、まず年賀状、暑中見舞い等の事業目的ですが、ひとり暮らしの高齢者、寝たきりの高齢者に年賀状、暑中見舞い等を送付することによりまして、高齢者の孤独感、病苦を慰めるというものが事業目的に掲げているものです。これにつきましては、大体のスポーツ活動につきましては、生涯学習課のほうが窓口で対応していますけれども、例えば一つには、区立の体育館のほうで水泳教室でありますとか、スポーツ全般にわたってのフリー教室ということで。","voiceIndex":343,"id":"exchange-152"},{"speaker":"藤田委員","kind":"質問","question":"こういうサポートが必要なんだと。そういう実態につきまして、どのようにお考えなのか、お伺いしたいと思います。これは生涯学習課でやっていますよというんじゃなくて、実態的に詳しいのは障害福祉課がつかんでいるわけですから、ぜひタイアップして、障害者福祉課長はスポーツマンですので、その辺、ぜひ音頭をとってやっていただけないかと、このように思うんですけども、いかがでしょうか。","respondent":"早津高齢福祉課長、日下部障害者福祉課長","answer":"手動の車いすと比べまして、かなり重いものですので、万一の事態というのは大変な事故を招きかねるというようなこともありまして、貸し出しについては手動というものに限らせていただいているというのが現在の考え方です。その辺も含めて、これからまた充実についても検討してまいりたいと、このように考えております。","voiceIndex":346,"id":"exchange-153"},{"speaker":"藤田委員","kind":"質問・要望","question":"今、昭和元年に生まれた人は７７歳ですね。もし、品川区だけではちょっとむずかしいなという場合があれば、これは城南５区で、城南５区パラリンピック大会でもいいですから、何か希望が持てるような、そうした途中で例えば障害に遭った方とか、いろんな方たちがいらっしゃいますから、ぜひ希望の持てるような祭典を考えていただけないかなと、この点だけちょっとご答弁いただいて終わります。","respondent":"日下部障害者福祉課長","answer":"ただ、なかなかいろいろ障害によってスポーツが可能な方とか、いろいろ限定されるという状況等もありますので、その辺については今後の一つの検討課題ということで受けとめさせていただきたいというふうに思います。","voiceIndex":349,"id":"exchange-154"},{"speaker":"林（宏）委員","kind":"確認","question":"１９９ページから始まります介護保険の会計というところ全般、一つ、二つ項目で聞きたいと思いますけど、その前に、次世代育成支援に関係するお話が初日から毎日のように出ています。それに関連して確認をしておきたいと思います。いろいろな世代、１８歳までの児童というところで、次世代育成支援対策推進法が政府で決められてきた。ありますよね。じゃあ、それをまず教えてください。","respondent":"中尾根企画部長","answer":"子育て支援策の基本的なコンセプトは五つだと思って認識していますけども、一つは今後、普遍化、多用化していくということを体系づけるというのが一つです。","voiceIndex":352,"id":"exchange-155"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ですから、しっかり１０年のスパンで今言ったいろんな子どもたち、いろんな育ち方をしている、そういう子どもたちのことを考えてやっていただきたい。この中にいろいろ出てくる国庫負担基本額というのが、いわゆるここでは品川区の場合、１０９億８,３００万円強という数字がうたわれているんですけども、この数字が、いわゆる介護保険の給付というふうに考えていいわけですかね。","respondent":"早津高齢福祉課長","answer":"介護保険制度は委員のおっしゃるような負担割合をしておりまして、区からの繰入金もこの基本額の１２.５％です。","voiceIndex":354,"id":"exchange-156"},{"speaker":"林（宏）委員","kind":"確認","question":"赤字は赤字じゃないという説明で、それでわかる人はわかってくれると思いますけども、３年間過ぎて、さっき言ったほんとうは東京都と同じ割合ですから、都の負担金の約１３７億９千万円かが区の負担額なんです。給付の額からいうと。介護保険特別会計には、それだけのお金を入れなきゃ運営できないんですから、事務費だ何だというのが入っている。その辺をきちんとわきまえていますねというのを確認したい。","respondent":"早津高齢福祉課長","answer":"したがいまして、この合わない残額というものは、例えば何かといいますと、職員費、介護保険制度運営に当たる職員費ですとか、それから認定調査費、介護認定に要する調査費でございまして、これらはそれぞれ国と区が応分に負担し合うということが定められておりまして。","voiceIndex":356,"id":"exchange-157"},{"speaker":"林（宏）委員","kind":"確認","question":"これから先、介護保険の責任は自治体にあくまでもあるわけですから、そういうことをきちんとわきまえた上で、お金の出入りもしてほしいと思うし、決算の仕方も我々にきちんと伝わるような決算、繰入金というのは、基本額に対して給付金というのはこれだけ入っているんだ、事務経費はこれだけ入れていくんだ、職員費はこれだけ入れていくんだ、そういうわかるようにしていかないと。","respondent":"市岡企画財政課長","answer":"予算にしても、決算にしても、例えば一般会計繰入金も２０３ページの成果報告書の中では、給付費に対する繰入金と、その他一般会計繰入金として職員給与に充てるもの、それから事務費に充てる繰入金、これらを一応分けて表示をしているつもりです。","voiceIndex":358,"id":"exchange-158"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"これからの介護保険の充実にはサービスの充実というところに来るわけですから、ニーズの多様化に合わせたサービスを市町村として、していかなきゃいけないとなると、よけい会計というのはきちんとしていかないと、あやふやになると、先ほど来言っているように、社会保険だ、国民健康保険だという先の事例に似てくるのを心配しているんで、そういうことのないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":360,"id":"exchange-159"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1216#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":120269,"voices":361}}]);
